def completion_message(completion: Any, context: str = "模型调用") -> Any:
    choices = getattr(completion, "choices", None)
    if not choices:
        raise HTTPException(status_code=500, detail=f"{context}没有返回候选结果。")
    message = getattr(choices[0], "message", None)
    if message is None:
        raise HTTPException(status_code=500, detail=f"{context}返回结果缺少 message。")
    return message


def completion_text(completion: Any, context: str = "模型调用") -> str:
    return str(getattr(completion_message(completion, context), "content", "") or "")


def completion_diagnostics(completion: Any) -> str:
    """Return safe response metadata without logging model content."""
    choices = getattr(completion, "choices", None) or []
    if not choices:
        return "finish_reason=missing, content_chars=0, reasoning_chars=0, tool_calls=0"
    choice = choices[0]
    message = getattr(choice, "message", None)
    content = str(getattr(message, "content", "") or "") if message is not None else ""
    reasoning = str(getattr(message, "reasoning_content", "") or "") if message is not None else ""
    tool_calls = getattr(message, "tool_calls", None) or [] if message is not None else []
    finish_reason = str(getattr(choice, "finish_reason", "") or "unknown")
    return (
        f"finish_reason={finish_reason}, content_chars={len(content)}, "
        f"reasoning_chars={len(reasoning)}, tool_calls={len(tool_calls)}"
    )


def structured_planner_model_options(model: str) -> dict[str, Any]:
    """Favor deterministic JSON output over hidden reasoning for DeepSeek planners."""
    if "deepseek" in str(model or "").lower() or "api.deepseek.com" in VOLCANO_BASE_URL.lower():
        return {"extra_body": {"thinking": {"type": "disabled"}}}
    return {}


def create_chat_completion(client: OpenAI, *, json_object: bool = False, **kwargs: Any) -> Any:
    if not json_object:
        return client.chat.completions.create(**kwargs)
    try:
        return client.chat.completions.create(**kwargs, response_format={"type": "json_object"})
    except Exception as exc:  # noqa: BLE001
        message = str(exc).lower()
        if "response_format" not in message and "json" not in message:
            raise
        return client.chat.completions.create(**kwargs)


def user_facing_exception_detail(exc: Exception) -> str:
    if isinstance(exc, IndexError):
        return "后端处理时遇到空列表或缺失结果，已阻止裸 IndexError。请查看服务日志中的 traceback 定位具体步骤。"
    return str(exc)


