def create_agent_run(question: str, base_stamp: str | None = None) -> AgentRun:
    run_id = f"run-{base_stamp}" if base_stamp else None
    return AGENT_RUNTIME.create_run(question, run_id=run_id)


def execute_skill_command(
    *,
    agent_run: AgentRun | None,
    tool_name: str,
    cmd: list[str],
    cwd: str | Path,
    timeout_seconds: float,
    env: dict[str, str] | None = None,
    resources: ResourceRequest | None = None,
    policy: SandboxPolicy | None = None,
) -> SkillExecutionResult:
    run = agent_run or create_agent_run(f"ad-hoc:{tool_name}")
    request = SkillExecutionRequest(
        run_id=run.run_id,
        tool_name=tool_name,
        command=[str(item) for item in cmd],
        cwd=Path(cwd).expanduser().resolve(),
        env=env or PYTHON_NO_BYTECODE_ENV,
        resources=resources or ResourceRequest(timeout_seconds=timeout_seconds),
        policy=policy or AGENT_RUNTIME.default_policy,
    )
    return AGENT_RUNTIME.execute(run, request)


def record_agentchat_event(agent_run: AgentRun, phase: str, status: str, **payload: Any) -> dict[str, Any]:
    event = {
        "engine": "AutoGen AgentChat",
        "agent": str(payload.pop("agent", "") or "aime_chart_agent"),
        "phase": phase,
        "status": status,
        "runId": agent_run.run_id,
        **payload,
    }
    AGENT_RUNTIME.append_event(agent_run, "agentchat.event", event)
    return event


def source_references_json(references: list[SourceReference]) -> str:
    payload = [
        {
            "siteName": item.site_name,
            "url": item.url,
            "title": item.title,
            "summary": item.summary,
            "iconUrl": item.icon_url,
        }
        for item in references
    ]
    return html.escape(json.dumps(payload, ensure_ascii=False), quote=True)


