def normalized_chat_question(payload: ChatRequest) -> str:
    question = (payload.question or "").strip()
    if question:
        return question
    if payload.images:
        return "请识别图片并整理信息"
    return ""


def route_requires_clarification(route: dict[str, Any]) -> bool:
    value = route.get("requiresClarification", route.get("requires_clarification", False))
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes"}


def route_clarification_question(route: dict[str, Any]) -> str:
    return str(
        route.get("clarificationQuestion")
        or route.get("clarification_question")
        or route.get("reason")
        or "请补充证券的公司名称、上市市场或希望查看的业务指标。"
    ).strip()


def clarification_chat_response_payload(question: str, route: dict[str, Any]) -> dict[str, Any]:
    clarification = route_clarification_question(route)
    return {
        "question": question,
        "code": "",
        "selectedSkill": {
            "key": "clarification",
            "label": "需要补充信息",
            "script": "",
            "reason": str(route.get("reason") or clarification),
        },
        "htmlUrl": "",
        "reportUrl": "",
        "payloadUrl": None,
        "interpretation": clarification,
        "status": ["模型判断当前信息不足，未执行工具"],
        "agentRunId": None,
        "actionLinks": [],
    }


def resolve_explicit_kline_clarification(question: str, route: dict[str, Any]) -> dict[str, Any]:
    """Turn an already actionable native K-line request into an executable plan.

    The model is still allowed to clarify a genuinely ambiguous security identity.
    It must not clarify a period or annotation intent that the K-line contract
    already supports.
    """
    if not route_requires_clarification(route):
        return route
    if str(route.get("_strategy_source") or "") == "model-with-identity-validation":
        return route
    if not explicitly_targets_native_kline_chart(question):
        return route
    code = (infer_symbol_from_question(question) or extract_stock_code(question) or "").strip().upper()
    if not code or code in GENERIC_ROUTE_CODES or not is_business_kline_symbol(code, question):
        return route
    period = explicit_kline_period_from_question(question) or "1d"
    if period not in {"1m", "5m", "15m", "30m", "1h", "2h", "4h", "1d", "1w", "1M", "3M"}:
        return route
    component = ALLOWED_COMPONENTS_BY_FILE.get("kline.py")
    if component is None:
        return route
    updated = dict(route)
    updated["steps"] = [
        {
            "thought": "读取用户指定周期的行情，并在原生 K 线组件内完成技术位置判断与标记。",
            "script": "kline.py",
            "label": component.label,
            "code": code,
            "cli_args": ["--period", period],
            "reason": "标的、K线周期和原生标记意图均已明确，无需再次澄清。",
            "expected_observation": "返回指定周期的 OHLCV、均线、成交量与 MACD，并生成有行情依据的原生标记。",
            "next_thought": "基于可见行情确定候选技术位置并写入 K线标记。",
        }
    ]
    updated["requiresClarification"] = False
    updated["clarificationQuestion"] = ""
    updated["reason"] = "请求信息已足够：直接执行用户指定周期的 K线，并按其买卖点/支撑压力语义生成原生标记。"
    updated["_strategy_source"] = "explicit-kline-policy"
    return updated


