def fallback_external_search_query(question: str) -> str:
    lower = question.lower()
    if "a股" in lower or "沪指" in question or "深成指" in question or "创业板" in question:
        context = market_time_context_for_search(question)
        return f"A股 今日行情 {context['today']} 最近交易日 {context['last_trading_day']} 沪指 深成指 创业板 资金流向 板块 热点 新闻"
    if "美股" in question or "美国股市" in question or any(term in lower for term in ("s&p", "nasdaq", "dow", "wall street")):
        context = market_time_context_for_search(question)
        return f"US stock market today {context['today']} latest trading day {context['last_trading_day']} S&P 500 Nasdaq Dow sectors flows catalysts latest news"
    return external_search_query_for_question(question)


def is_broad_market_question(question: str) -> bool:
    lower = question.lower()
    return (
        any(term in lower for term in ("a股", "大盘", "今日市场", "今天市场", "市场表现"))
        or any(term in question for term in ("沪指", "深成指", "创业板", "上证指数", "上证综指", "美股", "美国股市"))
        or any(term in lower for term in ("stock market", "wall street", "market today"))
    )


@lru_cache(maxsize=128)
def infer_event_window_plan(question: str) -> dict[str, Any]:
    if should_use_yahoo_first_trading_day_policy(question) or should_use_yahoo_monthly_cumulative_policy(question):
        return {"requiresEventWindow": False}
    deterministic = deterministic_event_window_plan(question)
    api_key = (
        model_api_key()
    )
    if not api_key:
        return deterministic or {"requiresEventWindow": False}

    prompt = (
        "你是一个多语言 Agent 任务规划器。判断用户是否在要求“事件窗口时间序列分析”。\n"
        "事件窗口分析的必要工作流是：先确定一组事件及其发生日期，再为每个事件截取某资产在事件后/前后 N 天的数据，"
        "把每条序列按相对日期 day 0..N 对齐，计算累计收益率/价格/涨跌幅等指标，最后绘制多条对齐曲线。\n"
        "如果用户明确要求“当日/当天/同日涨跌幅”和“柱状图/bar chart”，则仍需要先确定事件日期，但 chartType 应为 bar，"
        "metric 应为 event_day_return，windowDays 可为 1；不要把这类问题强制改成 100 天动态折线。\n"
        "事件窗口任务后续调用 yahoo_data.py 时，必须构造 --event-windows-json=[{\"label\":\"事件名\",\"date\":\"YYYY-MM-DD\"},...]；"
        "如果事件日期尚未验证，needsDateLookup=true，reasoningSteps 必须先安排搜索/观察步骤，不能把任务退化成普通累计涨幅。\n"
        "eventDateKind 必须具体描述要抽取的事件日期语义。对于事故/incident/crash/空难/坠机/安全事故，eventDateKind 应为 accident occurrence date，"
        "并明确排除新闻发布日期、调查报告日期、起诉日期、听证日期、航班取消日期、市场交易日期。\n"
        "请根据语义推理，不要做关键词匹配；用户可能用中文、繁体中文、粤语、日文、韩文、泰文、英文等任意语言表达。\n"
        "如果用户只是要求某资产从某年到今天的普通历史趋势线，requiresEventWindow=false。\n"
        "如果用户要求统计某资产/指数在历史日线中“单日/当日/日涨跌幅/daily return”超过或低于某个百分比阈值的日期，requiresEventWindow=false；这些日期是筛选出的交易日，不是需要外部搜索验证的事件发生日。\n"
        "如果用户要求“每个/各个/历任/各任/each”实体在某个事件之后 N 天内的资产表现，通常 requiresEventWindow=true。\n"
        "startYear 必须从用户问题中提取；如果用户说 since/from/ตั้งแต่/以来/以降某一年，就返回该年份，不要默认成 2000。\n"
        "只返回 JSON。\n"
        "Schema: {\n"
        "  \"requiresEventWindow\": true|false,\n"
        "  \"assetSymbol\": \"SPY or empty\",\n"
        "  \"eventSubject\": \"natural language description of event entities\",\n"
        "  \"eventSet\": \"canonical event set if recognizable, e.g. us_presidential_inaugurations_since_2000, otherwise natural language\",\n"
        "  \"eventDateKind\": \"inauguration date / earnings date / policy announcement date / ...\",\n"
        "  \"startYear\": 2000|null,\n"
        "  \"eventCount\": 4|null,\n"
        "  \"windowDays\": 100|null,\n"
        "  \"metric\": \"cumulative_return|close|return_pct|...\",\n"
        "  \"chartType\": \"dynamic_line|line|bar|...\",\n"
        "  \"needsDateLookup\": true|false,\n"
        "  \"reasoningSteps\": [\"short concrete plan step\", \"...\"]\n"
        "}\n"
        "reasoningSteps 必须使用用户问题的语言，并体现可执行的 ReAct 步骤：计划、需要的观察、下一步工具输入。\n\n"
        f"User question: {question}"
    )
    client = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL)
    raw = ""
    for model in [VOLCANO_ROUTER_MODEL, VOLCANO_INTERPRET_MODEL]:
        if not model:
            continue
        try:
            completion = create_chat_completion(
                client,
                json_object=True,
                model=model,
                messages=[{"role": "user", "content": prompt}],
                temperature=0,
                max_tokens=700,
            )
            raw = completion_text(completion, "图表规划模型")
            break
        except Exception:
            continue
    if not raw:
        return deterministic or {"requiresEventWindow": False}
    parsed = parse_json_object(raw)
    if not isinstance(parsed, dict):
        return deterministic or {"requiresEventWindow": False}
    parsed["requiresEventWindow"] = bool(parsed.get("requiresEventWindow"))
    if deterministic and not parsed["requiresEventWindow"]:
        return deterministic
    return parsed


def deterministic_event_window_plan(question: str) -> dict[str, Any] | None:
    lower = question.lower()
    event_terms = (
        "事件",
        "事故",
        "空难",
        "空難",
        "坠机",
        "墜機",
        "财报",
        "財報",
        "业绩",
        "業績",
        "披露",
        "发布",
        "發佈",
        "公布",
        "incident",
        "accident",
        "crash",
        "earnings",
        "results",
        "release",
        "总统",
        "總統",
        "president",
        "presidential",
        "就职",
        "就職",
        "就任",
        "inauguration",
        "inaugural",
    )
    market_metric_terms = (
        "当日涨幅",
        "當日漲幅",
        "当天涨幅",
        "當天漲幅",
        "同日涨幅",
        "同日漲幅",
        "涨幅",
        "漲幅",
        "涨跌幅",
        "漲跌幅",
        "收益率",
        "累计收益率",
        "累計收益率",
        "return",
        "cumulative return",
        "gain",
    )
    chart_terms = ("柱状图", "柱狀圖", "柱形图", "柱形圖", "bar chart", "bar")
    if not any(term in lower or term in question for term in event_terms):
        return None
    if not any(term in lower or term in question for term in market_metric_terms):
        return None
    count_match = re.search(r"(?:最近|近|last|latest)\s*(\d+)", question, flags=re.I)
    event_count = int(count_match.group(1)) if count_match else None
    asset = infer_symbol_from_question(question) or extract_stock_code(question) or ""
    is_event_day_bar = any(term in lower or term in question for term in chart_terms) and any(
        term in lower or term in question for term in ("当日", "當日", "当天", "當天", "同日", "same-day", "same day", "event day")
    )
    is_earnings_event = any(term in lower or term in question for term in ("财报", "財報", "业绩", "業績", "earnings", "results"))
    is_presidential_inauguration = any(term in lower or term in question for term in ("总统", "總統", "president", "presidential")) and any(
        term in lower or term in question for term in ("就职", "就職", "就任", "inauguration", "inaugural")
    )
    if is_presidential_inauguration and not asset and any(term in lower or term in question for term in ("标普", "標普", "s&p", "spx")):
        asset = "^GSPC"
    event_subject = f"{asset or '标的'}财报披露" if is_earnings_event else (
        "美国总统就职" if is_presidential_inauguration else (
        "波音787事故" if ("787" in lower or "波音" in question or "boeing" in lower) else "相关事件"
        )
    )
    event_set = "earnings_releases_from_question" if is_earnings_event else (
        "us_presidential_inaugurations_since_2000" if is_presidential_inauguration else (
        "boeing_787_recent_incidents" if ("787" in lower or "波音" in question or "boeing" in lower) else "event_set_from_question"
        )
    )
    window_days = 1 if is_event_day_bar else 100
    metric = "event_day_return" if is_event_day_bar else "cumulative_return"
    chart_type = "bar" if is_event_day_bar else "dynamic_line"
    final_reasoning_step = (
        "查询标的在每个事件日的行情并计算当日涨跌幅。"
        if is_event_day_bar
        else f"查询标的在每个事件后{window_days}天窗口内的行情，并计算窗口累计收益率曲线。"
    )
    return {
        "requiresEventWindow": True,
        "assetSymbol": asset,
        "eventSubject": event_subject,
        "eventSet": event_set,
        "eventDateKind": "earnings release date" if is_earnings_event else ("presidential inauguration date" if is_presidential_inauguration else "accident/incident occurrence date"),
        "startYear": None,
        "eventCount": event_count,
        "windowDays": window_days,
        "metric": metric,
        "chartType": chart_type,
        "needsDateLookup": True,
        "reasoningSteps": [
            "先搜索并验证每次事件的实际发生日期。",
            "把搜索观察结果总结为 events=[{\"label\":\"事件名\",\"date\":\"YYYY-MM-DD\"}]。",
            "将 events 序列化为 yahoo_data.py 的 --event-windows-json 参数。",
            final_reasoning_step,
        ],
    }


def deterministic_event_window_route(question: str) -> dict[str, Any] | None:
    plan = deterministic_event_window_plan(question)
    if not plan or not plan.get("requiresEventWindow"):
        return None
    asset = str(plan.get("assetSymbol") or infer_symbol_from_question(question) or extract_stock_code(question) or "SPY").strip().upper()
    search_component = ALLOWED_COMPONENTS_BY_FILE.get(EXTERNAL_INFO_SEARCH_SCRIPT)
    yahoo_component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    if not search_component or not yahoo_component:
        return None
    search_query = event_window_search_query(question, plan)
    chart_type = event_window_chart_type_for_question(question, plan)
    metric = "event_day_return" if is_event_day_bar_request(question) else str(plan.get("metric") or "cumulative_return")
    window_days = event_window_days_for_question(question, plan)
    title = build_event_window_title(question, plan, asset)
    return {
        "steps": [
            {
                "thought": "先使用权威事故/事件列表查找实际发生日期，形成可传给 Yahoo 的结构化事件数组。",
                "script": EXTERNAL_INFO_SEARCH_SCRIPT,
                "label": search_component.label,
                "code": asset,
                "cli_args": ["--query", search_query, "--source", "kimi", "--limit", "20", "--max-details", "20"],
                "reason": "模型路由 JSON 不完整时的确定性兜底：事件窗口分析必须先获取事件发生日，不能把新闻发布日期当作事件日期。",
                "expected_observation": "得到按日期排序的事件列表，每条包含 label 和 YYYY-MM-DD 发生日期。",
                "next_thought": "将事件列表序列化为 --event-windows-json 后调用 yahoo_data.py。",
            },
            {
                "thought": "用事件日期查询 BA 在每个事件日或之后第一个交易日的涨跌幅，并渲染柱状图。",
                "script": "yahoo_data.py",
                "label": yahoo_component.label,
                "code": asset,
                "cli_args": [
                    "--metric",
                    metric,
                    "--chart-type",
                    chart_type,
                    "--window-days",
                    str(window_days),
                    "--title",
                    title,
                ],
                "reason": "Yahoo 只在前序搜索 observation 被结构化为 --event-windows-json 后执行。",
                "expected_observation": "每个事件对应一个交易日涨跌幅数据点。",
                "next_thought": "用柱状图展示日期与涨跌幅，并说明事件口径。",
            },
        ],
        "reason": "模型路由输出不完整，已使用确定性事件窗口兜底计划。",
    }


def apply_event_window_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if (
        should_use_yahoo_daily_return_threshold_policy(question)
        or should_use_yahoo_first_trading_day_policy(question)
        or should_use_yahoo_monthly_cumulative_policy(question)
    ):
        return route
    plan = infer_event_window_plan(question)
    if not plan.get("requiresEventWindow"):
        return route
    steps = [step for step in normalize_route_steps(route) if str(step.get("script") or "").strip()]
    component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    search_component = ALLOWED_COMPONENTS_BY_FILE.get(EXTERNAL_INFO_SEARCH_SCRIPT)
    code_component = ALLOWED_COMPONENTS_BY_FILE.get("code_interpreter.py")
    grouped_line_component = ALLOWED_COMPONENTS_BY_FILE.get("group_line.py")
    if not component or not search_component:
        return route
    asset = event_window_asset_code_for_question(question, plan, steps)
    metric = "event_day_return" if is_event_day_bar_request(question) else str(plan.get("metric") or "cumulative_return").strip() or "cumulative_return"
    chart_type = event_window_chart_type_for_question(question, plan)
    window_days = event_window_days_for_question(question, plan)
    title = build_event_window_title(question, plan, asset)
    known_events = event_window_events_from_plan(plan)
    yahoo_cli_args = [
        "--metric",
        metric,
        "--chart-type",
        chart_type,
        "--window-days",
        str(window_days),
        "--title",
        title,
    ]
    if known_events:
        yahoo_cli_args.extend(["--event-windows-json", json.dumps(known_events, ensure_ascii=False)])
    yahoo_step = {
        "script": "yahoo_data.py",
        "label": component.label,
        "code": asset,
        "cli_args": yahoo_cli_args,
        "reason": "Agent 计划判断为事件分析：先确定事件日期，再查询行情并计算用户指定指标，最后按用户要求的图表类型呈现。",
    }
    redundant_visualizers = {
        "yahoo_data.py",
        "code_interpreter.py",
        "line_chart.py",
        "bar_chart.py",
        "grouped_bar.py",
        "bar_line.py",
        "group_line.py",
        *AIME_GENERIC_CHART_SCRIPTS,
    }
    without_yahoo: list[dict[str, Any]] = []
    search_query = event_window_search_query(question, plan)
    explicit_search = explicitly_requested_event_date_search(question)
    has_search_step = bool(known_events) and not explicit_search
    for step in steps:
        script = str(step.get("script") or "")
        if script in redundant_visualizers:
            continue
        if known_events and not explicit_search and script in SEARCH_SCRIPTS:
            continue
        item = dict(step)
        if script == "external_info_search.py" and search_query:
            has_search_step = True
            event_search_args = replace_cli_option_value(list(item.get("cli_args") or []), "--query", search_query)
            if has_cli_option(event_search_args, "--source"):
                event_search_args = replace_cli_option_value(event_search_args, "--source", "kimi")
            else:
                event_search_args.extend(["--source", "kimi"])
            if has_cli_option(event_search_args, "--max-details"):
                event_search_args = replace_cli_option_value(event_search_args, "--max-details", "20")
            else:
                event_search_args.extend(["--max-details", "20"])
            if has_cli_option(event_search_args, "--limit"):
                event_search_args = replace_cli_option_value(event_search_args, "--limit", "20")
            else:
                event_search_args.extend(["--limit", "20"])
            item["cli_args"] = event_search_args
        elif script in SEARCH_SCRIPTS:
            has_search_step = True
        without_yahoo.append(item)
    if not has_search_step:
        without_yahoo.insert(
            0,
            {
                "script": EXTERNAL_INFO_SEARCH_SCRIPT,
                "label": search_component.label,
                "code": "MARKET",
                "cli_args": ["--query", search_query, "--source", "kimi", "--limit", "20", "--max-details", "20"],
                "reason": "事件窗口分析需要先搜索并校验事件实际发生日期，再把结构化事件数组传给 Yahoo。",
                "expected_observation": "可提取为 events=[{label,date}] 的事件发生日期列表。",
            },
        )
    final_steps = [*without_yahoo, yahoo_step]
    if requested_grouped_bar_chart(question) and code_component:
        final_steps.append(
            {
                "script": "code_interpreter.py",
                "label": code_component.label,
                "code": asset,
                "cli_args": ["--chart-type", "grouped-bar", "--title", title, "--question", question],
                "reason": "用户明确要求分组柱状图；Yahoo 负责取事件日多标的涨跌幅，Code Interpreter 负责把结构化 payload 转为 grouped-bar。",
                "expected_observation": "按日期分组、按标的分系列的 grouped-bar chartPayload。",
            }
        )
    if requested_grouped_line_chart(question) and code_component and grouped_line_component:
        final_steps.extend(
            [
                {
                    "script": "code_interpreter.py",
                    "label": code_component.label,
                    "code": asset,
                    "cli_args": ["--chart-type", "grouped-line", "--title", title, "--question", question],
                    "reason": "用户明确要求分组折线图；Yahoo 负责输出每个事件窗口的累计收益率序列，Code Interpreter 负责转换为 group_line.py 的多系列 payload。",
                    "expected_observation": "按相对交易日为 x 轴、按总统/事件为系列的 grouped-line chartPayload。",
                },
                {
                    "script": "group_line.py",
                    "label": grouped_line_component.label,
                    "code": asset,
                    "cli_args": ["--title", title],
                    "reason": "用户明确要求分组折线图，使用 group_line.py 渲染而不是降级为 dynamic_line。",
                    "expected_observation": "生成各总统就职后 100 天累计收益率对比的分组折线图 HTML 与 payload。",
                },
            ]
        )
    updated = dict(route)
    updated["steps"] = final_steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    plan_reason = "; ".join(str(item) for item in (plan.get("reasoningSteps") or [])[:4] if item)
    policy_reason = f"Agent 事件窗口计划：{plan_reason}" if plan_reason else "Agent 已规划为事件窗口分析。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def should_use_presidential_spy_event_window(question: str) -> bool:
    plan = infer_event_window_plan(question)
    if not plan.get("requiresEventWindow"):
        return False
    events = event_window_events_from_plan(plan)
    return bool(events)


def explicitly_requested_event_date_search(question: str) -> bool:
    text = str(question or "")
    lower = text.lower()
    if has_explicit_google_search_intent(text):
        return True
    explicit_evidence_terms = (
        "网页",
        "網站",
        "网站",
        "来源",
        "來源",
        "引用",
        "出处",
        "出處",
        "核验",
        "核實",
        "验证",
        "驗證",
        "联网搜索",
        "全网",
        "全網",
        "google",
        "web search",
        "search online",
        "official source",
        "source link",
    )
    return any(term in lower for term in explicit_evidence_terms)


def event_window_asset_code_for_question(question: str, plan: dict[str, Any], steps: list[dict[str, Any]]) -> str:
    def split_symbols(value: str) -> list[str]:
        return [
            symbol
            for symbol in re.split(r"[,，;；/、\s]+", str(value or "").upper())
            if re.fullmatch(r"[A-Z0-9][A-Z0-9.\-]{0,14}", symbol)
        ]

    for step in steps:
        code = str(step.get("code") or "").strip().upper()
        if "," in code:
            symbols = split_symbols(code)
            if len(symbols) >= 2:
                return ",".join(dict.fromkeys(symbols))
    asset = str(plan.get("assetSymbol") or infer_symbol_from_question(question) or extract_stock_code(question) or "SPY").strip().upper()
    symbols = infer_symbols_from_question(question)
    if requested_grouped_bar_chart(question):
        for symbol in reversed(split_symbols(asset)):
            if symbol not in symbols:
                symbols.insert(0, symbol)
        if "spy" in question.lower() and "SPY" not in symbols:
            symbols.append("SPY")
        deduped = [symbol for symbol in dict.fromkeys(symbols) if symbol]
        if len(deduped) >= 2:
            return ",".join(deduped)
    return asset


def build_event_window_title(question: str, plan: dict[str, Any], asset: str) -> str:
    event_subject = str(plan.get("eventSubject") or plan.get("eventSet") or "事件").strip()
    event_set = str(plan.get("eventSet") or "").lower()
    window_days = event_window_days_for_question(question, plan)
    html_lang = html_lang_for_question(question)
    if is_event_day_bar_request(question):
        if html_lang == "ja":
            return f"{event_subject}当日の{asset}騰落率"
        if html_lang == "th":
            subject = event_subject if re.search(r"[\u0e00-\u0e7f]", event_subject) else "เหตุการณ์ที่เกี่ยวข้อง"
            return f"{asset} ผลตอบแทนวันเกิดเหตุของ{subject}"
        if html_lang == "en":
            return f"{asset} same-day return after {event_subject}"
        if html_lang == "zh-Hant":
            return to_traditional_chinese(f"{event_subject}当日{asset}涨跌幅")
        return f"{event_subject}当日{asset}涨跌幅"
    metric = {
        "ja": "累積収益率",
        "zh-Hant": "累計收益率",
        "zh-CN": "累计收益率",
        "th": "ผลตอบแทนสะสม",
    }.get(html_lang, "cumulative return")
    if html_lang == "ja":
        return f"{event_subject}後{window_days}日間の{asset} {metric}"
    if html_lang == "th":
        subject = "เข้ารับตำแหน่งประธานาธิบดีสหรัฐฯ" if "president" in event_set or "presidential" in event_set or "ประธานาธิบดี" in event_subject else event_subject
        if not re.search(r"[\u0e00-\u0e7f]", subject):
            subject = "เหตุการณ์ที่เกี่ยวข้อง"
        return f"{asset} {metric} ใน {window_days} วันแรกหลัง{subject}"
    if html_lang == "en":
        return f"{asset} {metric} in {window_days} days after {event_subject}"
    if html_lang == "zh-Hant":
        return to_traditional_chinese(f"{event_subject}後{window_days}日內{asset}{metric}")
    return f"{event_subject}后{window_days}日内{asset}{metric}"


def is_event_day_bar_request(question: str) -> bool:
    lower = question.lower()
    event_day_terms = (
        "当日",
        "当天",
        "同日",
        "首日",
        "当天涨幅",
        "当日涨幅",
        "same-day",
        "same day",
        "day 0",
        "event day",
    )
    bar_terms = ("柱状图", "柱形图", "bar chart", "bar")
    return any(term in lower for term in event_day_terms) and any(term in lower for term in bar_terms)


def event_window_chart_type_for_question(question: str, plan: dict[str, Any]) -> str:
    if is_event_day_bar_request(question):
        return "bar"
    chart_type = str(plan.get("chartType") or "dynamic_line").strip() or "dynamic_line"
    if chart_type == "line":
        return "dynamic_line"
    if chart_type not in {"dynamic_line", "bar"}:
        return "dynamic_line"
    return chart_type


def event_window_days_for_question(question: str, plan: dict[str, Any]) -> int:
    if is_event_day_bar_request(question):
        return 1
    return int(to_float(plan.get("windowDays")) or 100)


def filter_event_windows_by_plan(events: list[dict[str, str]], plan: dict[str, Any]) -> list[dict[str, str]]:
    start_year = int(to_float(plan.get("startYear")) or 0)
    end_year = int(to_float(plan.get("endYear")) or 0)
    filtered: list[dict[str, str]] = []
    for event in events:
        date = str(event.get("date") or "")
        year = int(date[:4]) if re.fullmatch(r"\d{4}-\d{2}-\d{2}", date) else 0
        if start_year and year and year < start_year:
            continue
        if end_year and year and year > end_year:
            continue
        filtered.append(event)
    return filtered


def event_window_events_from_plan(plan: dict[str, Any]) -> list[dict[str, str]]:
    explicit = plan.get("events")
    if isinstance(explicit, list):
        events: list[dict[str, str]] = []
        for item in explicit:
            if not isinstance(item, dict):
                continue
            label = str(item.get("label") or item.get("name") or "").strip()
            date = str(item.get("date") or item.get("eventDate") or "").strip()
            if label and re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
                events.append({"label": label, "date": date})
        if events:
            return limit_event_windows_by_plan(filter_event_windows_by_plan(events, plan), plan)

    event_set = str(plan.get("eventSet") or plan.get("eventSubject") or "").lower()
    date_kind = str(plan.get("eventDateKind") or "").lower()
    is_presidential = any(
        token in event_set
        for token in ("president", "presidential", "大統領", "总统", "總統", "ประธานาธิบดี")
    )
    is_inauguration = (
        "inaug" in date_kind
        or "就" in date_kind
        or "任" in date_kind
        or "เข้ารับตำแหน่ง" in date_kind
        or "สาบาน" in date_kind
        or not date_kind
    )
    if is_presidential and is_inauguration:
        return limit_event_windows_by_plan(filter_event_windows_by_plan(presidential_inauguration_events_since_2000(), plan), plan)
    return []


def limit_event_windows_by_plan(events: list[dict[str, str]], plan: dict[str, Any]) -> list[dict[str, str]]:
    event_count = int(to_float(plan.get("eventCount")) or 0)
    if event_count > 0:
        return events[:event_count]
    return events


def event_window_observation_context(previous_runs: list[ModuleRun]) -> str:
    blocks: list[str] = []
    for run in previous_runs:
        if run.selected.filename not in SEARCH_SCRIPTS:
            continue
        payload = read_payload_value(run.payload_path)
        direct_answer = ""
        if isinstance(payload, list):
            articles = payload
            query = ""
        elif isinstance(payload, dict):
            articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
            query = str(payload.get("query") or "")
            direct_answer = str(payload.get("answer") or "").strip()
        else:
            articles = []
            query = ""
            direct_answer = ""
        if direct_answer:
            blocks.append(f"Kimi final search answer from {run.selected.filename}, query={query}:")
            blocks.append(plain_text_excerpt(direct_answer, limit=6000))
        if not articles:
            continue
        blocks.append(f"Search observation from {run.selected.filename}, query={query}:")
        for index, item in enumerate(articles[:8], start=1):
            if not isinstance(item, dict):
                continue
            title = plain_text_excerpt(str(item.get("title") or ""), limit=180)
            source = plain_text_excerpt(str(item.get("source") or ""), limit=80)
            url = plain_text_excerpt(str(item.get("url") or ""), limit=180)
            body = plain_text_excerpt(str(item.get("content_text") or ""), limit=1200)
            summary = plain_text_excerpt(str(item.get("summary") or ""), limit=360)
            text = body or summary
            if body and summary and summary not in body:
                text = f"{body} Summary snippet: {summary}"
            blocks.append(f"{index}. source={source}; title={title}; url={url}; text={text}")
    return "\n".join(blocks)[:12000]


def extract_event_windows_from_observations(
    question: str,
    plan: dict[str, Any],
    previous_runs: list[ModuleRun],
) -> list[dict[str, str]]:
    structured_events = extract_structured_event_windows_from_observations(plan, previous_runs)
    if structured_events:
        return structured_events
    context = event_window_observation_context(previous_runs)
    if not context:
        return []
    api_key = model_api_key()
    if not api_key:
        return []
    event_count = int(to_float(plan.get("eventCount")) or 0)
    count_clause = (
        f"Return exactly the {event_count} most relevant events if the evidence supports them. "
        if event_count > 0
        else "Return only the relevant events needed by the user's question. "
    )
    prompt = (
        "You are the observation step in a ReAct financial-analysis agent.\n"
        "The user needs an event-window chart. Extract concrete event dates from the search observations so the next market-data tool can run.\n"
        "Use only the observation text below. If a date cannot be supported, do not invent it.\n"
        f"{count_clause}"
        "If the observation contains a structured Aviation Safety Network accident/incident table with lines like "
        "'date=YYYY-MM-DD; label=...', prefer those rows over news articles, sort them by date descending for 'recent/latest' requests, "
        "and return the requested number of rows if available. These ASN date fields are accident/incident occurrence dates.\n"
        "The date must match the plan's eventDateKind. Do not use irrelevant report publication dates, article dates, investigation-report dates, page update dates, or stock-price dates as event dates.\n"
        "Important exception: for earnings release / financial results disclosure tasks, an investor-relations, newsroom, GlobeNewswire, PR Newswire, SEC/newswire, or earnings-calendar item titled like 'Announces Financial Results' or 'reports earnings' may use its published_date as the actual disclosure/release date, because the publication is the event.\n"
        "For accident/incident/crash tasks, use the accident or incident occurrence date only. "
        "Reject dates that refer to black-box searches, investigation updates, final/preliminary reports, lawsuits, hearings, safety reviews, flight cancellations, article publication, or market movement. "
        "A title like 'crash probe', 'black box found', 'families sued', or 'report delayed' is not by itself evidence of the crash date. "
        "Only include an event if the observation text directly supports when the crash/incident happened. "
        "If fewer than the requested count are supported, return only the supported events and explain the shortage in observation; do not pad with article dates.\n"
        "Transform the search observations into a Yahoo-ready structure, not a prose summary. "
        "The canonical output field is events, and it must be directly serializable as the yahoo_data.py --event-windows-json value. "
        "Each events item must contain only a short label and a YYYY-MM-DD date for the actual event occurrence; evidence/source fields may explain why, but yahoo_data.py will consume label/date. "
        "Do not include raw articles, article publication dates, snippets without occurrence dates, or inferred dates in events.\n"
        "For same-day/event-day return bar charts, also include a yahooCliArgs field showing the exact intended CLI fragment: "
        "[\"--metric\",\"event_day_return\",\"--chart-type\",\"bar\",\"--window-days\",\"1\",\"--event-windows-json\",\"<events JSON string>\"]. "
        "This yahooCliArgs field is a planning checksum; events remains the source of truth.\n"
        "The returned events will be passed verbatim to yahoo_data.py as --event-windows-json, so every date must be safe to use as a market event date.\n"
        "Normalize dates to YYYY-MM-DD. Labels should be short, human-readable event names in the user's language when possible.\n"
        "Return JSON only: {\"events\":[{\"label\":\"...\",\"date\":\"YYYY-MM-DD\",\"dateType\":\"actual_occurrence_date\",\"evidence\":\"short source phrase\",\"sourceUrl\":\"...\"}],\"yahooCliArgs\":[\"--metric\",\"event_day_return\",\"--chart-type\",\"bar\",\"--window-days\",\"1\",\"--event-windows-json\",\"[...]\"],\"observation\":\"short note\"}.\n\n"
        f"User question: {question}\n"
        f"Structured plan: {json.dumps(plan, ensure_ascii=False)}\n\n"
        f"Search observations:\n{context}"
    )
    try:
        completion = create_chat_completion(
            OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL),
            json_object=True,
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
            max_tokens=900,
        )
    except Exception:
        return []
    parsed = parse_json_object(completion_text(completion, "图表规划模型"))
    raw_events = parsed.get("events") if isinstance(parsed, dict) else None
    if not isinstance(raw_events, list):
        return []
    events: list[dict[str, str]] = []
    for item in raw_events:
        if not isinstance(item, dict):
            continue
        label = str(item.get("label") or item.get("name") or "").strip()
        date = str(item.get("date") or item.get("eventDate") or "").strip()
        if label and re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
            events.append({"label": label, "date": date})
    events = filter_event_windows_by_plan(events, plan)
    if event_count > 0:
        events = events[:event_count]
    return events


def extract_structured_event_windows_from_observations(
    plan: dict[str, Any],
    previous_runs: list[ModuleRun],
) -> list[dict[str, str]]:
    event_count = int(to_float(plan.get("eventCount")) or 0)
    events: list[dict[str, str]] = []
    date_kind = str(plan.get("eventDateKind") or "").lower()
    event_set = str(plan.get("eventSet") or plan.get("eventSubject") or "").lower()
    is_earnings = any(token in f"{date_kind} {event_set}" for token in ("earnings", "financial results", "财报", "財報", "业绩", "業績"))
    for run in previous_runs:
        if run.selected.filename not in SEARCH_SCRIPTS:
            continue
        payload = read_payload_value(run.payload_path)
        if isinstance(payload, list):
            articles = payload
        elif isinstance(payload, dict) and isinstance(payload.get("articles"), list):
            articles = payload.get("articles") or []
        else:
            articles = []
        for item in articles:
            if not isinstance(item, dict):
                continue
            source = str(item.get("source") or "")
            title = str(item.get("title") or "")
            text = str(item.get("content_text") or item.get("summary") or "")
            if is_earnings:
                event = extract_earnings_release_event_from_article(item)
                if event:
                    events.append(event)
                    continue
            if "Aviation Safety Network" in source or "Aviation Safety Network Boeing 787" in text:
                for match in re.finditer(r"\bdate=(\d{4}-\d{2}-\d{2})\b;\s*label=([^;]+)", text):
                    date = match.group(1)
                    label = match.group(2).strip()
                    if label and re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
                        events.append({"label": label, "date": date})
    deduped: dict[tuple[str, ...], dict[str, str]] = {}
    for event in events:
        key = (event["date"],) if is_earnings else (event["label"], event["date"])
        deduped.setdefault(key, event)
    sorted_events = sorted(deduped.values(), key=lambda item: item["date"], reverse=True)
    filtered = filter_event_windows_by_plan(sorted_events, plan)
    if event_count > 0:
        filtered = filtered[:event_count]
    return filtered


def extract_earnings_release_event_from_article(item: dict[str, Any]) -> dict[str, str] | None:
    title = str(item.get("title") or "").strip()
    source = str(item.get("source") or "").strip()
    title_lower = title.lower()
    source_lower = source.lower()
    if not title:
        return None
    if any(token in title_lower for token in ("conference call", "to discuss", "reminder", "scheduled")):
        return None
    release_title = (
        ("financial results" in title_lower and any(token in title_lower for token in ("announces", "reports", "quarter", "fiscal")))
        or ("earnings" in title_lower and any(token in title_lower for token in ("reports", "report", "released", "release", "announces", "results")))
    )
    trusted_release_source = any(
        token in source_lower
        for token in ("newsroom", "investor", "globenewswire", "pr newswire", "business wire", "yahoo finance", "marketwatch", "investing.com")
    )
    if not release_title:
        return None
    if not trusted_release_source and "financial results" not in title_lower:
        return None
    raw_date = str(item.get("published_date") or item.get("published_at") or item.get("date") or "").strip()
    date = normalize_observation_date(raw_date)
    if not date:
        return None
    label = re.sub(r"\s*[-|]\s*[^-|]+$", "", title).strip() or title
    return {"label": plain_text_excerpt(label, limit=72), "date": date}


def normalize_observation_date(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    iso_match = re.search(r"\b(\d{4}-\d{2}-\d{2})\b", raw)
    if iso_match:
        return iso_match.group(1)
    try:
        parsed = parsedate_to_datetime(raw)
        if parsed:
            return parsed.date().isoformat()
    except Exception:
        pass
    month_match = re.search(
        r"\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?\s+(\d{1,2}),\s*(\d{4})\b",
        raw,
        flags=re.I,
    )
    if month_match:
        month_names = {
            "jan": 1,
            "feb": 2,
            "mar": 3,
            "apr": 4,
            "may": 5,
            "jun": 6,
            "jul": 7,
            "aug": 8,
            "sep": 9,
            "sept": 9,
            "oct": 10,
            "nov": 11,
            "dec": 12,
        }
        month_key = month_match.group(1).lower().rstrip(".")[:4]
        if month_key == "sept":
            month_key = "sept"
        else:
            month_key = month_key[:3]
        month = month_names.get(month_key)
        if month:
            return dt.date(int(month_match.group(3)), month, int(month_match.group(2))).isoformat()
    return ""


def has_cli_arg(cli_args: list[Any], name: str) -> bool:
    return any(str(item) == name for item in cli_args)


def normalize_threshold_yahoo_args(
    selected: SkillScript,
    code: str,
    cli_args: list[Any],
    question: str,
) -> tuple[str, list[Any]]:
    args = [str(item) for item in cli_args]
    if selected.filename != "yahoo_data.py" or not should_use_yahoo_daily_return_threshold_policy(question):
        return code, args
    primary_code = (
        infer_symbol_from_question(question)
        or extract_stock_code(question)
        or str(code or "").split(",", 1)[0].strip()
        or code
    )
    args = remove_cli_option(args, {"--symbols"})
    args = replace_cli_option(args, "--metric", "return_pct")
    args = replace_cli_option(args, "--interval", "1d")
    args = replace_cli_option(args, "--range", infer_yahoo_range_from_question(question))
    args = replace_cli_option(args, "--chart-type", "bar")
    if not has_cli_option(args, "--title"):
        args.extend(["--title", f"{primary_code} 日涨跌幅"])
    return primary_code, args


def normalize_event_day_yahoo_code_and_title(
    selected: SkillScript,
    code: str,
    cli_args: list[Any],
    question: str,
) -> tuple[str, list[Any]]:
    args = list(cli_args)
    if selected.filename != "yahoo_data.py" or not has_cli_arg(args, "--event-windows-json"):
        return code, args
    if requested_grouped_bar_chart(question):
        return code, args
    if "," not in code:
        return code, args
    primary_code = code.split(",", 1)[0].strip() or code
    title = value_after_option([str(item) for item in args], "--title")
    if title and code in title:
        args = replace_cli_option_value([str(item) for item in args], "--title", title.replace(code, primary_code))
    return primary_code, args


def normalize_yahoo_chart_type_args(selected: SkillScript, cli_args: list[Any]) -> list[str]:
    args = [str(item) for item in cli_args]
    if selected.filename != "yahoo_data.py":
        return args
    raw_chart_type = value_after_option(args, "--chart-type")
    if not raw_chart_type:
        return args
    value = str(raw_chart_type).strip()
    normalized = value.lower().replace("-", "_").replace(" ", "_")
    if normalized in {"line", "bar", "dynamic_line"}:
        canonical = normalized
    elif normalized in {"dynamicline", "dynamic"}:
        canonical = "dynamic_line"
    elif normalized in {"group_line", "grouped_line", "multi_line", "groupedline"}:
        canonical = "dynamic_line"
    elif normalized in {"bar_chart", "column", "column_chart"}:
        canonical = "bar"
    elif normalized in {"grouped_bar", "group_bar", "bar_line", "column_line", "combo"}:
        canonical = "bar" if has_cli_arg(args, "--event-windows-json") else "line"
    else:
        canonical = "line"
    if canonical == value:
        return args
    return replace_cli_option(args, "--chart-type", canonical)


def selected_requires_event_windows(selected: SkillScript, question: str) -> bool:
    if (
        should_use_yahoo_daily_return_threshold_policy(question)
        or should_use_yahoo_first_trading_day_policy(question)
        or should_use_yahoo_monthly_cumulative_policy(question)
    ):
        return False
    return selected.filename == "yahoo_data.py" and bool(infer_event_window_plan(question).get("requiresEventWindow"))


def enrich_cli_args_from_react_observations(
    selected: SkillScript,
    cli_args: list[Any],
    question: str,
    previous_runs: list[ModuleRun],
) -> list[Any]:
    args = list(cli_args)
    plan = infer_event_window_plan(question)
    if selected.filename != "yahoo_data.py" or not plan.get("requiresEventWindow"):
        return args
    events = event_window_events_from_plan(plan)
    if not events:
        events = extract_event_windows_from_observations(question, plan, previous_runs)
    if not events:
        return args
    if not has_cli_arg(args, "--event-windows-json"):
        args.extend(["--event-windows-json", json.dumps(events, ensure_ascii=False)])
    if not has_cli_arg(args, "--window-days"):
        args.extend(["--window-days", str(event_window_days_for_question(question, plan))])
    if "--range" in args:
        index = args.index("--range")
        if index + 1 < len(args):
            args[index + 1] = "max"
    else:
        args.extend(["--range", "max"])
    if "--interval" in args:
        index = args.index("--interval")
        if index + 1 < len(args):
            args[index + 1] = "1d"
    else:
        args.extend(["--interval", "1d"])
    chart_type = event_window_chart_type_for_question(question, plan)
    if "--chart-type" in args:
        index = args.index("--chart-type")
        if index + 1 < len(args):
            args[index + 1] = chart_type
    else:
        args.extend(["--chart-type", chart_type])
    if is_event_day_bar_request(question):
        if "--metric" in args:
            index = args.index("--metric")
            if index + 1 < len(args):
                args[index + 1] = "event_day_return"
        else:
            args.extend(["--metric", "event_day_return"])
    return args


def auto_fill_event_window_args_if_needed(
    selected: SkillScript,
    cli_args: list[Any],
    question: str,
    previous_runs: list[ModuleRun],
    base_stamp: str,
    index: int,
) -> list[Any]:
    args = list(cli_args)
    if not selected_requires_event_windows(selected, question) or has_cli_arg(args, "--event-windows-json"):
        return args

    plan = infer_event_window_plan(question)
    if not plan.get("requiresEventWindow"):
        return args

    enriched = enrich_cli_args_from_react_observations(selected, args, question, previous_runs)
    if has_cli_arg(enriched, "--event-windows-json"):
        return enriched

    search_component = ALLOWED_COMPONENTS_BY_FILE.get(EXTERNAL_INFO_SEARCH_SCRIPT)
    if not search_component:
        return args

    GENERATED_DIR.mkdir(parents=True, exist_ok=True)
    search_selected = SkillScript(
        key=Path(EXTERNAL_INFO_SEARCH_SCRIPT).stem,
        label=search_component.label,
        filename=EXTERNAL_INFO_SEARCH_SCRIPT,
        reason="自动补齐事件窗口所需的事件发生日期。",
    )
    search_args = [
        "--query",
        event_window_search_query(question, plan),
        "--source",
        "kimi",
        "--limit",
        "8",
        "--max-details",
        "8",
    ]
    safe_stamp = f"{base_stamp}-{index}-auto-event-search"
    html_path = GENERATED_DIR / f"{safe_stamp}.html"
    payload_path = GENERATED_DIR / f"{safe_stamp}.json"
    try:
        run_skill_script(search_selected, "MARKET", html_path, payload_path, search_args, question)
    except Exception as exc:  # noqa: BLE001
        print(f"Auto event-date search failed: {exc}", file=sys.stderr)
        return args

    search_run = ModuleRun(
        selected=search_selected,
        code="MARKET",
        html_path=html_path,
        payload_path=payload_path,
        route={"script": EXTERNAL_INFO_SEARCH_SCRIPT, "cli_args": search_args},
    )
    return enrich_cli_args_from_react_observations(selected, args, question, [*previous_runs, search_run])


