def event_window_search_query(question: str, plan: dict[str, Any]) -> str:
    lower_question = question.lower()
    event_set = str(plan.get("eventSet") or plan.get("eventSubject") or "").lower()
    date_kind = str(plan.get("eventDateKind") or "").lower()
    if any(token in event_set for token in ("president", "presidential", "总统", "總統")) or "inaug" in date_kind:
        start_year = int(to_float(plan.get("startYear")) or 2000)
        return f"US presidents since {start_year} inauguration dates list"
    if ("787" in lower_question or "boeing" in lower_question or "波音" in lower_question) and any(
        term in lower_question for term in ("事故", "空难", "incident", "accident", "crash")
    ):
        return "Boeing 787 Dreamliner accidents incidents dates Air India Flight 171 battery fire"
    if any(term in lower_question or term in question for term in ("earnings", "financial results", "财报", "財報", "业绩", "業績", "披露")):
        asset = str(plan.get("assetSymbol") or infer_symbol_from_question(question) or extract_stock_code(question) or "").strip().upper()
        subject = str(plan.get("eventSubject") or "").strip()
        entity = asset or subject or question
        return f"{entity} quarterly earnings release dates financial results investor relations"
    api_key = model_api_key()
    fallback_parts = [
        str(plan.get("eventSubject") or "").strip(),
        str(plan.get("eventDateKind") or "").strip(),
        str(plan.get("assetSymbol") or "").strip(),
        "date",
    ]
    fallback = " ".join(part for part in fallback_parts if part).strip() or question
    if not api_key:
        return fallback
    prompt = (
        "Generate one concise English web-search query for discovering the event set and dates needed by this event-window analysis.\n"
        "Do not answer the user's question. Do not include stock-price terms unless they help identify the event.\n"
        "Prefer a broad event-discovery query using the entity and event type. Do not include phrases like 'latest 4' or 'last N' in the query; the next extraction step will select the requested count.\n"
        "Return JSON only: {\"query\":\"...\"}.\n\n"
        f"User question: {question}\n"
        f"Structured plan: {json.dumps(plan, ensure_ascii=False)}"
    )
    try:
        completion = create_chat_completion(
            OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL),
            json_object=True,
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
            max_tokens=120,
        )
        parsed = parse_json_object(completion_text(completion, "行动计划模型"))
        query = str((parsed or {}).get("query") or "").strip()
        return query or fallback
    except Exception:
        return fallback


