def default_search_cli_args(script: str, question: str) -> list[str]:
    if script == EXTERNAL_INFO_SEARCH_SCRIPT:
        plan = infer_event_window_plan(question)
        query = event_window_search_query(question, plan) if plan.get("requiresEventWindow") else external_search_query_for_question(question)
        args = ["--query", query, "--limit", "20", "--max-details", "20"]
        if plan.get("requiresEventWindow"):
            args.extend(["--source", "kimi"])
        for site in infer_search_sites(question):
            args.extend(["--site", site])
        return args
    return ["--query", question, "--semantic", "--no-topic-filter", "--limit", "20", "--max-details", "20"]


def infer_search_sites(question: str) -> list[str]:
    sites: list[str] = []
    for match in re.finditer(r"site:([A-Za-z0-9.-]+)", question):
        sites.append(match.group(1))
    for match in re.finditer(r"https?://([A-Za-z0-9.-]+)", question):
        sites.append(match.group(1))
    deduped: list[str] = []
    for site in sites:
        if site and site not in deduped:
            deduped.append(site)
    return deduped[:4]


def apply_mind_map_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    lower = question.lower()
    if not any(term.lower() in lower for term in MIND_MAP_TERMS):
        return route

    steps = normalize_route_steps(route)
    for step in steps:
        if not is_mind_map_step(step):
            continue
        args = step.get("cli_args") if isinstance(step.get("cli_args"), list) else []
        if not has_cli_option([str(value) for value in args], "--data") and not has_cli_option([str(value) for value in args], "--payload"):
            step["cli_args"] = [*args]
            updated = dict(route)
            updated["steps"] = steps
            return updated
        return route
    component = ALLOWED_COMPONENTS_BY_FILE.get("mind_map.py")
    if not component:
        return route

    code = specific_code_for_route(question, steps)
    if len(steps) >= MAX_ROUTE_STEPS:
        steps = [step for step in steps if str(step.get("script") or "") not in SEARCH_SCRIPTS][: MAX_ROUTE_STEPS - 1]

    steps.append(
        {
            "script": component.filename,
            "label": component.label,
            "code": code,
            "cli_args": [
                "--title",
                question[:48] or "Mind Map",
            ],
            "reason": "用户明确要求思维导图/脑图；mind_map.py 只负责渲染，内容由前序搜索/模型摘要生成后注入。",
        }
    )
    updated = dict(route)
    updated["steps"] = steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "已按思维导图请求补充 mind_map 渲染模块。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def _cli_option_value_from_step(step: dict[str, Any], *options: str) -> str:
    args = sanitize_cli_args(step.get("cli_args") or []) if isinstance(step.get("cli_args"), list) else []
    for option in options:
        value = value_after_option(args, option)
        if value:
            return str(value).strip()
    return ""


def yahoo_symbol_text_for_step(step: dict[str, Any]) -> str:
    return (
        _cli_option_value_from_step(step, "--symbols", "--symbol", "--code")
        or str(step.get("code") or "").strip()
    )


def is_resolved_yahoo_symbol_token(token: str) -> bool:
    value = str(token or "").strip().upper()
    if not value or value in GENERIC_ROUTE_CODES or value in MACRO_PSEUDO_CODES:
        return False
    if re.search(r"[\u3400-\u9fff]", value):
        return False
    if len(value) > 24:
        return False
    return bool(re.fullmatch(r"\^?[A-Z0-9][A-Z0-9.\-=]{0,23}", value))


def yahoo_step_has_resolved_symbol(step: dict[str, Any]) -> bool:
    if str(step.get("script") or "") != "yahoo_data.py":
        return True
    args = sanitize_cli_args(step.get("cli_args") or []) if isinstance(step.get("cli_args"), list) else []
    if has_cli_option(args, "--macro-indicators") or has_cli_option(args, "--event-windows-json"):
        return True
    symbol_text = yahoo_symbol_text_for_step(step)
    tokens = [token.strip() for token in re.split(r"[,，\s]+", symbol_text) if token.strip()]
    return bool(tokens) and all(is_resolved_yahoo_symbol_token(token) for token in tokens)


def needs_text_evidence_mind_map(question: str, steps: list[dict[str, Any]]) -> bool:
    lower = str(question or "").lower()
    has_mind_map_intent = any(term.lower() in lower for term in MIND_MAP_TERMS) or any(is_mind_map_step(step) for step in steps)
    if not has_mind_map_intent:
        return False
    text_summary_terms = (
        "总结",
        "總結",
        "梳理",
        "要点",
        "要點",
        "表现",
        "表現",
        "盘面",
        "盤面",
        "热点",
        "熱點",
        "新闻",
        "新聞",
        "消息",
        "主题",
        "主題",
        "summary",
        "summarize",
        "overview",
        "market today",
    )
    return is_broad_market_question(question) or any(term in lower or term in question for term in text_summary_terms)


def make_text_evidence_step_for_question(question: str) -> dict[str, Any] | None:
    target_script = EXTERNAL_INFO_SEARCH_SCRIPT if is_broad_market_question(question) or should_use_external_info_search(question) else NEWS_SEARCH_SCRIPT
    component = ALLOWED_COMPONENTS_BY_FILE.get(target_script)
    if not component:
        return None
    cli_args = fallback_external_search_args(question) if target_script == EXTERNAL_INFO_SEARCH_SCRIPT else default_search_cli_args(target_script, question)
    return {
        "script": target_script,
        "label": component.label,
        "code": "MARKET",
        "cli_args": cli_args,
        "thought": "先获取可被思维导图归纳的文本证据 observation。",
        "reason": "当前请求是主题/泛市场的结构化总结，不是单一 Yahoo symbol 的结构化行情查询。",
        "expected_observation": "获得与用户主题直接相关的最新事实、新闻或网页摘要。",
        "next_thought": "基于文本 observation 生成层级化思维导图内容。",
    }


def repair_unresolved_yahoo_for_text_mind_map(question: str, route: dict[str, Any]) -> dict[str, Any]:
    steps = normalize_route_steps(route)
    if not needs_text_evidence_mind_map(question, steps):
        return route
    invalid_yahoo = [
        step
        for step in steps
        if str(step.get("script") or "") == "yahoo_data.py" and not yahoo_step_has_resolved_symbol(step)
    ]
    if not invalid_yahoo:
        return route

    repaired_steps = [
        dict(step)
        for step in steps
        if str(step.get("script") or "") not in {"yahoo_data.py", "code_interpreter.py"}
        or yahoo_step_has_resolved_symbol(step)
    ]
    has_search = any(str(step.get("script") or "") in SEARCH_SCRIPTS for step in repaired_steps)
    if not has_search:
        search_step = make_text_evidence_step_for_question(question)
        if search_step:
            repaired_steps.insert(0, search_step)

    updated = dict(route)
    updated["steps"] = repaired_steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    repair_reason = "Yahoo step 未包含可解析 symbol，已按工具能力边界改为先获取文本证据，再生成思维导图。"
    updated["reason"] = f"{reason}；{repair_reason}" if reason else repair_reason
    updated["_display_strategy"] = updated["reason"]
    return updated


def apply_key_stats_snapshot_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    steps = normalize_route_steps(route)
    if any(str(step.get("script") or "") == "key_stats.py" for step in steps):
        return route
    if not any(str(step.get("script") or "") in {"kline.py", "trade_flow.py", "volume_profile.py"} for step in steps):
        return route
    lower = question.lower()
    trigger = any(
        term in question or term in lower
        for term in (
            "近期", "最近", "当前", "當前", "走势", "走勢", "表现", "表現", "关注", "關注",
            "值得", "估值", "市值", "价格", "價格", "波动", "波動", "short-term", "recent",
            "current", "watch", "valuation", "market cap",
        )
    )
    if not trigger:
        return route
    component = ALLOWED_COMPONENTS_BY_FILE.get("key_stats.py")
    if not component:
        return route
    code = specific_code_for_route(question, steps)
    if len(steps) >= MAX_ROUTE_STEPS:
        search_indexes = [index for index, step in enumerate(steps) if str(step.get("script") or "") in SEARCH_SCRIPTS]
        if search_indexes:
            steps.pop(search_indexes[-1])
        else:
            return route
    steps.append(
        {
            "script": "key_stats.py",
            "label": component.label,
            "code": code,
            "cli_args": [],
            "reason": "补充当前价、日内区间、52周区间、市值、估值和波动等市场快照，辅助判断当前是否值得关注。",
            "expected_observation": "返回当前价格、区间位置、估值倍数、市值、Beta 和成交额等关键统计。",
        }
    )
    updated = dict(route)
    updated["steps"] = steps[:MAX_ROUTE_STEPS]
    return updated


def apply_short_term_trading_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    lower = question.lower()
    has_code = (infer_symbol_from_question(question) or extract_stock_code(question) or "").upper()
    if not has_code:
        return route

    technical_terms = (
        "k线", "k線", "走势", "走勢", "趋势", "趨勢", "技术", "技術", "支撑", "支撐",
        "压力", "壓力", "风险条件", "風險條件", "交易机会", "交易機會", "短线", "短線",
        "短期", "今天", "今日", "当前", "當前", "资金面", "資金面", "资金流", "資金流", "流向", "成交分布",
        "成交结构", "成交結構", "成交量", "量能", "筹码", "籌碼", "关键统计", "關鍵統計",
        "季节性", "季節性", "机构", "機構", "内部人", "內部人", "insider", "institution",
        "technical", "trend", "support", "resistance", "risk", "short-term", "volume",
        "volume profile", "fund flow", "money flow", "seasonal", "seasonality",
    )
    if not any(term in question or term in lower for term in technical_terms):
        return route

    steps = normalize_route_steps(route)
    code = specific_code_for_route(question, steps)
    desired: list[tuple[str, list[str], str]] = []

    if any(term in question or term in lower for term in ("k线", "k線", "走势", "走勢", "趋势", "趨勢", "技术", "技術", "支撑", "支撐", "压力", "壓力", "交易机会", "交易機會", "短线", "短線", "短期", "今天", "今日", "technical", "trend", "support", "resistance", "short-term")):
        desired.append(("kline.py", [], "用户询问K线走势、支撑压力和短线机会，需要用 Kline 模块读取价格、量能和技术形态。"))
    if any(term in question or term in lower for term in ("资金面", "資金面", "资金流", "資金流", "流向", "资金", "資金", "买卖", "買賣", "订单流", "訂單流", "fund flow", "money flow")):
        desired.append(("trade_flow.py", [], "用户询问资金流向，需要用 Trade Flow 模块查看大单/小单、流入流出和净流趋势。"))
    if any(term in question or term in lower for term in ("成交分布", "成交结构", "成交結構", "成交量", "量能", "筹码", "籌碼", "volume profile", "volume")):
        desired.append(("volume_profile.py", [], "用户询问成交分布和量价结构，需要用 Volume Profile 模块查看成交量、买卖量和价位分布。"))
    if any(term in question or term in lower for term in ("关键统计", "關鍵統計", "当前", "當前", "今天", "今日", "52周", "52 周", "市值", "波动", "波動", "key stats")):
        desired.append(("key_stats.py", [], "用户要求关键统计数据，需要补充当前价、日内区间、52周区间、市值、估值和成交统计。"))
    if any(term in question or term in lower for term in ("季节性", "季節性", "seasonal", "seasonality")):
        desired.append(("seasonals.py", [], "用户询问季节性表现，需要用 Seasonals 模块查看近年季节性收益和成交额变化。"))
    if any(term in question or term in lower for term in ("机构", "機構", "institution")):
        desired.append(("institution_trades.py", [], "用户询问机构交易情况，需要用 Institution Trades 模块查看机构买卖活动和近期交易明细。"))
    if any(term in question or term in lower for term in ("内部人", "內部人", "insider")):
        desired.append(("insider_trades.py", [], "用户询问内部人交易情况，需要用 Insider Trades 模块查看内部人买卖和近期交易明细。"))

    if not desired:
        return route
    changed = False
    for script, cli_args, reason in desired:
        changed = append_business_step_if_available(
            steps=steps,
            script=script,
            code=code,
            cli_args=cli_args,
            reason=reason,
        ) or changed
    if not changed:
        return route

    priority = {
        "kline.py": 0,
        "trade_flow.py": 1,
        "volume_profile.py": 2,
        "key_stats.py": 3,
        "seasonals.py": 4,
        "institution_trades.py": 5,
        "insider_trades.py": 6,
    }
    steps = sorted(steps, key=lambda step: priority.get(str(step.get("script") or ""), 50))
    updated = dict(route)
    updated["steps"] = steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "已按业务图表 Skill 描述补齐短线交易分析模块：K线、资金流、成交分布、关键统计、季节性、机构和内部人交易。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def is_pure_us_equity_price_trend_request(question: str) -> bool:
    """Return True when the user asks only for a US equity price/K-line view."""
    text = str(question or "")
    lower = text.lower()
    if requested_yahoo_data_source(text) or is_explicit_non_us_equity_question(text):
        return False
    if has_explicit_coordinate_chart_request(text):
        # Explicit line/bar/etc. requests should keep the requested visual form.
        return False
    has_price_trend = any(
        term in text or term in lower
        for term in (
            "股价走势", "股價走勢", "价格走势", "價格走勢", "技术走势", "技術走勢",
            "k线", "k線", "行情走势", "行情走勢", "走势", "走勢", "price trend",
            "stock price trend", "share price trend", "technical trend", "kline", "candlestick",
        )
    )
    if not has_price_trend:
        return False
    non_price_dimensions = (
        *FINANCIAL_BROAD_TERMS,
        *INCOME_STATEMENT_TERMS,
        *EPS_METRIC_TERMS,
        *REVENUE_EXPENSE_TERMS,
        *VALUATION_TERMS,
        *LONG_TERM_QUALITY_TERMS,
        "现金流", "現金流", "资产负债", "資產負債", "基本面", "业绩", "業績",
        "盈利", "利润", "利潤", "营收", "營收", "估值", "市值", "关键统计", "關鍵統計",
        "52周", "52 周", "资金流", "資金流", "订单流", "訂單流", "买卖盘", "買賣盤",
        "筹码", "籌碼", "成交结构", "成交結構", "季节性", "季節性", "机构", "機構",
        "内部人", "內部人", "目标价", "目標價", "评级", "評級", "分析师", "分析師",
        "新闻", "新聞", "消息", "催化", "为什么", "為什麼", "原因", "why", "news",
        "catalyst", "fundamental", "earnings", "revenue", "profit", "cash flow", "valuation",
        "market cap", "key stats", "52-week", "fund flow", "money flow", "order flow",
        "volume profile", "seasonality", "institution", "insider", "price target", "rating",
    )
    return not any(term.lower() in lower for term in non_price_dimensions)


def apply_pure_price_trend_kline_only_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    """Use the business K-line as the sole data source and visual for price trend."""
    if not is_pure_us_equity_price_trend_request(question):
        return route
    steps = normalize_route_steps(route)
    code = us_equity_code_for_question(question, steps)
    if not code:
        return route
    kline_step = next((dict(step) for step in steps if str(step.get("script") or "") == "kline.py"), None)
    if kline_step is None:
        component = ALLOWED_COMPONENTS_BY_FILE.get("kline.py")
        if not component:
            return route
        kline_step = {
            "script": "kline.py",
            "label": component.label,
            "code": code,
            "cli_args": [],
        }
    kline_step["code"] = code
    kline_step["reason"] = (
        "用户只询问股价/K线走势；K线业务组件已经内置 OHLCV、成交量和技术指标取数与展示，"
        "无需重复调用 Yahoo close、通用折线、财务、现金流、估值或关键统计模块。"
    )
    updated = dict(route)
    updated["steps"] = [kline_step]
    policy_reason = "已按纯股价走势意图收敛为唯一 K线业务组件，并移除重复行情源及无关基本面模块。"
    reason = str(route.get("reason") or "").strip()
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    updated["_display_strategy"] = policy_reason
    updated["_strategy_source"] = "policy"
    return updated


def apply_price_question_dimension_scope_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    """Remove business modules that a focused price question did not request."""
    if is_explicit_non_us_equity_question(question) or not has_price_intent(question):
        return route
    lower = str(question or "").lower()
    broad_research_terms = (
        "综合分析", "綜合分析", "全面分析", "投研", "投资分析", "投資分析", "怎么看",
        "怎麼看", "值不值得", "能不能买", "能不能買", "投资价值", "投資價值", "风险机会",
        "風險機會", "前景", "展望", "analysis", "thesis", "investment case", "outlook",
    )
    if any(term in lower for term in broad_research_terms):
        return route

    wants_key_stats = any(
        term in lower
        for term in (
            "关键统计", "關鍵統計", "市值", "52周", "52 周", "日内区间", "日內區間",
            "成交额", "成交額", "换手", "換手", "波动率", "波動率", "beta", "贝塔",
            "key stats", "market cap", "52-week", "day range", "turnover", "volatility",
        )
    )
    wants_income = any(term.lower() in lower for term in (*FINANCIAL_BROAD_TERMS, *INCOME_STATEMENT_TERMS, *EPS_METRIC_TERMS))
    wants_balance_sheet = any(
        term in lower for term in ("资产负债", "資產負債", "资产", "資產", "负债", "負債", "balance sheet", "debt", "liquidity")
    ) or any(term.lower() in lower for term in FINANCIAL_BROAD_TERMS)
    wants_cash_flow = any(
        term in lower for term in ("现金流", "現金流", "经营现金流", "經營現金流", "自由现金流", "自由現金流", "cash flow", "free cash flow", "fcf")
    ) or any(term.lower() in lower for term in FINANCIAL_BROAD_TERMS)
    wants_valuation = any(term.lower() in lower for term in VALUATION_TERMS)
    explicit_coordinate_chart = has_explicit_coordinate_chart_request(question)
    explicit_yahoo = requested_yahoo_data_source(question)

    steps = normalize_route_steps(route)
    has_kline = any(str(step.get("script") or "") == "kline.py" for step in steps)
    filtered: list[dict[str, Any]] = []
    for step in steps:
        script = str(step.get("script") or "")
        if script == "key_stats.py" and not wants_key_stats:
            continue
        if script in {"income_statement.py", "key_financial_indicators.py", "revenue_expenses.py"} and not wants_income:
            continue
        if script == "balance_sheet.py" and not wants_balance_sheet:
            continue
        if script == "cash_flow.py" and not wants_cash_flow:
            continue
        if script in {"valuation.py", "valuation_ratios.py"} and not wants_valuation:
            continue
        if script == "kline.py" and explicit_coordinate_chart:
            # The user explicitly chose a coordinate chart instead of the K-line view.
            continue
        if has_kline and not explicit_yahoo and not explicit_coordinate_chart:
            if script in {"yahoo_data.py", "code_interpreter.py", *COORDINATE_GENERIC_CHART_SCRIPTS}:
                continue
        filtered.append(step)

    if len(filtered) == len(steps):
        return route
    updated = dict(route)
    updated["steps"] = filtered[:MAX_ROUTE_STEPS]
    policy_reason = "已按股价问句的明确维度移除未请求的业务模块，并避免 K线与 Yahoo/通用行情图重复取数。"
    reason = str(route.get("reason") or "").strip()
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def apply_derived_chart_annotation_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    """Use the native K-line as the single source and render target for inferred annotations."""
    if not wants_model_derived_chart_annotation(question):
        return route
    steps = normalize_route_steps(route)
    code = specific_code_for_route(question, steps)
    kline_step = next((step for step in steps if str(step.get("script") or "") == "kline.py"), None)
    if kline_step is None:
        append_business_step_if_available(
            steps=steps,
            script="kline.py",
            code=code,
            cli_args=[],
            reason="用户要求模型判断买卖点或支撑压力，必须先读取 K 线价格、量能与技术结构，再生成数据坐标标记。",
        )
        kline_step = next((step for step in steps if str(step.get("script") or "") == "kline.py"), None)
    if kline_step is None:
        return route

    extrema_kind = requested_52_week_extrema_kind(question)
    if extrema_kind:
        # A 52-week extreme must be computed from roughly one trading year's
        # daily bars.  Do not let a model-provided small limit silently turn it
        # into a recent 80-bar high/low.
        cli_args = sanitize_cli_args(kline_step.get("cli_args") or [])
        cli_args = replace_cli_option(cli_args, "--period", "1d")
        cli_args = replace_cli_option(cli_args, "--limit", "260")
        cli_args = replace_cli_option(cli_args, "--range", "1y")
        kline_step["cli_args"] = cli_args
        kline_step["reason"] = (
            f"用户要求标记52周{'最高' if extrema_kind == 'high' else '最低'}价；"
            "先读取至少260根日K，并从最近52周数据确定价格及对应交易日。"
        )

    # The K-line payload already contains OHLCV and technical-series evidence.  Keeping
    # Yahoo/code-interpreter/generic-line fallbacks here creates duplicate data and can
    # cause the planner to draw a second, unrelated chart instead of annotating K-line.
    steps = [kline_step]
    updated = dict(route)
    updated["steps"] = steps
    reason = str(route.get("reason") or "").strip()
    policy_reason = "已将语义型画线请求收敛为 K线取数 → 模型推理价位 → AiChart 原生标记，不再调用 Yahoo、代码解释器或通用折线图兜底。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    updated["_display_strategy"] = updated["reason"]
    return updated


