    if any(term in question or term in lower for term in ("派息率", "分红率", "分紅率", "payout ratio")):
        desired.append(("payout_ratio.py", [], "用户明确询问派息率/分红率，需要调用 Payout Ratio 查看净利润、现金分红和分红率历史。"))
