def enforce_explicit_yahoo_source_scope(question: str, route: dict[str, Any]) -> dict[str, Any]:
    """Treat an explicit Yahoo request as an exclusive data-source boundary."""
    if not requested_yahoo_data_source(question):
        return route
    steps = normalize_route_steps(route)
    filtered: list[dict[str, Any]] = []
    for step in steps:
        script = str(step.get("script") or "")
        skill = skill_name_for_script_filename(script)
        if script in {"yahoo_data.py", "code_interpreter.py"} or skill == "generic-chart":
            filtered.append(dict(step))

    if not any(str(step.get("script") or "") == "yahoo_data.py" for step in filtered):
        component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
        code = specific_code_for_route(question, steps)
        if component:
            metric = yahoo_requested_financial_metric(question) or "close"
            filtered.insert(
                0,
                {
                    "script": "yahoo_data.py",
                    "label": component.label,
                    "code": code,
                    "cli_args": ["--metric", metric],
                    "thought": "仅调用用户指定的 Yahoo 数据源。",
                    "reason": "用户明确指定 Yahoo；已阻止 AInvest、新闻搜索及其他业务数据源参与。",
                    "expected_observation": "获得 Yahoo 返回的结构化数据或明确的 Yahoo 缺失结果。",
                },
            )
    if filtered == steps:
        return route
    updated = dict(route)
    updated["steps"] = filtered[:MAX_ROUTE_STEPS]
    existing_reason = str(route.get("reason") or "").strip()
    scope_reason = "用户明确指定 Yahoo 数据源，已移除 AInvest 财务、行情、估值、现金流、新闻搜索及其他外部数据步骤；仅保留 Yahoo 和必要的无外部取数转换/渲染。"
    updated["reason"] = f"{existing_reason}；{scope_reason}" if existing_reason else scope_reason
    updated["_display_strategy"] = updated["reason"]
    updated["_strategy_source"] = "policy"
    return updated


def macro_indicator_arg(question: str) -> str:
    lower = question.lower()
    indicators: list[str] = []
    if "gdp" in lower or "国内生产总值" in question or "國內生產總值" in question:
        indicators.append("gdp")
    if "人口" in question or "population" in lower:
        indicators.append("population")
    if "失业率" in question or "失業率" in question or "unemployment" in lower:
        indicators.append("unemployment")
    if "cpi" in lower:
        indicators.append("cpi")
    if "通胀" in question or "通脹" in question or "inflation" in lower:
        indicators.append("inflation")
    if "利率" in question or "interest rate" in lower:
        indicators.append("interest_rate")
    return ",".join(indicators or ["gdp", "population", "unemployment"])


def macro_data_search_query(question: str) -> str:
    lower = question.lower()
    country = "United States" if any(term in lower or term in question for term in ("美国", "美國", "us ", "u.s.", "united states", "america")) else ""
    window = "last 5 years annual data" if any(term in lower or term in question for term in ("过去5年", "過去5年", "近5年", "5年", "last 5 years", "past 5 years")) else "annual data"
    indicators: list[str] = []
    if "gdp" in lower or "国内生产总值" in question or "國內生產總值" in question:
        indicators.append("GDP")
    if "人口" in question or "population" in lower:
        indicators.append("population")
    if "失业率" in question or "失業率" in question or "unemployment" in lower:
        indicators.append("unemployment rate")
    if "cpi" in lower:
        indicators.append("CPI")
    if "通胀" in question or "通脹" in question or "inflation" in lower:
        indicators.append("inflation")
    if "利率" in question or "interest rate" in lower:
        indicators.append("interest rate")
    indicator_text = " ".join(indicators) or "macroeconomic indicators"
    return f"{country} {indicator_text} {window} official data World Bank FRED IMF".strip()


def macro_chart_title(question: str) -> str:
    if html_lang_for_question(question) == "en":
        return "US GDP, Population and Unemployment Rate"
    if any(term in question for term in ("美国", "美國")):
        return "美国GDP、人口与失业率"
    return plain_text_excerpt(question, 36) or "宏观指标趋势"


def is_invalid_macro_yahoo_step(question: str, step: dict[str, Any]) -> bool:
    if str(step.get("script") or "") != "yahoo_data.py":
        return False
    if not requested_macro_indicator_data(question):
        return False
    code = str(step.get("code") or "").strip().upper()
    if code in GENERIC_ROUTE_CODES or code in MACRO_PSEUDO_CODES:
        return True
    args = [str(value).strip().upper() for value in step.get("cli_args") or []]
    return any(value in MACRO_PSEUDO_CODES for value in args)


def apply_macro_indicator_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not requested_macro_indicator_data(question):
        return route
    steps = normalize_route_steps(route)
    force_yahoo_macro = requested_yahoo_data_source(question)
    if not force_yahoo_macro and not any(is_invalid_macro_yahoo_step(question, step) for step in steps):
        return route

    search_component = ALLOWED_COMPONENTS_BY_FILE.get(EXTERNAL_INFO_SEARCH_SCRIPT)
    yahoo_component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    code_component = ALLOWED_COMPONENTS_BY_FILE.get("code_interpreter.py")
    chart_component = ALLOWED_COMPONENTS_BY_FILE.get("bar_line.py")
    if not search_component and not yahoo_component:
        return route

    title = macro_chart_title(question)
    if requested_yahoo_data_source(question) and yahoo_component:
        source_step = {
            "thought": "用户明确指定雅虎数据，先调用 Yahoo Data 的宏观指标模式获取年度宏观序列。",
            "script": "yahoo_data.py",
            "label": yahoo_component.label,
            "code": "US_MACRO",
            "cli_args": [
                "--macro-indicators",
                macro_indicator_arg(question),
                "--range",
                infer_yahoo_range_from_question(question),
                "--title",
                title,
            ],
            "reason": "用户指定使用雅虎数据；宏观指标不走股票 symbol chart API，而走 Yahoo Data 宏观指标模式。",
            "expected_observation": "返回年度 GDP、人口、失业率等宏观指标的结构化 payload。",
            "next_thought": "把 Yahoo 宏观 payload 整理成柱折图组件可消费的数据。",
        }
    else:
        source_step = {
            "thought": "先检索官方或可溯源的宏观年度数据。",
            "script": EXTERNAL_INFO_SEARCH_SCRIPT,
            "label": search_component.label,
            "code": "MARKET",
            "cli_args": [
                "--query",
                macro_data_search_query(question),
                "--source",
                "kimi",
                "--limit",
                "8",
                "--max-details",
                "20",
                "--timeout",
                "60",
            ],
            "reason": "用户未指定必须使用 Yahoo，先检索可溯源宏观年度数据。",
            "expected_observation": "返回包含年份、GDP、人口、失业率等字段的可溯源宏观数据。",
            "next_thought": "把检索结果整理为柱折图可消费的字段和值。",
        }
    replaced_source_scripts = {EXTERNAL_INFO_SEARCH_SCRIPT}
    if force_yahoo_macro:
        replaced_source_scripts.add("yahoo_data.py")
    filtered = [
        dict(step)
        for step in steps
        if str(step.get("script") or "") not in replaced_source_scripts
        and not is_invalid_macro_yahoo_step(question, step)
    ]

    has_code_step = any(str(step.get("script") or "") == "code_interpreter.py" for step in filtered)
    if not has_code_step and code_component:
        filtered.insert(
            0,
            {
                "script": "code_interpreter.py",
                "label": code_component.label,
                "code": "MARKET",
                "cli_args": ["--chart-type", "bar-line", "--title", title, "--question", question],
                "reason": "根据用户问句从宏观数据检索结果中抽取年份和指标字段，生成柱折图数据。",
                "expected_observation": "输出 data 数组，每行包含 period/year 以及 GDP、人口、失业率字段。",
            },
        )
    else:
        for step in filtered:
            if str(step.get("script") or "") == "code_interpreter.py":
                args = [str(value) for value in step.get("cli_args") or []]
                if not has_cli_option(args, "--chart-type"):
                    args.extend(["--chart-type", "bar-line"])
                args = replace_cli_option(args, "--title", title)
                if not has_cli_option(args, "--question"):
                    args.extend(["--question", question])
                step["cli_args"] = args
                step["reason"] = "根据前一步宏观数据源整理年份、GDP、人口、失业率字段，生成柱折图数据。"

    if requested_bar_line_chart(question) and chart_component and not any(str(step.get("script") or "") == "bar_line.py" for step in filtered):
        filtered.append(
            {
                "script": "bar_line.py",
                "label": chart_component.label,
                "code": "MARKET",
                "cli_args": ["--title", title],
                "reason": "按用户指定的柱折图形式呈现整理后的宏观指标。",
                "expected_observation": "生成双轴柱折图 HTML。",
            }
        )

    updated = dict(route)
    updated["steps"] = [source_step, *filtered][:MAX_ROUTE_STEPS]
    if requested_yahoo_data_source(question) and yahoo_component:
        updated["reason"] = "用户明确指定雅虎数据，已改为执行 Yahoo Data 宏观指标模式，再整理并渲染柱折图。"
    else:
        updated["reason"] = "宏观经济指标不是可交易标的，已改为先获取可溯源宏观数据，再按用户问句整理并渲染柱折图。"
    return updated


def yahoo_data_renders_dynamic_line(step: dict[str, Any]) -> bool:
    if str(step.get("script") or "") != "yahoo_data.py":
        return False
    args = [str(value).strip().lower() for value in step.get("cli_args") or []]
    for index, value in enumerate(args[:-1]):
        if value == "--chart-type" and args[index + 1] in {"line", "dynamic_line", "dynamic-line"}:
            return True
    return any(value in {"--chart-type=dynamic_line", "--chart-type=dynamic-line", "--chart-type=line"} for value in args)


def is_dynamic_line_render_step(step: dict[str, Any]) -> bool:
    script = str(step.get("script") or "")
    return script == "dynamic_line.py"


def dynamic_line_dark_theme_requested(question: str) -> bool:
    lower = question.lower()
    return any(
        term in lower
        for term in (
            "dark",
            "dark mode",
            "night mode",
            "--theme dark",
            "--theme=dark",
            "暗夜",
            "暗色",
            "暗黑",
            "深色",
            "夜间模式",
            "黑底",
            "黑色背景",
        )
    )


def explicit_dark_theme_requested(question: str) -> bool:
    return dynamic_line_dark_theme_requested(question)


def normalize_business_theme_args(selected: SkillScript, args: list[str], question: str) -> list[str]:
    themeable = {
        "wall_street_consensus.py",
        "kline.py",
        "average_rating_history.py",
        "analyst_recommendations.py",
        "investment_rating.py",
        "fundamental_investment_rating.py",
    }
    if selected.filename not in themeable:
        return args
    cleaned = remove_cli_option(args, {"--theme", "--theme-mode", "--themeMode", "--dark"})
    if explicit_dark_theme_requested(question):
        return replace_cli_option(cleaned, "--theme", "dark")
    return cleaned


def normalize_dynamic_line_theme_args(args: list[str], question: str) -> list[str]:
    cleaned = remove_cli_option(args, {"--theme"})
    if dynamic_line_dark_theme_requested(question):
        return replace_cli_option(cleaned, "--theme", "dark")
    return cleaned


def normalize_logic_chart_theme_args(args: list[str], question: str) -> list[str]:
    cleaned = remove_cli_option(args, {"--theme", "--theme-mode", "--themeMode", "--dark"})
    if explicit_dark_theme_requested(question):
        return replace_cli_option(cleaned, "--theme", "dark")
    return cleaned


@lru_cache(maxsize=128)
def script_supports_cli_option(filename: str, option: str) -> bool:
    try:
        text = script_path_for_filename(filename).read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return False
    pattern = re.compile(r"add_argument\((?P<args>.*?)\)", re.S)
    for match in pattern.finditer(text):
        if re.search(rf"['\"]{re.escape(option)}['\"]", match.group("args")):
            return True
    return False


def add_language_arg_if_supported(selected: SkillScript, args: list[str], language: str, *, force: bool = False) -> list[str]:
    if not script_supports_cli_option(selected.filename, "--language"):
        return remove_cli_option(args, {"--language"})
    if not force and has_cli_option(args, "--language"):
        return args
    return replace_cli_option(args, "--language", language)


def ensure_dynamic_line_after_yahoo_data(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if requested_bar_line_chart(question):
        return route
    steps = normalize_route_steps(route)
    if not any(yahoo_data_renders_dynamic_line(step) for step in steps):
        return route

    if any(is_dynamic_line_render_step(step) for step in steps):
        updated_steps: list[dict[str, Any]] = []
        changed = False
        for step in steps:
            item = dict(step)
            if is_dynamic_line_render_step(item):
                args = [str(value) for value in item.get("cli_args") or []] if isinstance(item.get("cli_args"), list) else []
                next_args = normalize_dynamic_line_theme_args(args, question)
                if next_args != args:
                    item["cli_args"] = next_args
                    changed = True
            updated_steps.append(item)
        if not changed:
            return route
        updated = dict(route)
        updated["steps"] = updated_steps[:MAX_ROUTE_STEPS]
        reason = str(route.get("reason") or "").strip()
        policy_reason = "Yahoo Data Tool 仅作为数据源；dynamic_line.py 仅在用户明确要求 dark/暗夜模式时携带 --theme dark，否则不添加 --theme。"
        updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
        return updated

    component = ALLOWED_COMPONENTS_BY_FILE.get("dynamic_line.py")
    if not component:
        return route

    updated_steps = list(steps)
    last_yahoo_index = max(index for index, step in enumerate(updated_steps) if yahoo_data_renders_dynamic_line(step))
    yahoo_step = updated_steps[last_yahoo_index]
    args = [str(value) for value in yahoo_step.get("cli_args") or []] if isinstance(yahoo_step.get("cli_args"), list) else []
    title = value_after_option(args, "--title") or str(yahoo_step.get("title") or "")
    dynamic_args: list[str] = []
    if title:
        dynamic_args.extend(["--title", title])
    dynamic_args = normalize_dynamic_line_theme_args(dynamic_args, question)
    updated_steps.insert(
        last_yahoo_index + 1,
        {
            "thought": "Yahoo Data Tool 只负责取数，使用 Aime dynamic_line 组件渲染最终动态图。",
            "script": "dynamic_line.py",
            "label": component.label,
            "code": yahoo_step.get("code") or "MARKET",
            "cli_args": dynamic_args,
            "reason": "保持 Yahoo 作为数据源，避免 Yahoo 工具内维护图表样式。",
            "expected_observation": "读取上一步 Yahoo payload 并输出统一样式的 dynamic_line HTML。",
        },
    )
    updated = dict(route)
    updated["steps"] = updated_steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "Yahoo Data Tool 仅作为数据源，已追加 dynamic_line.py 负责最终渲染。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def enforce_text_search_limit_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    steps = normalize_route_steps(route)
    if not steps:
        return route
    changed = False
    normalized_steps: list[dict[str, Any]] = []
    for step in steps:
        item = dict(step)
        script = str(item.get("script") or "")
        args = list(item.get("cli_args") or [])
        if script == EXTERNAL_INFO_SEARCH_SCRIPT:
            item["cli_args"] = build_external_info_search_args(args, question)
            changed = True
        elif script == NEWS_SEARCH_SCRIPT:
            category = str(value_after_option([str(value) for value in args], "--category") or "").strip().lower()
            if category not in {"videos", "video", "shorts"}:
                item["cli_args"] = replace_cli_option_value(args, "--limit", "20")
                item["cli_args"] = replace_cli_option_value(item["cli_args"], "--max-details", "20")
                changed = True
        normalized_steps.append(item)
    if not changed:
        return route
    updated = dict(route)
    updated["steps"] = normalized_steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "文本搜索结果量已统一调整为 20 条，并抓取 20 条详情用于生成更完整回答。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


