def apply_short_term_price_kline_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not asks_short_term_price_or_technical_question(question):
        return route
    steps = normalize_route_steps(route)
    if any(str(step.get("script") or "") == "kline.py" for step in steps):
        return route
    code = specific_code_for_route(question, steps)
    if code in {"", "MARKET", "ALL", "GENERAL", "NEWS"}:
        code = infer_symbol_from_question(question) or extract_stock_code(question) or ""
    if not code:
        return route
    if not is_us_stock_symbol_for_business_chart(code):
        return route
    component = ALLOWED_COMPONENTS_BY_FILE.get("kline.py")
    if not component:
        return route
    kline_step = {
        "thought": "先补充最新行情/K线，用价格、均线、成交量和技术指标判断短期目标是否有数据支撑。",
        "script": "kline.py",
        "label": component.label,
        "code": code,
        "cli_args": ["--period", infer_kline_period_from_question(question)],
        "reason": "用户询问短期价格、上涨空间、目标价或技术走势，必须用行情图验证价格与量能是否支持该判断。",
        "expected_observation": "展示最新K线、均线、成交量与MACD等技术指标。",
    }
    insertion_index = 0
    while insertion_index < len(steps) and str(steps[insertion_index].get("script") or "") in SEARCH_SCRIPTS:
        insertion_index += 1
    steps = [*steps[:insertion_index], kline_step, *steps[insertion_index:]]
    updated = dict(route)
    updated["steps"] = steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "短期价格/技术判断已强制补充 kline.py 行情图。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def remove_kline_fallback_code_interpreter_charts(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not asks_short_term_price_or_technical_question(question):
        return route
    steps = normalize_route_steps(route)
    if not any(str(step.get("script") or "") == "kline.py" for step in steps):
        return route
    updated_steps: list[dict[str, Any]] = []
    changed = False
    for index, step in enumerate(steps):
        script = str(step.get("script") or "")
        if script != "code_interpreter.py":
            updated_steps.append(step)
            continue
        next_visualizer = next(
            (
                str(candidate.get("script") or "")
                for candidate in steps[index + 1 :]
                if str(candidate.get("script") or "") not in SEARCH_SCRIPTS
            ),
            "",
        )
        args = [str(value) for value in step.get("cli_args") or []] if isinstance(step.get("cli_args"), list) else []
        chart_type = cli_option_value(args, "--chart-type").strip().lower()
        if (
            next_visualizer not in COORDINATE_GENERIC_CHART_SCRIPTS
            and chart_type in {"", "line", "dynamic-line"}
        ):
            changed = True
            continue
        updated_steps.append(step)
    if not changed:
        return route
    updated = dict(route)
    updated["steps"] = updated_steps[:MAX_ROUTE_STEPS]
    reason = str(route.get("reason") or "").strip()
    policy_reason = "已移除 K 线后的普通折线兜底转换，避免用 code_interpreter.py 降级替代业务 K 线图。"
    updated["reason"] = f"{reason}；{policy_reason}" if reason else policy_reason
    return updated


def infer_short_term_yahoo_range_from_question(question: str) -> str:
    explicit_range = infer_yahoo_range_from_question(question)
    if explicit_range != "1y":
        return explicit_range
    lower = str(question or "").lower()
    if any(term in lower or term in question for term in ("近期", "最近", "短期", "近来", "近況", "recent", "short-term", "lately")):
        return "6mo"
    return explicit_range


def is_yahoo_price_symbol_outside_us_business(symbol: str) -> bool:
    code = str(symbol or "").strip().upper()
    if not code or code in GENERIC_ROUTE_CODES:
        return False
    return not is_us_stock_symbol_for_business_chart(code)


