def is_no_drawable_data_error(message: Any) -> bool:
    text = str(message or "").strip().lower()
    if not text:
        return False
    return any(
        marker in text
        for marker in (
            "no chart was generated because the input did not contain drawable data",
            "input did not contain drawable data",
            "no drawable data",
            "没有可绘制数据",
            "无可绘制数据",
        )
    )


def downstream_step_should_skip_after_no_data(
    selected: SkillScript,
    steps: list[dict[str, Any]],
    index_zero_based: int,
    skipped_no_data_modules: list[str],
) -> bool:
    if not skipped_no_data_modules:
        return False
    if selected.filename != "code_interpreter.py" and selected.filename not in GENERIC_CHART_PAYLOAD_SCRIPTS:
        return False
    if index_zero_based <= 0:
        return False
    previous_script = normalize_script_filename(str(steps[index_zero_based - 1].get("script") or ""))
    previous_skill = skill_name_for_script_filename(previous_script)
    return (
        previous_skill == "business-chart-recall"
        or previous_script == "code_interpreter.py"
        or previous_script in GENERIC_CHART_PAYLOAD_SCRIPTS
    )


def coordinate_chart_waiting_for_failed_transform(
    selected: SkillScript,
    steps: list[dict[str, Any]],
    index_zero_based: int,
    failed_modules: list[str],
) -> bool:
    if selected.filename not in GENERIC_CHART_PAYLOAD_SCRIPTS:
        return False
    if index_zero_based <= 0:
        return False
    previous_script = str(steps[index_zero_based - 1].get("script") or "")
    if previous_script != "code_interpreter.py":
        return False
    return any(message.startswith("code_interpreter.py:") for message in failed_modules)


def has_placeholder_payload_arg(args: list[str]) -> bool:
    payload_options = {"--payload", "--data-json", "--data", "--raw-data"}
    for index, value in enumerate(args):
        if value in payload_options and index + 1 < len(args):
            if "{{prev_step_payload}}" in args[index + 1] or "__PREV_STEP_PAYLOAD__" in args[index + 1]:
                return True
        if any(value.startswith(f"{option}=") for option in payload_options):
            if "{{prev_step_payload}}" in value or "__PREV_STEP_PAYLOAD__" in value:
                return True
    return False


def normalize_threshold_code_interpreter_args(cli_args: list[Any], question: str, runs: list[ModuleRun]) -> list[Any]:
    if not should_use_yahoo_daily_return_threshold_policy(question):
        return cli_args
    args = [str(value) for value in cli_args]
    if not has_cli_option(args, "--payload") and not has_cli_option(args, "--data-json") and not has_cli_option(args, "--data") and not has_cli_option(args, "--raw-data"):
        source_run = next(
            (
                run
                for run in reversed(runs)
                if run.payload_path.exists()
                and run.selected.filename == "yahoo_data.py"
            ),
            None,
        )
        if source_run:
            args.extend(["--payload", str(source_run.payload_path)])
    args = replace_cli_option(args, "--chart-type", "bar")
    if question and not has_cli_option(args, "--question") and not has_cli_option(args, "--instruction"):
        args.extend(["--question", question])
    if not has_cli_option(args, "--title"):
        args.extend(["--title", "单日涨跌幅阈值筛选"])
    return args


def replace_cli_option(args: list[str], option: str, value: str) -> list[str]:
    cleaned: list[str] = []
    index = 0
    while index < len(args):
        current = args[index]
        if current == option:
            index += 2 if index + 1 < len(args) and not args[index + 1].startswith("-") else 1
            continue
        if current.startswith(f"{option}="):
            index += 1
            continue
        cleaned.append(current)
        index += 1
    cleaned.extend([option, value])
    return cleaned


def normalize_yahoo_interval_args(args: list[str]) -> list[str]:
    interval_aliases = {
        "annual": "3mo",
        "yearly": "3mo",
        "year": "3mo",
        "1y": "3mo",
        "quarterly": "3mo",
        "quarter": "3mo",
        "monthly": "1mo",
        "month": "1mo",
        "weekly": "1wk",
        "week": "1wk",
        "daily": "1d",
        "day": "1d",
    }
    valid = {"1m", "2m", "5m", "15m", "30m", "60m", "90m", "1h", "4h", "1d", "5d", "1wk", "1mo", "3mo"}
    normalized = list(args)
    index = 0
    while index < len(normalized):
        value = normalized[index]
        if value == "--interval" and index + 1 < len(normalized):
            raw = normalized[index + 1].strip().lower()
            replacement = interval_aliases.get(raw, raw)
            if replacement in valid:
                normalized[index + 1] = replacement
                index += 2
                continue
            normalized = normalized[:index] + normalized[index + 2 :]
            continue
        if value.startswith("--interval="):
            raw = value.split("=", 1)[1].strip().lower()
            replacement = interval_aliases.get(raw, raw)
            if replacement in valid:
                normalized[index] = f"--interval={replacement}"
                index += 1
                continue
            normalized.pop(index)
            continue
        index += 1
    return normalized


def generate_mind_map_content_from_news(question: str, news_runs: list[ModuleRun]) -> str:
    articles = collect_news_articles(news_runs, question=question, limit=12)
    if not articles:
        return mind_map_no_evidence_content(question)

    api_key = model_api_key()
    if api_key:
        model_content = generate_mind_map_content_with_model(question, articles, api_key)
        if model_content and mind_map_content_is_specific(model_content, articles):
            return model_content
    return fallback_mind_map_content_from_news(question, articles)


def collect_news_articles(news_runs: list[ModuleRun], question: str = "", limit: int = 10) -> list[dict[str, str]]:
    articles: list[dict[str, str]] = []
    seen: set[str] = set()
    for run in news_runs:
        payload = read_payload(run.payload_path)
        answer = mind_map_clean_search_answer(str(payload.get("answer") or "").strip())
        if answer and not mind_map_answer_is_unusable(answer):
            title = mind_map_evidence_title_from_answer(question=question, payload=payload)
            key = f"answer:{plain_text_excerpt(answer, limit=120)}"
            if key not in seen:
                seen.add(key)
                articles.append(
                    {
                        "kind": "search_answer",
                        "title": title,
                        "date": "",
                        "summary": mind_map_preserve_excerpt(answer, limit=6000),
                        "source": display_source_name_for_article(payload, {}),
                        "url": "",
                    }
                )
                if len(articles) >= limit:
                    return articles
        raw_articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
        if not raw_articles and isinstance(payload.get("results"), list):
            raw_articles = payload["results"]
        for item in raw_articles:
            if not isinstance(item, dict):
                continue
            title = plain_text_excerpt(str(item.get("title") or ""), limit=120)
            if not title:
                title = plain_text_excerpt(str(item.get("finalUrl") or item.get("url") or ""), limit=120)
            if not title or title in seen:
                continue
            seen.add(title)
            if str(payload.get("type") or "") == "url-content-reader":
                summary_text = "\n".join(
                    str(value)
                    for value in (item.get("description"), item.get("text"))
                    if value
                )
                summary_limit = 6000
            else:
                summary_text = str(
                    item.get("summary")
                    or item.get("content_text")
                    or item.get("description")
                    or item.get("text")
                    or ""
                )
                summary_limit = 360
            summary_text = mind_map_clean_search_answer(summary_text)
            if not summary_text.strip():
                # Reference-only entries from Kimi contain domains/URLs but no
                # substantive text. They are useful for citations, but harmful
                # as mind-map content because they become source/date branches.
                continue
            url = str(item.get("url") or item.get("finalUrl") or "").strip()
            articles.append(
                {
                    "title": title,
                    "date": str(item.get("published_date") or str(item.get("published_at") or "")[:10]).strip(),
                    "summary": plain_text_excerpt(summary_text, limit=summary_limit),
                    "source": display_source_name_for_article(payload, item),
                    "url": url,
                }
            )
            if len(articles) >= limit:
                return articles
    return articles


def mind_map_answer_is_unusable(answer: str) -> bool:
    text = re.sub(r"\s+", " ", str(answer or "")).strip()
    if not text:
        return True
    lowered = text.lower()
    unusable_markers = (
        "请下达具体评测任务",
        "請下達具體評測任務",
        "当前未检索到可核验",
        "當前未檢索到可核驗",
        "未检索到可核验",
        "未檢索到可核驗",
        "未检索到可用",
        "未檢索到可用",
        "没有可用的搜索结果",
        "沒有可用的搜索結果",
        "请给我具体标的或问题",
        "请提供具体",
        "please provide",
        "no usable search results",
    )
    if any(marker in lowered for marker in unusable_markers):
        return True
    if text.startswith(("收到。", "好的。", "已在线。")) and len(text) < 260 and not re.search(r"\d|http|benchmark|Benchmark|论文|paper|榜", text):
        return True
    return False


def mind_map_evidence_title_from_answer(question: str, payload: dict[str, Any]) -> str:
    raw_query = str(payload.get("query") or payload.get("question") or question or "").strip()
    query = re.sub(r"(用|生成|整理|画|做)?(思维导图|思維導圖|脑图|腦圖|mind\s*map).*", "", raw_query, flags=re.IGNORECASE).strip(" ，。；;、")
    if query:
        return plain_text_excerpt(query, limit=80)
    payload_title = str(payload.get("title") or "").strip()
    if payload_title and not generic_mind_map_title(payload_title) and payload_title.lower() not in {"kimi 搜索", "kimi搜索"}:
        return plain_text_excerpt(payload_title, limit=80)
    return "搜索答案正文"


def mind_map_clean_search_answer(text: str) -> str:
    cleaned = str(text or "").strip()
    if not cleaned:
        return ""
    cleaned = re.sub(r"\[([^\]]+)\]\((?:https?://|www\.)[^)]+\)", r"\1", cleaned)
    cleaned = re.sub(r"https?://\S+|www\.\S+", "", cleaned)
    cleaned = re.sub(r"\b(?:php|html?)\?[\w=&%.\-]+[\w/&%.\-]*", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"(?m)^\s*[-*]?\s*来源[:：].*$", "", cleaned)
    cleaned = re.sub(r"(?m)^\s*[-*]?\s*资料来源[:：].*$", "", cleaned)
    cleaned = re.sub(r"(?m)^\s*[-*]?\s*出处[:：].*$", "", cleaned)
    cleaned = re.sub(r"(?:来源|资料来源|出处)[:：][^。；;\n]*(?:[。；;]\s*|$)", "", cleaned)
    cleaned = re.sub(r"来源(?:页面)?日期[:：][^，。；;\n]*(?:[，。；;]\s*)?", "", cleaned)
    cleaned = re.sub(r"发布时间[:：][^，。；;\n]*(?:[，。；;]\s*)?", "", cleaned)
    cleaned = re.sub(r"(?m)^\s*(?:来源|资料来源|参考|References?|Sources?)[:：].*$", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"(?m)^\s*[-*]?\s*注意[:：].*$", "", cleaned)
    cleaned = re.sub(r"(?m)^\s*[-*]?\s*(?:以上为资讯整理|不构成投资建议).*$", "", cleaned)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
    return cleaned.strip()


def mind_map_preserve_excerpt(text: str, limit: int = 6000) -> str:
    cleaned = str(text or "").strip()
    if len(cleaned) <= limit:
        return cleaned
    return cleaned[:limit].rstrip() + "…"


def generate_mind_map_content_with_model(question: str, articles: list[dict[str, str]], api_key: str) -> str:
    html_lang = html_lang_for_question(question)
    language_name = response_language_name(question)
    strict_language_rules = {
        "en": "Write all node text in natural English only.",
        "ja": "Write all node text in Japanese only.",
        "ko": "Write all node text in Korean only.",
        "th": "Write all node text in natural Thai only.",
        "zh-Hant": "Write all node text in Traditional Chinese only. Do not use Simplified Chinese.",
        "zh-CN": "Write all node text in Simplified Chinese only.",
        "es": "Write all node text in Spanish only.",
        "fr": "Write all node text in French only.",
        "de": "Write all node text in German only.",
        "pt": "Write all node text in Portuguese only.",
    }.get(html_lang, f"Write all node text in {language_name} only.")
    prompt = (
        "You are creating a mind map from fetched article/page content or search results.\n"
        f"{strict_language_rules}\n"
        "The user question is the organizing goal. Build the mind map to directly answer what the user asked, not to inventory sources, pages, snippets, or retrieval results.\n"
        "Before writing nodes, infer the user's requested analysis frame from the question: for example market performance, company development history, agent evaluation framework, financial comparison, event timeline, or risk checklist. First-level branches must be this answer frame, not website names, media names, source types, or article titles.\n"
        "Use ONLY the supplied content. If a full article body is provided, summarize the article's argument and evidence rather than copying titles, navigation text, or source snippets.\n"
        "The content logic, grouping, wording, and depth must be inferred from the actual information in the supplied content.\n"
        "The root title must be a topic-specific answer title inferred from the user question and evidence. Never use generic titles such as 思维导图, 今日市场热点, Market Hotspots, Summary, or Mind Map when a more specific title is possible.\n"
        "For a news article, prefer themes such as: core event, key evidence/numbers, background and causes, industry-chain/company impact, market reaction, disagreements, risks, and next checkpoints, but only when supported by the article.\n"
        "For a market-summary request, first-level themes should be decision-useful clusters such as market breadth, leading sectors, lagging sectors, capital flow/liquidity, policy or macro triggers, earnings/catalysts, risks/divergences, and next checkpoints. Choose only themes supported by the evidence.\n"
        "Preserve specialized finance/semiconductor terms when literal translation would be awkward, such as low-NA EUV, DUV immersion, capex, guidance, gross margin, and Installed Base Management.\n"
        "Mind-map layout constraints: keep every node short but specific. For Chinese/Japanese/Korean/Thai, each node should be at most 24 characters when possible and never exceed 34 characters. For alphabetic languages, each node should be at most 8 words when possible and never exceed 12 words.\n"
        "Depth requirement: when the supplied content has enough substance, use 3-4 hierarchy levels: root -> first-level theme -> concrete event/entity -> detail such as number, date, cause, impact, disagreement, or next checkpoint.\n"
        "Breadth requirement: use 4-6 first-level themes when possible. Under each first-level theme, include 2-4 concrete branches. Under concrete branches, include 1-3 deeper detail nodes when supported. If the evidence has enough substance, produce at least 12 informative leaf nodes.\n"
        "Do not put a full sentence with multiple facts into one node. Split it into a short parent node and child detail nodes.\n"
        "Every non-root branch should carry real information from the supplied content: named entities, products, business lines, regions, dates, figures, direction of change, causal factor, affected party, or specific implication.\n"
        "The required format is Markdown hierarchy only. It does not define or imply any content categories.\n"
        "Required hierarchy: one # root title; then ## first-level themes; then - second-level content branches; then indented sub-bullets for deeper details. Add deeper indentation only when the content itself naturally supports it.\n"
        "Do not treat placeholder words such as root, topic, branch, detail, source, date, impact, disagreement, data, cause, or entity as required node types. Do not output those placeholders literally.\n"
        "Avoid generic or empty nodes such as opportunities, risks, market drivers, price behavior, investor focus, impact, cause, data, trend, or key points unless the next level names the specific object and fact.\n"
        "Do not mechanically add metadata or commentary nodes. Never create branches named 数据来源、数据来源与日期、来源、出处、日期、参考、Source, Sources, Date, or Method. The UI already handles citations separately. Include a date only inside a substantive event/value node where the date changes the meaning.\n"
        "Never create nodes from citation/provenance lines such as media/source names plus timestamps or links. Examples to omit as nodes: 中国经济网收评，2026-08-11 15:11; 东方财富收评快讯，2026-08-11 16:28; 新浪财经/证券时报人民财讯; 华尔街见闻; source page; reference link; published date. Use facts from those lines only if they answer the user question, and rewrite them under a substantive branch.\n"
        "Do not add leaves whose only purpose is provenance, such as 来自东方财富、行情数据日期、另含历史行情页、source page, reference link, or published date. Convert them into substantive facts or omit them.\n"
        "For market-performance questions such as 今天A股市场表现, organize by performance dimensions: overall index direction, market breadth, turnover/liquidity, leading sectors, lagging sectors, and bottom-line interpretation. Do not organize by news outlet or article source.\n"
        "For evaluation/research-framework questions, organize by benchmark/use case, evaluation object, metric/split, comparability caveats, and recommended usage. Do not organize by website or search result.\n"
        "Do not add low-value missing-data leaves such as 原文未披露、未完整披露、无法核实、未提供、not disclosed, unavailable, or unknown; just omit unsupported missing details.\n"
        "Make the map richer than a title list: merge duplicate results, cluster related facts, surface source disagreements, and connect evidence to implications. Do not invent unsupported analysis.\n"
        "Return JSON only: {\"content\":\"# <generated title>\\n## <generated first-level theme>\\n- <generated content branch>\\n  - <generated content detail>\"}.\n\n"
        f"User question: {question}\n"
        f"Articles:\n{json.dumps(articles, ensure_ascii=False, indent=2)}"
    )
    try:
        client = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL)
        completion = create_chat_completion(
            client,
            json_object=True,
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
            max_tokens=2600,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"Mind map content model call failed: {exc}", file=sys.stderr)
        return ""
    parsed = parse_json_object(completion_text(completion, "行动计划模型"))
    content = str((parsed or {}).get("content") or "").strip()
    if not content.startswith("#"):
        return ""
    return to_traditional_chinese(content) if html_lang == "zh-Hant" else content


def mind_map_content_is_specific(content: str, articles: list[dict[str, str]]) -> bool:
    lowered = content.lower()
    root_title = mind_map_title_from_content(content)
    if generic_mind_map_title(root_title):
        return False
    forbidden_metadata_terms = (
        "数据来源",
        "數據來源",
        "资料来源",
        "資料來源",
        "来源与日期",
        "來源與日期",
        "来源和日期",
        "來源和日期",
        "行情数据日期",
        "行情數據日期",
        "另含搜刮",
        "另含搜索",
        "历史行情页",
        "歷史行情頁",
        "source and date",
        "data source",
        "sources",
        "references",
        "methodology",
    )
    heading_lines = [
        re.sub(r"^[#\-\s]+", "", line).strip().lower()
        for line in content.splitlines()
        if line.strip().startswith(("#", "-"))
    ]
    if any(any(term.lower() in line for term in forbidden_metadata_terms) for line in heading_lines):
        return False
    generic_terms = (
        "市场驱动因素",
        "市場驅動因素",
        "价格表现",
        "價格表現",
        "投资者关注",
        "投資者關注",
        "market drivers",
        "price behavior",
        "investor focus",
        "opportunities",
        "risks",
    )
    if any(term.lower() in lowered for term in generic_terms):
        article_terms = []
        for article in articles:
            for field in ("title", "source"):
                value = str(article.get(field) or "").strip()
                if value:
                    article_terms.extend(token for token in re.split(r"[\s,，:：;；|｜()（）/\-]+", value) if len(token) >= 3)
        if not any(token.lower() in lowered for token in article_terms[:80]):
            return False
    leaf_lines = [line.strip() for line in content.splitlines() if line.strip().startswith("-")]
    if not leaf_lines:
        return False
    if len(articles) >= 3 and len(leaf_lines) < 8:
        return False
    concrete_hits = 0
    source_names = {str(article.get("source") or "").strip().lower() for article in articles if article.get("source")}
    for line in leaf_lines:
        lower_line = line.lower()
        if re.search(r"\b[A-Z]{2,6}\b|\d|20\d{2}", line):
            concrete_hits += 1
            continue
        if any(source and source in lower_line for source in source_names):
            concrete_hits += 1
    return concrete_hits >= max(2, min(5, len(leaf_lines) // 3))


def fallback_mind_map_content_from_news(question: str, articles: list[dict[str, str]]) -> str:
    """Build a minimal markdown mind-map from model/search answer text only.

    This fallback intentionally does not classify raw search results into
    market/news buckets. Mind-map content should come from the LLM summary
    stage; when that stage is unavailable, use the cleaned answer text if it is
    substantive, otherwise emit a no-evidence note. The renderer script should
    not invent content categories.
    """
    answer_article = next(
        (
            article
            for article in articles
            if article.get("kind") == "search_answer" and str(article.get("summary") or "").strip()
        ),
        None,
    )
    if answer_article:
        answer_content = fallback_mind_map_content_from_answer(question, str(answer_article.get("summary") or ""))
        if answer_content:
            return answer_content

    combined_parts: list[str] = []
    for article in articles:
        if str(article.get("kind") or "") == "search_answer":
            continue
        summary = mind_map_clean_search_answer(str(article.get("summary") or "").strip())
        title = str(article.get("title") or "").strip()
        if not summary or mind_map_answer_is_unusable(summary):
            continue
        if mind_map_node_is_low_value(title) and len(summary) < 80:
            continue
        combined_parts.append(summary)
    combined = "\n".join(combined_parts[:4]).strip()
    if combined:
        answer_content = fallback_mind_map_content_from_answer(question, combined)
        if answer_content:
            return answer_content
    return mind_map_no_evidence_content(question)


def fallback_mind_map_content_from_answer(question: str, answer: str) -> str:
    lang = html_lang_for_question(question)
    title = mind_map_topic_title_from_question(question) or mind_map_title_from_question_fallback(question)
    cleaned = mind_map_clean_search_answer(answer)
    if mind_map_answer_is_unusable(cleaned):
        return ""
    if not cleaned:
        return ""
    sections: list[tuple[str, list[tuple[str, list[str]]]]] = []
    current_heading = ""
    current_items: list[tuple[str, list[str]]] = []

    def flush_heading() -> None:
        nonlocal current_heading, current_items
        if current_heading and current_items:
            sections.append((current_heading, current_items))
        current_heading = ""
        current_items = []

    for raw_line in cleaned.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        heading_match = re.match(r"^(?:#{1,4}\s*)?\*\*([^*]{2,40})\*\*[:：]?\s*$", line)
        if not heading_match:
            heading_match = re.match(r"^#{1,4}\s+(.{2,40})$", line)
        if heading_match:
            heading = mind_map_clean_node_text(heading_match.group(1))
            if heading and not mind_map_node_is_low_value(heading):
                flush_heading()
                current_heading = heading
            continue
        bullet_match = re.match(r"^[-*]\s+(.+)$", line)
        if not bullet_match:
            continue
        bullet = mind_map_clean_node_text(bullet_match.group(1))
        if not bullet or mind_map_node_is_low_value(bullet):
            continue
        parent, details = split_mind_map_bullet_to_node(bullet, lang)
        if not parent:
            continue
        if not current_heading:
            current_heading = "核心要点" if lang in {"zh-CN", "zh-Hant"} else "Key Takeaways"
        current_items.append((parent, details))
    flush_heading()

    if not sections:
        details = split_mind_map_summary_details(cleaned, lang)
        if not details:
            return ""
        sections = [("核心要点" if lang in {"zh-CN", "zh-Hant"} else "Key Takeaways", [(detail, []) for detail in details[:8]])]

    output = [f"# {title}"]
    for heading, items in sections[:6]:
        if mind_map_node_is_low_value(heading):
            continue
        output.append(f"## {heading}")
        for parent, details in items[:5]:
            output.append(f"- {parent}")
            for detail in details[:4]:
                output.append(f"  - {detail}")
    content = "\n".join(output)
    return to_traditional_chinese(content) if lang == "zh-Hant" else content


def split_mind_map_bullet_to_node(text: str, lang: str) -> tuple[str, list[str]]:
    normalized = mind_map_clean_node_text(text)
    if not normalized:
        return "", []
    parts = re.split(r"[:：]", normalized, maxsplit=1)
    if len(parts) == 2 and len(parts[0]) <= 34:
        parent = mind_map_clean_node_text(parts[0])
        tail = mind_map_clean_node_text(parts[1])
        details = split_mind_map_summary_details(tail, lang)
        return parent, [detail for detail in details if detail and not mind_map_node_is_low_value(detail)]
    if lang in {"zh-CN", "zh-Hant", "ja", "ko"} and len(normalized) > 54:
        cut = 54
        for separator in ("；", "，", "、", ";", ",", " "):
            index = normalized.rfind(separator, 24, 55)
            if index > 24:
                cut = index
                break
        parent = mind_map_clean_node_text(normalized[:cut])
        details = split_mind_map_summary_details(normalized[cut:], lang)
        return parent, [detail for detail in details if detail and not mind_map_node_is_low_value(detail)]
    if len(normalized.split()) > 12:
        words = normalized.split()
        parent = " ".join(words[:10])
        detail = " ".join(words[10:])
        return parent, [plain_text_excerpt(detail, 90)] if detail else []
    return normalized, []


def mind_map_clean_node_text(text: str) -> str:
    cleaned = mind_map_clean_search_answer(text)
    cleaned = re.sub(r"^[#\-*\s]+", "", cleaned)
    cleaned = re.sub(r"\*\*|__", "", cleaned)
    cleaned = re.sub(r"(?:来源|资料来源|出处)[:：].*$", "", cleaned)
    cleaned = re.sub(r"(?:Source|Sources|Reference|References)[:：].*$", "", cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r"\s+", " ", cleaned)
    return cleaned.strip(" ，。；;、")


def mind_map_node_is_low_value(text: str) -> bool:
    lowered = str(text or "").strip().lower()
    if not lowered:
        return True
    if re.fullmatch(r"(?:[a-z0-9-]+\.)+[a-z]{2,}(?:/.*)?", lowered):
        return True
    if re.search(r"\b(?:php|html?)\?[\w=&%.\-]+", lowered):
        return True
    low_value_terms = (
        "数据来源",
        "數據來源",
        "资料来源",
        "資料來源",
        "来源",
        "來源",
        "出处",
        "日期",
        "参考",
        "參考",
        "methodology",
        "published",
        "行情数据日期",
        "历史行情页",
        "未完整披露",
        "未披露",
        "未提供",
        "无法核实",
        "無法核實",
        "not disclosed",
        "unavailable",
        "unknown",
    )
    if any(term in lowered for term in low_value_terms):
        return True
    return bool(re.search(r"\b(?:source|sources|reference|references)\b", lowered))


def mind_map_topic_title_from_question(question: str) -> str:
    text = re.sub(r"\s+", " ", str(question or "").strip())
    if not text:
        return ""
    text = re.sub(
        r"(用|以|通过)?\s*(思维导图|思維導圖|脑图|腦圖|mind\s*map|markmap)\s*(整理|总结|梳理|展示|呈现|呈現)?(给我|給我|一下)?",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"^(帮我|帮忙|请|麻烦你|你)?\s*(搜一下|搜索|检索|查一下|查询|找一下|看一下)\s*", "", text)
    text = re.sub(r"(相关的)?(资料|資訊|信息|内容|材料)\s*$", "", text)
    text = text.strip(" ，。；;、:：")
    if not text:
        return ""
    lang = html_lang_for_question(question)
    base = plain_text_excerpt(text, limit=32 if lang in {"zh-CN", "zh-Hant", "ja", "ko"} else 64)
    if lang in {"zh-CN", "zh-Hant"}:
        if any(term in base.lower() for term in ("评测", "評測", "benchmark", "bench", "评价", "評價")):
            title = f"{base}要点整理"
        else:
            title = f"{base}资料整理"
        return to_traditional_chinese(title) if lang == "zh-Hant" else title
    return base


def mind_map_no_evidence_content(question: str) -> str:
    lang = html_lang_for_question(question)
    title = mind_map_topic_title_from_question(question) or mind_map_title_from_question_fallback(question)
    if lang == "zh-Hant":
        return to_traditional_chinese(
            f"# {title}\n"
            "## 未檢索到可用資料\n"
            "- 搜索結果沒有返回可核驗正文\n"
            "- 建議補充具體對象、榜單或 benchmark\n"
            "- 可指定時間窗與輸出指標"
        )
    if lang == "zh-CN":
        return (
            f"# {title}\n"
            "## 未检索到可用资料\n"
            "- 搜索结果没有返回可核验正文\n"
            "- 建议补充具体对象、榜单或 benchmark\n"
            "- 可指定时间窗与输出指标"
        )
    return (
        f"# {title}\n"
        "## No usable evidence found\n"
        "- Search returned no verifiable body text\n"
        "- Specify the target agent, leaderboard, or benchmark\n"
        "- Add a time window and desired metrics"
    )


def mind_map_title_from_question_fallback(question: str) -> str:
    text = plain_text_excerpt(str(question or "Mind Map").strip(), limit=48)
    return text or "Mind Map"


def mind_map_title_from_content(content: str) -> str:
    for line in str(content or "").splitlines():
        stripped = line.strip()
        if stripped.startswith("# "):
            return stripped[2:].strip()
    return ""


def generic_mind_map_title(title: str | None) -> bool:
    normalized = re.sub(r"[\s#：:|｜_-]+", "", str(title or "").strip().lower())
    if not normalized:
        return True
    generic = {
        "思维导图",
        "思維導圖",
        "脑图",
        "腦圖",
        "今日市场热点",
        "今日市場熱點",
        "市场热点",
        "市場熱點",
        "marketmindmap",
        "mindmap",
        "summary",
        "marketsummary",
        "markethotspots",
    }
    return normalized in generic


def split_mind_map_summary_details(summary: str, lang: str) -> list[str]:
    normalized = re.sub(r"\s+", " ", summary).strip()
    if not normalized:
        return []
    if lang in {"zh-CN", "zh-Hant", "ja", "ko"}:
        parts = [part.strip(" ，。；;、") for part in re.split(r"[。；;]\s*", normalized) if part.strip(" ，。；;、")]
    else:
        parts = [part.strip(" .;") for part in re.split(r"(?<=[.;])\s+", normalized) if part.strip(" .;")]
    if len(parts) <= 1 and len(normalized) > 80:
        parts = [normalized[index : index + 80].strip() for index in range(0, len(normalized), 80)]
    low_value_terms = (
        "未完整披露",
        "未披露",
        "未提供",
        "无法核实",
        "無法核實",
        "不可得",
        "缺失",
        "not disclosed",
        "unavailable",
        "unknown",
    )
    return [
        plain_text_excerpt(part, 90)
        for part in parts
        if part and not any(term.lower() in part.lower() for term in low_value_terms)
    ][:5]


def is_yahoo_financial_position_request(question: str) -> bool:
    text = str(question or "")
    lower = text.lower()
    source_requested = any(term in lower or term in text for term in ("yahoo", "yahoo finance", "雅虎"))
    position_requested = any(
        term in lower or term in text
        for term in (
            "financial position",
            "financial condition",
            "balance sheet",
            "财务状况",
            "財務狀況",
            "资产负债",
            "資產負債",
        )
    )
    return source_requested and position_requested


def yahoo_requested_financial_metric(question: str) -> str:
    text = str(question or "")
    lower = text.lower()
    candidates = (
        ("operating_income", ("operating income", "营业利润", "營業利潤")),
        ("gross_profit", ("gross profit", "毛利润", "毛利潤")),
        ("net_income", ("net income", "net profit", "净利润", "淨利潤", "净收入", "淨收入")),
        ("total_revenue", ("total revenue", "revenue", "营收", "營收", "营业收入", "營業收入")),
    )
    for metric, terms in candidates:
        if any(term in lower or term in text for term in terms):
            return metric
    return ""


def is_yahoo_single_financial_metric_request(question: str) -> bool:
    return (
        requested_yahoo_data_source(question)
        and bool(yahoo_requested_financial_metric(question))
        and not is_yahoo_financial_position_request(question)
    )


def apply_yahoo_single_financial_metric_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not is_yahoo_single_financial_metric_request(question):
        return route
    component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    if not component:
        return route
    metric = yahoo_requested_financial_metric(question)
    steps = normalize_route_steps(route)
    code = specific_code_for_route(question, steps)
    lower = str(question or "").lower()
    args = ["--metric", metric, "--language", html_lang_for_question(question)]
    strict_period = ""
    if any(term in lower or term in question for term in ("季度", "季报", "季報", "quarter", "quarterly")):
        args.extend(["--period-type", "quarterly"])
        strict_period = "quarterly"
    elif any(term in lower or term in question for term in ("年度", "年报", "年報", "财年", "財年", "annual", "fiscal year", "fy")):
        args.extend(["--period-type", "annual"])
        strict_period = "annual"
    if any(term in lower or term in question for term in ("最新", "最近一期", "latest", "current")):
        args.extend(["--range-length", "1"])
    else:
        args.extend(["--range-length", "5"])
    metric_labels = {
        "total_revenue": "营收",
        "net_income": "净利润",
        "operating_income": "营业利润",
        "gross_profit": "毛利润",
    }
    label = metric_labels.get(metric, metric)
    step = {
        "script": "yahoo_data.py",
        "label": component.label,
        "code": code,
        "cli_args": args,
        "thought": f"仅从 Yahoo 获取目标公司的{label}。",
        "reason": "用户明确指定 Yahoo 数据源，因此不调用 AInvest 财务、行情、估值、现金流或新闻模块。",
        "expected_observation": (
            f"获得 Yahoo 可提供的最新{label}、报告期和财务币种；若 Yahoo 未提供所请求的{strict_period}字段，返回正常的数据不可用状态且不替换口径。"
            if strict_period
            else f"获得 Yahoo 可提供的最新{label}、报告期和财务币种；若历史时间序列缺失，使用 Yahoo 最新财务快照并明确标记 TTM。"
        ),
        "next_thought": f"直接依据 Yahoo 返回值回答最新{label}。",
    }
    updated = dict(route)
    updated["steps"] = [step]
    updated["reason"] = "用户指定 Yahoo 数据源，已将计划收敛为单一 Yahoo 财务指标调用，不混入其他业务数据或搜索。"
    updated["_display_strategy"] = updated["reason"]
    updated["_strategy_source"] = "policy"
    updated["_policy_display_strategy_override"] = True
    return updated


