def is_net_profit_yoy_bar_line_request(question: str) -> bool:
    lower = str(question or "").lower()
    has_net_profit = any(term in lower or term in question for term in ("净利润", "淨利潤", "净收入", "淨收入", "net income", "net profit"))
    has_yoy = any(term in lower or term in question for term in ("同比", "年增", "年增长", "年增長", "yoy", "year over year", "year-on-year"))
    has_combo_chart = any(term in lower or term in question for term in ("柱折", "组合图", "組合圖", "bar-line", "bar line", "combo chart"))
