def financial_statement_symbol_for_question(question: str) -> str:
    return infer_symbol_from_question(question) or extract_stock_code(question) or "MARKET"


def financial_search_subject(question: str, code: str) -> str:
    text = str(question or "")
    aliases = (
        (("阿里巴巴", "alibaba"), "阿里巴巴"),
        (("腾讯控股", "騰訊控股", "腾讯", "騰訊", "tencent"), "腾讯控股"),
        (("英伟达", "英偉達", "nvidia"), "英伟达"),
        (("苹果", "蘋果", "apple"), "苹果公司"),
        (("微软", "微軟", "microsoft"), "微软"),
        (("谷歌", "alphabet", "google"), "Alphabet"),
        (("亚马逊", "亞馬遜", "amazon"), "亚马逊"),
        (("特斯拉", "tesla"), "特斯拉"),
        (("meta", "facebook"), "Meta"),
    )
    lower = text.lower()
    for names, label in aliases:
        if any(name in text or name in lower for name in names):
            return label
    return code if code and code != "MARKET" else "用户所问公司"


def apply_net_profit_yoy_bar_line_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not is_net_profit_yoy_bar_line_request(question):
        return route
    annual_period = is_annual_financial_period_request(question)
    count = requested_fiscal_year_count(question, default=4) if annual_period else requested_quarter_count(question, default=4)
    comparison_periods = count + 1 if annual_period else count + 4
    period_type = "annual" if annual_period else "quarterly"
    period_zh = "财年" if annual_period else "季度"
    period_baseline_zh = "上年" if annual_period else "上年同期"
    code = financial_statement_symbol_for_question(question)
    title = f"最近{count}个{period_zh}净利润与同比增长"
