def apply_yahoo_first_trading_day_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not should_use_yahoo_first_trading_day_policy(question):
        return route
    yahoo_component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    code_component = ALLOWED_COMPONENTS_BY_FILE.get("code_interpreter.py")
    if not yahoo_component or not code_component:
        return route
    steps = normalize_route_steps(route)
    code = (
        next(
            (
                str(step.get("code") or "").strip().upper()
                for step in steps
                if str(step.get("code") or "").strip().upper() not in {"", "MARKET", "ALL", "GENERAL", "NEWS"}
            ),
            "",
        )
        or infer_symbol_from_question(question)
        or extract_stock_code(question)
        or "MARKET"
    )
    start_year, end_year = infer_year_range_from_question(question)
    month = infer_month_from_question(question) or 1
    month_name = f"{month}月" if html_lang_for_question(question) != "en" else dt.date(2000, month, 1).strftime("%B")
    yahoo_step = {
        "script": "yahoo_data.py",
        "label": yahoo_component.label,
        "code": code,
        "cli_args": [
            "--metric",
            "adj_close",
            "--start-date",
            f"{start_year or 1990}-01-01",
            "--end-date",
            f"{end_year or dt.date.today().year}-12-31",
            "--interval",
            "1d",
            "--chart-type",
            "line",
            "--title",
            f"{code} 日频复权收盘价",
        ],
        "reason": "用户要求按年份/月筛选首个交易日，这是行情日线派生计算；先用 Yahoo 拉取日频价格，不使用网页搜索。",
    }
    code_step = {
        "script": "code_interpreter.py",
        "label": code_component.label,
        "code": code,
        "cli_args": [
            "--chart-type",
            "bar",
            "--title",
            f"{code} {start_year or ''}-{end_year or ''} 每年{month_name}首个交易日",
            "--question",
            question,
        ],
        "reason": "从 Yahoo 日频 payload 中按年份筛选指定月份的第一个可用交易日，输出年份、交易日期和价格，并渲染柱状图。",
        "expected_observation": "每年一条记录：year、firstTradingDate、close/adjClose。",
    }
    updated = dict(route)
    updated["steps"] = [yahoo_step, code_step]
    policy_reason = "已按首个交易日派生计算策略强制改为 Yahoo 日线 + Code Interpreter。"
    updated["reason"] = policy_reason
    return updated


def apply_yahoo_monthly_cumulative_route_policy(question: str, route: dict[str, Any]) -> dict[str, Any]:
    if not should_use_yahoo_monthly_cumulative_policy(question):
        return route
    yahoo_component = ALLOWED_COMPONENTS_BY_FILE.get("yahoo_data.py")
    code_component = ALLOWED_COMPONENTS_BY_FILE.get("code_interpreter.py")
    if not yahoo_component or not code_component:
        return route
    steps = normalize_route_steps(route)
    code = (
        next(
            (
                str(step.get("code") or "").strip().upper()
                for step in steps
                if str(step.get("code") or "").strip().upper() not in {"", "MARKET", "ALL", "GENERAL", "NEWS"}
            ),
            "",
        )
        or infer_symbol_from_question(question)
        or extract_stock_code(question)
        or "MARKET"
    )
    start_year, end_year = infer_year_range_or_recent_window(question)
    month = infer_month_from_question(question) or 1
    month_name = f"{month}月" if html_lang_for_question(question) != "en" else dt.date(2000, month, 1).strftime("%B")
    yahoo_step = {
        "script": "yahoo_data.py",
        "label": yahoo_component.label,
        "code": code,
        "cli_args": [
            "--metric",
            "adj_close",
            "--start-date",
            f"{start_year}-01-01",
            "--end-date",
            f"{end_year}-12-31",
            "--interval",
            "1d",
            "--chart-type",
            "line",
            "--title",
            f"{code} 日频复权收盘价",
        ],
        "reason": "用户要求按年份计算某个月累计涨幅；必须先用 Yahoo 拉取真实日频价格，再用 Python 按每年该月首尾交易日计算。",
    }
    code_step = {
        "script": "code_interpreter.py",
        "label": code_component.label,
        "code": code,
        "cli_args": [
            "--chart-type",
            "bar",
            "--title",
            f"{code} {start_year}-{end_year} 每年{month_name}累计涨幅",
            "--question",
            question,
        ],
        "reason": "从 Yahoo 日频 payload 中按年份筛选指定月份，使用该月第一个与最后一个可用交易日计算累计涨幅并渲染柱状图。",
        "expected_observation": "每年一条记录：year、firstTradingDate、lastTradingDate、returnPct。",
    }
    updated = dict(route)
    updated["steps"] = [yahoo_step, code_step]
    updated["reason"] = "已按每年指定月份累计涨幅策略强制改为 Yahoo 日线 + Code Interpreter。"
    return updated


def should_use_yahoo_market_cap_tool(question: str) -> bool:
    lower = question.lower()
    if should_use_yahoo_grouped_line_cumulative_policy(question):
        return False
    return (
        any(term.lower() in lower for term in MARKET_CAP_TERMS)
        and any(term.lower() in lower for term in HISTORICAL_LINE_TERMS)
    )


def should_use_yahoo_dynamic_line_tool(question: str) -> bool:
    if requested_grouped_bar_chart(question) or requested_grouped_line_chart(question) or requested_bar_line_chart(question):
        return False
    lower = question.lower()
    return (
        any(term.lower() in lower for term in CUMULATIVE_RETURN_TERMS)
        and (
            any(term.lower() in lower for term in DYNAMIC_LINE_TERMS)
            or any(term.lower() in lower for term in COMPARE_TERMS)
        )
        and len(infer_symbols_from_question(question)) >= 2
    )


def should_use_yahoo_grouped_line_cumulative_policy(question: str) -> bool:
    if (
        requested_grouped_bar_chart(question)
        or requested_bar_line_chart(question)
        or any(term.lower() in question.lower() for term in DYNAMIC_LINE_TERMS)
        or should_use_yahoo_daily_return_threshold_policy(question)
        or should_use_yahoo_first_trading_day_policy(question)
        or should_use_yahoo_monthly_cumulative_policy(question)
    ):
        return False
    lower = question.lower()
    symbols = infer_symbols_from_question(question)
    has_investment_value_intent = has_investment_value_or_profit_intent(question)
    has_return_intent = any(term.lower() in lower for term in CUMULATIVE_RETURN_TERMS) or (
        any(term in lower or term in question for term in ("收益率", "收益变化", "涨幅", "return", "returns", "gain"))
        and not any(term in lower or term in question for term in ("单日", "日收益率", "daily return", "daily returns"))
    ) or has_investment_value_intent
    has_time_window = any(term.lower() in lower for term in HISTORICAL_LINE_TERMS)
    return len(symbols) >= 2 and has_return_intent and has_time_window


