def infer_year_range_or_recent_window(question: str) -> tuple[int, int]:
    start_year, end_year = infer_year_range_from_question(question)
    if start_year and end_year:
        return start_year, end_year
    current_year = dt.date.today().year
    lower = question.lower()
    match = re.search(r"(?:过去|過去|近|最近|last|past)\s*(\d{1,2})\s*(?:年|years?)", lower)
    if match:
        years = max(1, min(30, int(match.group(1))))
        return current_year - years + 1, current_year
    if any(term in lower or term in question for term in ("过去十年", "過去十年", "近十年", "最近十年", "last decade")):
        return current_year - 9, current_year
    return current_year - 9, current_year


def should_use_yahoo_first_trading_day_policy(question: str) -> bool:
    lower = question.lower()
    has_first = any(term in lower or term in question for term in ("首个交易日", "首個交易日", "第一个交易日", "第一個交易日", "first trading day"))
    has_period = any(term in lower or term in question for term in ("每年", "每一年", "逐年", "各年", "每月", "每个月", "每個月", "每年1月", "yearly", "each year"))
    has_symbol = bool(infer_symbol_from_question(question) or extract_stock_code(question))
    return has_first and has_period and has_symbol


def infer_year_range_from_question(question: str) -> tuple[int | None, int | None]:
    text = str(question or "")
    range_match = re.search(r"((?:19|20)\d{2})\s*(?:年)?\s*(?:至|到|~|-|—|–|through|to)\s*((?:19|20)\d{2})", text, flags=re.I)
    if range_match:
        start = int(range_match.group(1))
        end = int(range_match.group(2))
        return (min(start, end), max(start, end))
    years = [int(item) for item in re.findall(r"(?:19|20)\d{2}", text)]
    if len(years) >= 2:
        return (min(years), max(years))
    if len(years) == 1:
        return (years[0], years[0])
    return (None, None)


def infer_yahoo_range_for_year_range(start_year: int | None, end_year: int | None) -> str:
    current_year = dt.date.today().year
    if start_year and current_year - start_year >= 10:
        return "max"
    if start_year and current_year - start_year >= 5:
        return "10y"
    if start_year and current_year - start_year >= 2:
        return "5y"
    return "2y"


def infer_month_from_question(question: str) -> int | None:
    text = str(question or "").lower()
    chinese_match = re.search(r"(\d{1,2})\s*月", text)
    if chinese_match:
        month = int(chinese_match.group(1))
        return month if 1 <= month <= 12 else None
    english_months = {
        "january": 1,
        "jan": 1,
        "february": 2,
        "feb": 2,
        "march": 3,
        "mar": 3,
        "april": 4,
        "apr": 4,
        "may": 5,
        "june": 6,
        "jun": 6,
        "july": 7,
        "jul": 7,
        "august": 8,
        "aug": 8,
        "september": 9,
        "sep": 9,
        "october": 10,
        "oct": 10,
        "november": 11,
        "nov": 11,
        "december": 12,
        "dec": 12,
    }
    for name, month in english_months.items():
        if name in text:
            return month
    return None


def infer_symbol_from_question(question: str) -> str | None:
    return extract_stock_code(str(question or ""))


def infer_symbols_from_question(question: str) -> list[str]:
    text = original_question_without_execution_feedback(question)
    symbols: list[str] = []
    for match in re.finditer(r"(?<![A-Za-z0-9])[A-Z]{1,6}(?:[.-][A-Z]{1,3})?(?![A-Za-z0-9])", text):
        ticker = match.group(0)
        # Regulatory/form identifiers such as S-1 are not ticker symbols.
        if re.match(r"-\d", text[match.end() :]):
            continue
        if ticker in {"AI", "IPO", "ETF", "GDP", "CPI", "USD", "US"}:
            continue
        symbols.append(ticker)
    deduped: list[str] = []
    for symbol in symbols:
        if symbol not in deduped:
            deduped.append(symbol)
    return deduped


def infer_yahoo_range_from_question(question: str) -> str:
    text = str(question or "").lower()
    if any(term in text for term in ("十年", "10年", "10 年", "10-year", "10 years", "decade")):
        return "10y"
    if any(term in text for term in ("五年", "5年", "5 年", "5-year", "5 years")):
        return "5y"
    if any(term in text for term in ("三年", "3年", "3 年", "3-year", "3 years")):
        return "5y"
    if any(term in text for term in ("两年", "2年", "2 年", "2-year", "2 years")):
        return "2y"
    if any(term in text for term in ("半年", "6个月", "6 個月", "6 months")):
        return "6mo"
    if any(term in text for term in ("三个月", "3个月", "3 個月", "近三月", "最近三月", "3 months")):
        return "3mo"
    if any(term in text for term in ("一个月", "一個月", "1个月", "1 個月", "近一月", "最近一月", "最近一个月", "最近一個月", "1 month")):
        return "1mo"
    return "1y"


def infer_yahoo_explicit_period_dates(question: str) -> tuple[dt.date | None, dt.date | None]:
    text = str(question or "")
    month = infer_month_from_question(text)
    if not month:
        return (None, None)
    today = dt.date.today()
    lower = text.lower()
    year: int | None = None
    if "去年" in text or "上年" in text or "last year" in lower:
        year = today.year - 1
    elif "今年" in text or "本年" in text or "this year" in lower:
        year = today.year
    else:
        explicit_years = [int(item) for item in re.findall(r"(?:19|20)\d{2}", text)]
        if explicit_years:
            year = explicit_years[0]
    if not year:
        return (None, None)
    start = dt.date(year, month, 1)
    end = today
    if start > end:
        return (None, None)
    return (start, end)


