def normalize_route_steps(route: dict[str, Any]) -> list[dict[str, Any]]:
    raw_steps = route.get("steps")
    if isinstance(raw_steps, list) and raw_steps:
        steps = [step for step in raw_steps if isinstance(step, dict)]
    else:
        steps = [route]
    if not steps:
        raise HTTPException(status_code=500, detail="模型没有返回可执行模块。")
    normalized: list[dict[str, Any]] = []
    for step in steps[:MAX_ROUTE_STEPS]:
        item = dict(step)
        item["script"] = normalize_script_filename(Path(str(item.get("script") or item.get("script_file") or item.get("file") or "")).name)
        if not item["script"]:
            for key in ("tool", "action", "skill"):
                candidate = str(item.get(key) or "").strip()
                if candidate in AGENT_ONLY_TOOLS:
                    item["_agent_tool"] = candidate
                    break
                if candidate.endswith(".py"):
                    item["script"] = normalize_script_filename(candidate)
                    break
        if item["script"] in AGENT_ONLY_TOOLS:
            continue
        if not item["script"] and item.get("_agent_tool"):
            continue
        question_context = str(route.get("question") or "")
        item["code"] = str(
            item.get("code")
            or route.get("code")
            or infer_symbol_from_question(question_context)
            or extract_stock_code(question_context)
            or "MARKET"
        ).strip().upper()
        if not isinstance(item.get("cli_args"), list):
            item["cli_args"] = []
        normalized.append(item)
    if not normalized:
        raise HTTPException(
            status_code=500,
            detail=(
                "模型只返回了 Agent 级工具，没有返回可执行 SKILL CLI 脚本。"
                "steps[].script 必须是 modules metadata 中的 .py 脚本。"
            ),
        )
    return normalized


def parse_json_object(text: str) -> dict[str, Any] | None:
    cleaned = text.strip()
    cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned)
    cleaned = re.sub(r"\s*```$", "", cleaned)
    parsed = parse_json_candidate(cleaned)
    if parsed is not None:
        return parsed
    try:
        balanced = extract_balanced_json_object(cleaned)
        if balanced:
            parsed = parse_json_candidate(balanced) or parse_json_candidate(repair_json_escapes(balanced))
            if parsed is not None:
                return parsed
        match = re.search(r"\{.*\}", cleaned, flags=re.S)
        if not match:
            return None
        candidate = match.group(0)
        return parse_json_candidate(candidate) or parse_json_candidate(repair_json_escapes(candidate))
    except Exception:
        return None


def parse_route_json(text: str) -> dict[str, Any] | None:
    parsed_any = parse_json_any(text)
    if isinstance(parsed_any, dict):
        return normalize_route_json_object(parsed_any)
    if isinstance(parsed_any, list):
        steps = [step for step in parsed_any if isinstance(step, dict)]
        if steps:
            return {"steps": steps, "reason": "模型返回了 ReAct 步骤列表。"}
    parsed_object = parse_json_object(text)
    if isinstance(parsed_object, dict):
        return normalize_route_json_object(parsed_object)
    return None


def normalize_route_json_object(route: dict[str, Any]) -> dict[str, Any]:
    normalized = dict(route)
    if not isinstance(normalized.get("steps"), list):
        for key in ("actions", "tool_calls", "tools", "plan"):
            candidate = normalized.get(key)
            if isinstance(candidate, list):
                normalized["steps"] = candidate
                break
    if not isinstance(normalized.get("steps"), list):
        return normalized
    steps: list[dict[str, Any]] = []
    for raw_step in normalized["steps"]:
        if not isinstance(raw_step, dict):
            continue
        step = dict(raw_step)
        script = normalize_script_filename(str(step.get("script") or "").strip())
        if script in AGENT_ONLY_TOOLS:
            continue
        if not script:
            for key in ("tool", "action", "skill"):
                candidate = str(step.get(key) or "").strip()
                if candidate in AGENT_ONLY_TOOLS:
                    step["_agent_tool"] = candidate
                    break
                if candidate.endswith(".py"):
                    script = normalize_script_filename(candidate)
                    break
        if script:
            step["script"] = script
        if not str(step.get("script") or "").strip() and step.get("_agent_tool"):
            continue
        args = step.get("cli_args")
        if not isinstance(args, list):
            for key in ("args", "arguments", "cliArgs"):
                candidate_args = step.get(key)
                if isinstance(candidate_args, list):
                    step["cli_args"] = candidate_args
                    break
        steps.append(step)
    normalized["steps"] = steps
    return normalized


def parse_json_any(text: str) -> Any | None:
    cleaned = strip_json_markdown(text)
    for candidate in json_parse_candidates(cleaned):
        parsed = parse_json_any_candidate(candidate)
        if parsed is not None:
            return parsed
    return None


def strip_json_markdown(text: str) -> str:
    cleaned = str(text or "").strip().lstrip("\ufeff")
    fence = re.match(r"^```(?:json|JSON)?\s*(.*?)\s*```$", cleaned, flags=re.S)
    if fence:
        return fence.group(1).strip()
    return cleaned


def json_parse_candidates(text: str) -> list[str]:
    candidates = [text]
    balanced_object = extract_balanced_json_object(text)
    if balanced_object and balanced_object not in candidates:
        candidates.append(balanced_object)
    balanced_array = extract_balanced_json_array(text)
    if balanced_array and balanced_array not in candidates:
        candidates.append(balanced_array)
    object_match = re.search(r"\{.*\}", text, flags=re.S)
    if object_match and object_match.group(0) not in candidates:
        candidates.append(object_match.group(0))
    array_match = re.search(r"\[.*\]", text, flags=re.S)
    if array_match and array_match.group(0) not in candidates:
        candidates.append(array_match.group(0))
    return candidates


def parse_json_any_candidate(candidate: str) -> Any | None:
    for value in (candidate, repair_json_escapes(candidate), repair_json_trailing_commas(repair_json_escapes(candidate))):
        try:
            return json.loads(value)
        except json.JSONDecodeError:
            try:
                return json.loads(value, strict=False)
            except json.JSONDecodeError:
                continue
    return None


def parse_json_candidate(candidate: str) -> dict[str, Any] | None:
    for value in (candidate, repair_json_escapes(candidate)):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            try:
                parsed = json.loads(value, strict=False)
            except json.JSONDecodeError:
                continue
        if isinstance(parsed, dict):
            return parsed
    return None


def repair_json_escapes(value: str) -> str:
    # Keep valid JSON escapes, but double invalid backslashes so model text like
    # "\username" or a truncated "\u" sequence does not break the full parse.
    repaired = re.sub(r"\\u(?![0-9a-fA-F]{4})", r"\\\\u", value)
    repaired = re.sub(r"\\(?![\"\\/bfnrtu])", r"\\\\", repaired)
    return repaired


def repair_json_trailing_commas(value: str) -> str:
    return re.sub(r",\s*([}\]])", r"\1", value)


def extract_balanced_json_object(text: str) -> str | None:
    start = text.find("{")
    if start < 0:
        return None
    depth = 0
    in_string = False
    escape = False
    for index in range(start, len(text)):
        char = text[index]
        if in_string:
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return text[start : index + 1]
    return None


def extract_balanced_json_array(text: str) -> str | None:
    start = text.find("[")
    if start < 0:
        return None
    depth = 0
    in_string = False
    escape = False
    for index in range(start, len(text)):
        char = text[index]
        if in_string:
            if escape:
                escape = False
            elif char == "\\":
                escape = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
            if depth == 0:
                return text[start : index + 1]
    return None


def extract_stock_code(question: str) -> str | None:
    text = original_question_without_execution_feedback(question)
    option_contract = OCC_OPTION_SYMBOL_RE.search(text)
    if option_contract:
        return option_contract.group(1).upper()
    crypto_pair = CRYPTO_PAIR_RE.search(text)
    if crypto_pair:
        return crypto_pair.group(0).upper()
    quoted = re.search(r"(?:股票代码|合约代码|期权代码|期權代碼|代码|ticker|symbol)[:：\s]*([A-Za-z0-9][A-Za-z0-9.^=\-]{0,23})", text)
    if quoted:
        return quoted.group(1).upper()

    candidates: list[str] = []
    for match in re.finditer(r"(?<![A-Za-z0-9])[A-Z]{1,6}(?:[.-][A-Z]{1,3})?(?![A-Za-z0-9])", text):
        if re.match(r"-\d", text[match.end() :]):
            continue
        candidates.append(match.group(0))
    ignored = {"PE", "PS", "EPS", "ROE", "ROA", "FCF", "CEO", "CFO", "USA", "ETF"}
    for candidate in candidates:
        if candidate not in ignored:
            return candidate
    return None


def normalize_symbol_for_selected(selected: SkillScript, code: str) -> str:
    value = str(code or "").strip().upper()
    if selected.filename == "yahoo_data.py":
        return canonicalize_yahoo_hk_symbol_text(value)
    if selected.key != "kline":
        return value
    symbols = [
        symbol.strip().upper()
        for symbol in re.split(r"[,，;；/、\s]+", value)
        if re.fullmatch(r"[A-Z0-9^][A-Z0-9.^=\-]{0,23}", symbol.strip().upper())
    ]
    if len(symbols) > 1:
        return ",".join(dict.fromkeys(symbols))
    if " " not in value:
        return value
    first_token = re.split(r"\s+", value, maxsplit=1)[0].strip("()")
    if re.fullmatch(r"[A-Z0-9.^=\-]{2,24}", first_token):
        return first_token
    return value


def kline_payload_has_data(payload_path: Path) -> bool:
    try:
        payload = json.loads(payload_path.read_text(encoding="utf-8", errors="ignore"))
    except (OSError, json.JSONDecodeError):
        return False
    rows = payload.get("data")
    if isinstance(rows, list) and bool(rows):
        return True
    per_symbol = payload.get("perSymbol")
    if isinstance(per_symbol, dict):
        return any(isinstance(item, dict) and isinstance(item.get("data"), list) and bool(item.get("data")) for item in per_symbol.values())
    return False


def clean_crypto_name_query(text: str) -> str:
    value = re.sub(r"\s+", " ", str(text or "").strip())
    value = re.sub(
        r"\b(price|chart|charts|analysis|trend|quote|coin|token|crypto)\b",
        "",
        value,
        flags=re.IGNORECASE,
    )
    return re.sub(r"\s+", " ", value).strip(" -_,")


def resolve_crypto_symbol_by_name(*queries: str) -> str | None:
    seen: set[str] = set()
    for raw_query in queries:
        query = clean_crypto_name_query(raw_query)
        if not query:
            continue
        lowered = query.casefold()
        if lowered in seen:
            continue
        seen.add(lowered)
        try:
            response = requests.get(
                "https://api.coingecko.com/api/v3/search",
                params={"query": query},
                timeout=8,
            )
            response.raise_for_status()
            payload = response.json()
        except Exception:
            continue
        coins = payload.get("coins")
        if not isinstance(coins, list):
            continue
        for coin in coins[:8]:
            if not isinstance(coin, dict):
                continue
            symbol = str(coin.get("symbol") or "").strip().upper()
            name = str(coin.get("name") or "").strip()
            if not symbol or not re.fullmatch(r"[A-Z0-9]{2,18}", symbol):
                continue
            if name.casefold() == query.casefold():
                return symbol
        first = next(
            (
                str(coin.get("symbol") or "").strip().upper()
                for coin in coins
                if isinstance(coin, dict) and re.fullmatch(r"[A-Z0-9]{2,18}", str(coin.get("symbol") or "").strip().upper())
            ),
            "",
        )
        if first:
            return first
    return None


def split_route_symbols(value: str) -> list[str]:
    return [
        symbol.strip().upper()
        for symbol in re.split(r"[,，;；/、\s]+", str(value or ""))
        if re.fullmatch(r"[A-Z0-9^][A-Z0-9.^\-]{0,18}", symbol.strip().upper())
    ]


def is_crypto_like_symbol(value: str) -> bool:
    symbol = str(value or "").strip().upper().replace("-", "").replace("/", "")
    if not symbol or "." in str(value or "") or symbol.startswith("^"):
        return False
    return bool(re.fullmatch(r"[A-Z0-9]{2,18}(USDT|USDC|USD|BTC|ETH)", symbol))


def should_retry_kline_as_crypto(code: str, question: str) -> bool:
    symbols = split_route_symbols(code)
    if len(symbols) != 1:
        return False
    symbol = symbols[0] if symbols else str(code or "").strip().upper()
    if not symbol or symbol in GENERIC_ROUTE_CODES:
        return False
    lower = question.lower()
    crypto_terms = ("crypto", "cryptocurrency", "coin", "token", "bitcoin", "btc", "ethereum", "eth", "加密", "数字币", "數字幣", "比特币", "比特幣", "以太坊")
    return is_crypto_like_symbol(symbol) or any(term in lower for term in crypto_terms)


def run_skill_script(
    selected: SkillScript,
    code: str,
    html_path: Path,
    payload_path: Path,
    cli_args: list[Any],
    question: str = "",
    *,
    agent_run: AgentRun | None = None,
    prepared_command: list[str] | None = None,
) -> None:
    script = script_path_for_filename(selected.filename)
    if not script.exists():
        raise HTTPException(status_code=500, detail=f"找不到组件脚本：{script}")

    if selected.filename == NEWS_SEARCH_SCRIPT:
        run_news_search_script(selected, code, script, html_path, payload_path, cli_args, question, agent_run=agent_run, prepared_command=prepared_command)
        return
    if selected.filename == VIDEO_SEARCH_SCRIPT:
        run_video_search_script(selected, code, script, html_path, payload_path, cli_args, question, agent_run=agent_run, prepared_command=prepared_command)
        return
    if selected.filename == EXTERNAL_INFO_SEARCH_SCRIPT:
        run_external_info_search_script(selected, code, script, html_path, payload_path, cli_args, question, agent_run=agent_run, prepared_command=prepared_command)
        return
    if selected.filename == URL_CONTENT_READER_SCRIPT:
        run_url_content_reader_script(selected, code, script, html_path, payload_path, cli_args, question, agent_run=agent_run, prepared_command=prepared_command)
        return

    resolved_code = normalize_symbol_for_selected(selected, code)
    cmd = prepared_command or build_script_command(selected, script, resolved_code, html_path, payload_path, cli_args, question)
    script_cwd = str(script.parent)
    timeout_seconds = script_timeout_seconds(selected)
    result = execute_skill_command(
        agent_run=agent_run,
        tool_name=selected.filename,
        cmd=cmd,
        cwd=script_cwd,
        timeout_seconds=timeout_seconds,
        env=PYTHON_NO_BYTECODE_ENV,
    )
    if result.timed_out:
        write_timed_out_module_result(selected, resolved_code, html_path, payload_path, timeout_seconds)
        return
    if result.returncode != 0 and "unrecognized arguments: --payload-output" in result.stderr:
        cmd = build_script_command(selected, script, resolved_code, html_path, payload_path, cli_args, question, include_payload_output=False)
        result = execute_skill_command(
            agent_run=agent_run,
            tool_name=f"{selected.filename}:retry-no-payload-output",
            cmd=cmd,
            cwd=script_cwd,
            timeout_seconds=timeout_seconds,
            env=PYTHON_NO_BYTECODE_ENV,
        )
        if result.timed_out:
            write_timed_out_module_result(selected, resolved_code, html_path, payload_path, timeout_seconds)
            return
    if result.returncode != 0:
        message = result.stderr.strip() or result.stdout.strip() or "脚本执行失败"
        raise HTTPException(
            status_code=500,
            detail=humanize_script_error(selected, resolved_code, message),
        )
    if selected.filename == "code_interpreter.py":
        validate_code_interpreter_result_context(payload_path, cli_args, question)
    if selected.key == "kline":
        payload_args = adapt_cli_args_for_script(
            selected,
            ensure_kline_period_arg(
                selected,
                remove_cli_option(sanitize_cli_args(cli_args), {"--code", "--symbol"}),
                question,
            ),
            question,
        )
        payload_options = cli_args_to_dict(payload_args)
        if not write_kline_payload_from_rendered_html(resolved_code, html_path, payload_path, payload_options):
            write_kline_payload(resolved_code, payload_path, payload_options)
        if not kline_payload_has_data(payload_path) and should_retry_kline_as_crypto(resolved_code, question):
            alternate_symbol = resolve_crypto_symbol_by_name(code, question)
            if alternate_symbol and alternate_symbol != resolved_code:
                retry_html_path = html_path
                retry_payload_path = payload_path
                retry_cmd = build_script_command(selected, script, alternate_symbol, retry_html_path, retry_payload_path, cli_args, question)
                retry_result = execute_skill_command(
                    agent_run=agent_run,
                    tool_name=f"{selected.filename}:crypto-retry",
                    cmd=retry_cmd,
                    cwd=script_cwd,
                    timeout_seconds=timeout_seconds,
                    env=PYTHON_NO_BYTECODE_ENV,
                )
                if retry_result.returncode == 0:
                    if not write_kline_payload_from_rendered_html(alternate_symbol, html_path, payload_path, payload_options):
                        write_kline_payload(alternate_symbol, payload_path, payload_options)
                    if kline_payload_has_data(payload_path):
                        return
    if selected.key == "trade_flow":
        refresh_trade_flow_title_after_run(script, html_path, payload_path, question)
    if selected.key == "wall_street_consensus":
        refresh_wall_street_consensus_title_after_run(script, html_path, payload_path, question)


def refresh_trade_flow_title_after_run(script: Path, html_path: Path, payload_path: Path, question: str) -> None:
    if not payload_path.exists():
        return
    payload = read_payload(payload_path)
    if not payload or payload.get("type") == "module-timeout":
        return
    lang = html_lang_for_question(question)
    payload["language"] = lang
    title = generate_trade_flow_title(question, payload, lang)
    if title:
        payload["title"] = title
    labels = generate_trade_flow_labels(question, lang)
    if labels:
        payload["i18n"] = labels
    payload_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        command = [sys.executable, str(script), "--input", str(payload_path), "--language", lang, "--output", str(html_path)]
        if labels:
            command.extend(["--labels-json", json.dumps(labels, ensure_ascii=False)])
        subprocess.run(
            command,
            cwd=str(script.parent),
            text=True,
            capture_output=True,
            timeout=30,
            env=PYTHON_NO_BYTECODE_ENV,
        )
    except Exception:
        return


def refresh_wall_street_consensus_title_after_run(script: Path, html_path: Path, payload_path: Path, question: str) -> None:
    if not payload_path.exists():
        return
    payload = read_payload(payload_path)
    if not payload or payload.get("type") == "module-timeout":
        return
    theme = "dark" if explicit_dark_theme_requested(question) else "light"
    lang = html_lang_for_question(question)
    title = generate_wall_street_consensus_title(question, payload) or fallback_wall_street_consensus_title(question, payload)
    if title:
        payload["title"] = title
    payload["language"] = lang
    payload_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        command = [sys.executable, str(script), "--input", str(payload_path), "--language", lang, "--theme", theme, "--output", str(html_path)]
        subprocess.run(
            command,
            cwd=str(script.parent),
            text=True,
            capture_output=True,
            timeout=30,
            env=PYTHON_NO_BYTECODE_ENV,
        )
    except Exception:
        return


def wall_street_consensus_rendered_theme(html_path: Path, payload: dict[str, Any]) -> str:
    for key in ("themeMode", "theme"):
        value = str(payload.get(key) or "").strip().lower()
        if value == "dark":
            return "dark"
    try:
        html_text = html_path.read_text(encoding="utf-8")
    except Exception:
        return "light"
    return "dark" if "theme-dark" in html_text else "light"


def fallback_wall_street_consensus_title(question: str, payload: dict[str, Any]) -> str:
    code = str(payload.get("code") or "").strip().upper()
    summary = payload.get("ratingSummary") if isinstance(payload.get("ratingSummary"), dict) else {}
    target = payload.get("priceTarget") if isinstance(payload.get("priceTarget"), dict) else {}
    upside = payload.get("upside") if isinstance(payload.get("upside"), dict) else {}
    rating = str(summary.get("label") or "--").strip()
    rating_map = {
        "strong buy": {"zh-CN": "强烈买入", "zh-Hant": "強烈買入"},
        "buy": {"zh-CN": "买入", "zh-Hant": "買入"},
        "hold": {"zh-CN": "持有", "zh-Hant": "持有"},
        "sell": {"zh-CN": "卖出", "zh-Hant": "賣出"},
        "strong sell": {"zh-CN": "强烈卖出", "zh-Hant": "強烈賣出"},
    }
    lang = html_lang_for_question(question)
    localized_rating = rating_map.get(rating.lower(), {}).get(lang, rating)
    analysts = int(summary.get("analystCount") or 0)
    average_target = to_float(target.get("average"))
    upside_percent = to_float(upside.get("percent"))
    target_text = f"${average_target:,.2f}" if average_target is not None else "--"
    upside_text = f"{upside_percent:+.2f}%" if upside_percent is not None else "--"
    lower = (question or "").lower()
    wants_target = any(token in lower for token in ("target", "price target", "目标价", "目標價"))
    if "zh-Hant" in lang or any(ch in question for ch in "評級華爾識標價買賣強師"):
        return f"{code} 目標價{target_text}，上行空間{upside_text}" if wants_target else f"{code} 分析師共識：{localized_rating}"
    if re.search(r"[\u4e00-\u9fff]", question or ""):
        return f"{code} 目标价{target_text}，上行空间{upside_text}" if wants_target else f"{code} 分析师共识：{localized_rating}"
    suffix = f" from {analysts} analysts" if analysts else ""
    return f"{code} Target {target_text}, {upside_text} Upside" if wants_target else f"{code} Consensus: {rating}{suffix}"


def generate_wall_street_consensus_title(question: str, payload: dict[str, Any]) -> str:
    api_key = model_api_key()
    if not api_key:
        return ""
    summary = payload.get("ratingSummary") if isinstance(payload.get("ratingSummary"), dict) else {}
    target = payload.get("priceTarget") if isinstance(payload.get("priceTarget"), dict) else {}
    facts = {
        "code": payload.get("code"),
        "rating": summary.get("label"),
        "score": summary.get("score"),
        "analystCount": summary.get("analystCount"),
        "averageTarget": target.get("average"),
        "lowTarget": target.get("low"),
        "highTarget": target.get("high"),
        "lastPrice": payload.get("lastPrice"),
        "upsidePercent": (payload.get("upside") or {}).get("percent") if isinstance(payload.get("upside"), dict) else None,
        "industryRank": payload.get("industryRank"),
    }
    prompt = (
        "基于用户问句和华尔街分析师共识数据，生成一个短标题。\n"
        f"目标语言代码：{html_lang_for_question(question)}。\n"
        "要求：使用用户问句对应语言；如果是 zh-Hant 必须用繁体；如果是 zh-CN 必须用简体；"
        "不要输出 Wall Street Consensus、华尔街共识 这类组件名或泛标题；"
        "标题要结合真实数据，优先体现用户关注点，例如评级、目标价、上行/下行空间、分析师数量或行业排名；"
        "最多 20 个中文字符或 9 个英文词；只输出标题。\n\n"
        f"用户问句：{question}\n"
        f"数据：{json.dumps(facts, ensure_ascii=False)}"
    )
    try:
        completion = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL, timeout=15, max_retries=0).chat.completions.create(
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
            max_tokens=80,
        )
        title = completion_text(completion, "资金流标题生成").strip()
    except Exception:
        return ""
    title = re.sub(r"[\n\r\t\"'`]+", "", title).strip(" ：:，,.。")
    generic = {"wall street consensus", "华尔街共识", "華爾街共識", "分析师共识", "分析師共識"}
    if not title or title.lower() in generic:
        return ""
    return title[:56]


def generate_trade_flow_title(question: str, payload: dict[str, Any], lang: str | None = None) -> str:
    api_key = model_api_key()
    if not api_key:
        return ""
    code = str(payload.get("code") or "").strip().upper()
    facts = {
        "code": code,
        "currency": payload.get("currency"),
        "totalInflow": payload.get("totalInflowLabel") or payload.get("totalInflow"),
        "totalOutflow": payload.get("totalOutflowLabel") or payload.get("totalOutflow"),
        "netFlow": payload.get("netFlowLabel") or payload.get("netFlow"),
        "distribution": [
            {
                "name": item.get("name"),
                "inflow": item.get("inflowLabel") or item.get("inflow"),
                "outflow": item.get("outflowLabel") or item.get("outflow"),
                "net": item.get("netLabel") or item.get("net"),
            }
            for item in (payload.get("distribution") or [])[:5]
            if isinstance(item, dict)
        ],
    }
    prompt = (
        "基于用户问句和资金流数据，生成一个短而有洞察的图表标题。\n"
        f"目标语言代码：{lang or html_lang_for_question(question)}。\n"
        "要求：使用目标语言和书写系统；如果目标语言是 zh-Hant，所有中文必须使用繁体；如果目标语言是 zh-CN，所有中文必须使用简体；"
        "不要使用 Trade Flow Insight、订单流图、资金流图 这类组件名或泛标题；"
        "突出净流入/净流出、买卖力量、主导资金或用户关心的标的；最多 18 个中文字符或 8 个英文词；只输出标题。\n\n"
        f"用户问句：{question}\n"
        f"资金流数据：{json.dumps(facts, ensure_ascii=False)}"
    )
    try:
        completion = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL, timeout=15, max_retries=0).chat.completions.create(
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.2,
            max_tokens=60,
        )
        title = completion_text(completion, "交易流标题生成").strip()
    except Exception:
        return ""
    title = re.sub(r"[\n\r\t\"'`]+", "", title).strip(" ：:，,.。")
    generic = {"trade flow insight", "订单流图", "资金流图", "资金流分析", "订单流分析"}
    if not title or title.lower() in generic:
        return ""
    return title[:40]


def generate_trade_flow_labels(question: str, lang: str) -> dict[str, str]:
    api_key = model_api_key()
    if not api_key:
        return {}
    keys = [
        "componentName",
        "orderFlowDistribution",
        "orderFlowTracker",
        "currency",
        "inflow",
        "outflow",
        "netFlow",
        "netInflow",
        "netOutflow",
        "stockPrice",
        "extraLarge",
        "large",
        "medium",
        "small",
        "overall",
        "noTrackerData",
        "donutAria",
        "timeRangeStart",
        "timeRangeEnd",
    ]
    prompt = (
        "Generate UI labels for a stock order-flow/trade-flow chart component.\n"
        "Return strict JSON only. The JSON object must contain exactly these keys:\n"
        f"{json.dumps(keys, ensure_ascii=False)}\n\n"
        f"Target language code: {lang}\n"
        f"User question: {question}\n\n"
        "Requirements:\n"
        "- Use the target language and writing system inferred from the language code.\n"
        "- For zh-Hant, every Chinese character must be Traditional Chinese.\n"
        "- For zh-CN, every Chinese character must be Simplified Chinese.\n"
        "- Keep labels concise enough for chart UI tabs, legends, and section titles.\n"
        "- Do not include explanations, Markdown, or extra keys."
    )
    try:
        completion = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL, timeout=12, max_retries=0).chat.completions.create(
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.1,
            max_tokens=500,
        )
        content = completion_text(completion, "交易流标签生成").strip()
        content = re.sub(r"^```(?:json)?\s*|\s*```$", "", content, flags=re.I | re.S).strip()
        parsed = json.loads(content)
    except Exception as exc:  # noqa: BLE001
        print(f"Trade flow label generation fallback: {exc}", file=sys.stderr)
        return {}
    if not isinstance(parsed, dict):
        return {}
    result = {key: str(parsed.get(key) or "").strip() for key in keys}
    return {key: value for key, value in result.items() if value}


def script_timeout_seconds(selected: SkillScript) -> int:
    if selected.filename == "kline.py":
        return int(os.getenv("ANALYSIS_PLANNER_KLINE_TIMEOUT_SECONDS", "180"))
    if selected.filename == "computer_use.py":
        return int(os.getenv("ANALYSIS_PLANNER_COMPUTER_USE_TIMEOUT_SECONDS", "360"))
    return int(os.getenv("ANALYSIS_PLANNER_TOOL_TIMEOUT_SECONDS", "90"))


def write_timed_out_module_result(
    selected: SkillScript,
    code: str,
    html_path: Path,
    payload_path: Path,
    timeout_seconds: int,
) -> None:
    payload = {
        "type": "module-timeout",
        "script": selected.filename,
        "label": selected.label,
        "code": code,
        "ok": False,
        "error": "timeout",
        "summary": f"{selected.label} 执行超过 {timeout_seconds} 秒，已跳过该模块。",
    }
    payload_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    document = f"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(selected.label)} Timeout</title>
<style>
html,body{{margin:0;background:#fff;color:#1f2937;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}}
.timeout-card{{padding:24px;border:1px solid #fee2e2;background:#fff7f7;border-radius:12px;color:#991b1b;font-size:14px;line-height:1.6}}
.timeout-card strong{{display:block;margin-bottom:6px;color:#7f1d1d;font-size:16px}}
</style>
</head>
<body>
<main class="timeout-card">
  <strong>{html.escape(selected.label)} 超时</strong>
  <div>{html.escape(payload["summary"])}</div>
</main>
<script>
function sendHeight(){{
  try {{ parent.postMessage({{type:'analysis-planner-chart-height', height:Math.ceil(document.body.scrollHeight || 120)}}, '*'); }} catch (e) {{}}
}}
window.addEventListener('load', sendHeight); setTimeout(sendHeight, 80);
</script>
</body>
</html>"""
    html_path.write_text(document, encoding="utf-8")


def validate_code_interpreter_result_context(
    payload_path: Path,
    cli_args: list[Any],
    fallback_question: str,
) -> None:
    """Reject a transform result that does not belong to the current tool call."""
    payload = read_payload(payload_path)
    actual_question = str(payload.get("question") or "").strip()
    args = [str(value) for value in cli_args]
    expected_question = (
        cli_option_value(args, "--question")
        or cli_option_value(args, "--instruction")
        or fallback_question
    ).strip()

    normalize = lambda value: re.sub(r"\s+", " ", str(value or "")).strip()
    if not actual_question or normalize(actual_question) != normalize(expected_question):
        raise HTTPException(
            status_code=500,
            detail="数据整理结果与当前问题不一致，已阻止复用其他问题的历史结果。",
        )


def humanize_script_error(selected: SkillScript, code: str, raw_message: str) -> str:
    message = (raw_message or "").strip()
    lowered = message.lower()
    code_upper = (code or "").upper()

    if "returned no payout ratio data" in lowered:
        return (
            f"{code_upper} 当前没有可用的 payout ratio 数据。"
            "这通常是因为该标的没有常规现金分红，或者数据源暂未提供可计算的派息率历史。"
        )
    if "returned no dividend yield data" in lowered:
        return (
            f"{code_upper} 当前没有可用的 dividend yield 数据。"
            "这通常是因为该标的没有常规现金分红，或者数据源暂未提供对应股息收益率历史。"
        )
    if "returned no data" in lowered:
        return f"{selected.label} 暂时没有取到 {code_upper} 的可用数据。"
    if "traceback (most recent call last):" in lowered:
        lines = [line.strip() for line in message.splitlines() if line.strip()]
        for line in reversed(lines):
            if any(line.startswith(prefix) for prefix in ("RuntimeError:", "ValueError:", "TypeError:", "SystemExit:", "Exception:", "HTTPException:")):
                return line
        return f"{selected.label} 执行失败，请稍后重试。"
    return message[-600:]


def build_script_command(
    selected: SkillScript,
    script: Path,
    code: str,
    html_path: Path,
    payload_path: Path,
    cli_args: list[Any],
    question: str = "",
    include_payload_output: bool = True,
) -> list[str]:
    clean_args = sanitize_cli_args(cli_args)
    clean_args = remove_cli_option(clean_args, {"--code", "--symbol"})
    if selected.key == "code_interpreter":
        clean_args = remove_cli_option(clean_args, {"--style-json"})
    clean_args = ensure_kline_period_arg(selected, clean_args, question)
    clean_args = ensure_kline_minimum_limit_arg(selected, clean_args)
    clean_args = adapt_cli_args_for_script(selected, clean_args, question)
    if selected.key == "code_interpreter" and question and not has_cli_option(clean_args, "--question") and not has_cli_option(clean_args, "--instruction"):
        clean_args.extend(["--question", question])
    if selected.key == "kline":
        clean_args = add_language_arg_if_supported(selected, clean_args, kline_script_language(question))
    if selected.key == "trade_flow" and not any(arg == "--language" or arg.startswith("--language=") for arg in clean_args):
        trade_flow_lang = html_lang_for_question(question)
        clean_args.extend(["--language", trade_flow_lang])
        if not has_cli_option(clean_args, "--labels-json"):
            labels = generate_trade_flow_labels(question, trade_flow_lang)
            if labels:
                clean_args.extend(["--labels-json", json.dumps(labels, ensure_ascii=False)])
    if selected.filename in {"key_stats.py", "volume_profile.py"}:
        clean_args = add_language_arg_if_supported(selected, clean_args, html_lang_for_question(question))
    if script_tool_category(selected.filename) == "chart_recall":
        clean_args = add_language_arg_if_supported(selected, clean_args, html_lang_for_question(question))
    if selected.key == "wall_street_consensus" and question and not has_cli_option(clean_args, "--question"):
        clean_args.extend(["--question", question])
    if selected.filename in {
        "income_statement.py",
        "balance_sheet.py",
        "revenue_expenses.py",
        "cash_flow.py",
        "key_financial_indicators.py",
        "revenue_sources.py",
        "revenue_geography.py",
        "revenue_estimate.py",
        "eps_estimate.py",
    }:
        clean_args = add_language_arg_if_supported(selected, clean_args, html_lang_for_question(question))
    if question.strip() and script_path_for_filename(selected.filename).parent.name == "scripts" and script_path_for_filename(selected.filename).parent.parent.name == "business-chart-recall":
        clean_args = add_language_arg_if_supported(selected, clean_args, kline_script_language(question) if selected.key == "kline" else html_lang_for_question(question), force=True)
    if selected.filename == "trading_view_chart.py":
        clean_args = add_language_arg_if_supported(selected, clean_args, html_lang_for_question(question))
    clean_args = normalize_generic_chart_payload_args(selected, clean_args, question)
    cmd = [sys.executable, str(script), *clean_args]
    if selected.filename == "trading_view_chart.py":
        widget = cli_option_value(clean_args, "--widget") or "advanced-chart"
        if code and widget in {"advanced-chart", "symbol-overview", "mini-chart", "single-ticker", "tickers", "ticker-tape", "symbol-info", "technical-analysis", "fundamental-data", "company-profile"}:
            cmd.extend(["--symbol", code])
    elif selected.key == "kline":
        cmd.extend(["--symbol", code])
    elif selected.filename not in GENERIC_CHART_PAYLOAD_SCRIPTS:
        cmd.extend(["--code", code])
    if "--output" not in clean_args and "-o" not in clean_args:
        cmd.extend(["--output", str(html_path)])
    if include_payload_output and selected.key != "kline":
        cmd.extend(["--payload-output", str(payload_path)])
    return cmd


def skill_shell_command_for_display(
    selected: SkillScript,
    code: str,
    html_path: Path,
    payload_path: Path,
    cli_args: list[Any],
    question: str = "",
) -> list[str]:
    """Return the shell command that the runtime is about to execute."""
    try:
        script = script_path_for_filename(selected.filename)
        if selected.filename == NEWS_SEARCH_SCRIPT:
            args = build_news_search_args(code, cli_args, question)
            cmd = [sys.executable, str(script), *args, "--format", "json", "--output", str(payload_path)]
        elif selected.filename == VIDEO_SEARCH_SCRIPT:
            args = build_video_search_args(code, cli_args, question)
            cmd = [sys.executable, str(script), *args, "--format", "json", "--output", str(payload_path)]
        elif selected.filename == EXTERNAL_INFO_SEARCH_SCRIPT:
            args = build_external_info_search_args(cli_args, question)
            cmd = [
                sys.executable,
                str(script),
                *args,
                "--format",
                "json",
                "--output",
                str(payload_path),
                "--payload-output",
                str(payload_path),
            ]
        elif selected.filename == URL_CONTENT_READER_SCRIPT:
            args = build_url_content_reader_args(cli_args, question)
            cmd = [sys.executable, str(script), *args, "--output", str(html_path), "--payload-output", str(payload_path)]
        else:
            resolved_code = normalize_symbol_for_selected(selected, code)
            cmd = build_script_command(selected, script, resolved_code, html_path, payload_path, cli_args, question)
        return [str(item) for item in cmd]
    except Exception:
        return []


