def normalize_label_key(value: Any) -> str:
    text = str(value or "").strip().lower()
    compact = re.sub(r"[^a-z0-9_]+", "", text.replace(" ", "_").replace("-", "_"))
    return compact


def generic_display_label(field: Any, lang: str, model_labels: dict[str, str] | None = None) -> str:
    raw = str(field or "").strip()
    model_value = (model_labels or {}).get(normalize_label_key(raw))
    if model_value:
        return model_value
    labels = GENERIC_FIELD_LABELS.get(normalize_label_key(raw)) or GENERIC_FIELD_LABELS.get(raw.lower())
    if labels:
        return labels.get(lang) or labels.get("en") or raw
    if lang == "zh-Hant":
        return to_traditional_chinese(raw)
    if lang == "zh-CN":
        return raw
    return raw.replace("_", " ").strip().title() or raw


def chart_label_needs_localization(label: Any, field: Any, lang: str) -> bool:
    label_text = str(label or "").strip()
    if not label_text:
        return True
    field_text = str(field or "").strip()
    if label_text == field_text or normalize_label_key(label_text) == normalize_label_key(field_text):
        return True
    labels = GENERIC_FIELD_LABELS.get(normalize_label_key(field_text)) or GENERIC_FIELD_LABELS.get(field_text.lower())
    if not labels:
        return False
    target = labels.get(lang) or labels.get("en") or ""
    return bool(target and label_text in set(labels.values()) and label_text != target)


def chart_label_field_candidates(payload: Any, limit: int = 36) -> list[dict[str, Any]]:
    candidates: dict[str, dict[str, Any]] = {}

    def add(field: Any, label: Any = "", sample: Any = None) -> None:
        field_text = str(field or "").strip()
        if not field_text or len(candidates) >= limit:
            return
        key = normalize_label_key(field_text)
        if not key:
            return
        item = candidates.setdefault(key, {"field": field_text})
        label_text = str(label or "").strip()
        if label_text:
            item["label"] = label_text
        if sample not in (None, "") and "sample" not in item:
            item["sample"] = sample

    def walk(value: Any) -> None:
        if len(candidates) >= limit:
            return
        if isinstance(value, dict):
            field = value.get("field") or value.get("key")
            if field:
                add(field, value.get("label") or value.get("name"))
            data = value.get("data") or value.get("rows")
            if isinstance(data, list):
                for row in data[:3]:
                    if isinstance(row, dict):
                        for key, sample in list(row.items())[:20]:
                            if isinstance(sample, (int, float)) and not isinstance(sample, bool):
                                add(key, "", sample)
            for key in ("series", "columnSeries", "lineSeries", "items", "nodes", "links"):
                items = value.get(key)
                if isinstance(items, list):
                    for item in items[:limit]:
                        if isinstance(item, dict):
                            add(item.get("field") or item.get("key") or item.get("id") or item.get("name") or item.get("label"), item.get("label") or item.get("name"))
                            walk(item)
            for key in ("component", "props", "root", "chartPayload"):
                if isinstance(value.get(key), dict):
                    walk(value[key])
        elif isinstance(value, list):
            for item in value[:6]:
                walk(item)

    walk(payload)
    return list(candidates.values())[:limit]


def ark_chart_display_labels(question: str, payload: Any, lang: str) -> dict[str, str]:
    fields = chart_label_field_candidates(payload)
    if not fields:
        return {}
    api_key = model_api_key()
    if not api_key:
        return {}
    prompt = (
        "你是图表字段显示名生成器。请根据用户问题、目标语言和字段语义，为每个字段生成简洁、专业、适合图表 legend/tooltip/axis 的展示名称。\n"
        "要求：只返回 JSON；key 必须使用输入 field 原文；value 是目标语言展示名。不要翻译 data key 本身。"
        "保留股票代码和通用金融缩写，如 EPS、EBIT、EBITDA、TTM、GDP、CPI。"
        "若字段是单位化或比率，请在展示名中自然体现单位或百分比语义，但不要编造数据不存在的单位。\n\n"
        f"目标语言代码：{lang}\n"
        f"用户问题：{question}\n"
        f"字段：{json.dumps(fields, ensure_ascii=False)}"
    )
    try:
        completion = create_chat_completion(
            OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL, timeout=12, max_retries=0),
            json_object=True,
            model=VOLCANO_INTERPRET_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
            max_tokens=700,
        )
    except Exception:
        return {}
    parsed = parse_json_object(completion_text(completion, "图表字段标签生成")) or {}
    output: dict[str, str] = {}
    for item in fields:
        field = str(item.get("field") or "").strip()
        value = str(parsed.get(field) or parsed.get(normalize_label_key(field)) or "").strip()
        if value:
            output[normalize_label_key(field)] = plain_text_excerpt(value, 40)
    return output


def localize_chart_series_labels(payload: Any, lang: str, model_labels: dict[str, str] | None = None) -> Any:
    if isinstance(payload, list):
        for item in payload:
            localize_chart_series_labels(item, lang, model_labels)
        return payload
    if not isinstance(payload, dict):
        return payload
    for key in ("series", "columnSeries", "lineSeries", "items", "nodes", "links"):
        values = payload.get(key)
        if isinstance(values, list):
            for item in values:
                if not isinstance(item, dict):
                    continue
                field = item.get("field") or item.get("key") or item.get("id") or item.get("name") or item.get("label")
                if chart_label_needs_localization(item.get("label") or item.get("name"), field, lang):
                    localized = generic_display_label(field, lang, model_labels)
                    if "label" in item or key in {"series", "columnSeries", "lineSeries"}:
                        item["label"] = localized
                    elif "name" in item:
                        item["name"] = localized
                localize_chart_series_labels(item, lang, model_labels)
    for key in ("component", "props", "root", "chartPayload"):
        if isinstance(payload.get(key), dict):
            localize_chart_series_labels(payload[key], lang, model_labels)
    return payload


def normalize_generic_chart_payload_args(selected: SkillScript, args: list[str], question: str = "") -> list[str]:
    if selected.filename not in GENERIC_CHART_PAYLOAD_SCRIPTS:
        return args
    lang = html_lang_for_question(question) if question else "en"
    normalized = list(args)
    index = 0
    while index < len(normalized):
        value = normalized[index]
        if value == "--data-json" and index + 1 < len(normalized):
            normalized[index + 1] = ensure_json_object_text(normalized[index + 1], selected.filename, lang, question)
            index += 2
            continue
        if value.startswith("--data-json="):
            raw = value.split("=", 1)[1]
            normalized[index] = f"--data-json={ensure_json_object_text(raw, selected.filename, lang, question)}"
        index += 1
    return normalized


def ensure_json_object_text(raw: str, filename: str, lang: str = "en", question: str = "") -> str:
    text = str(raw or "").strip()
    if not text:
        if filename == "bar_line.py":
            raise HTTPException(status_code=500, detail="bar_line.py 缺少可视化数据，未生成兜底图。")
        return "{}"
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError:
        if filename == "bar_line.py":
            raise HTTPException(status_code=500, detail="bar_line.py 输入不是有效 JSON，未生成兜底图。")
        parsed = {"text": text}
    model_labels = ark_chart_display_labels(question, parsed, lang) if question else {}
    if filename == "bar_line.py":
        return json.dumps(ensure_bar_line_payload_object(parsed, lang, model_labels), ensure_ascii=False, separators=(",", ":"))
    if isinstance(parsed, dict):
        localize_chart_series_labels(parsed, lang, model_labels)
        return json.dumps(parsed, ensure_ascii=False, separators=(",", ":"))
    title = filename.rsplit(".", 1)[0].replace("_", " ").title()
    if isinstance(parsed, list):
        payload = {"title": title, "data": parsed}
        localize_chart_series_labels(payload, lang, model_labels)
        return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    return json.dumps({"title": title, "value": parsed}, ensure_ascii=False, separators=(",", ":"))


def ensure_bar_line_payload_object(value: Any, lang: str = "en", model_labels: dict[str, str] | None = None) -> dict[str, Any]:
    if isinstance(value, dict) and (
        value.get("type") in {"bar-line", "column-line"}
        or value.get("chartType") in {"bar-line", "column-line"}
        or isinstance(value.get("component"), dict)
        or (isinstance(value.get("root"), dict) and isinstance(value.get("root", {}).get("component"), dict))
    ):
        localize_chart_series_labels(value, lang, model_labels)
        return value
    if isinstance(value, dict):
        data = value.get("data")
        if not isinstance(data, list):
            props = value.get("props")
            if isinstance(props, dict) and isinstance(props.get("data"), list):
                data = props["data"]
        title = str(value.get("title") or value.get("name") or "")
    elif isinstance(value, list):
        data = value
        title = ""
    else:
        raise HTTPException(status_code=500, detail="bar_line.py 输入无法转换为有效柱折图数据，未生成兜底图。")
    if not isinstance(data, list) or not data:
        raise HTTPException(status_code=500, detail="bar_line.py 没有可绘制数据，未生成兜底图。")
    if not any(isinstance(row, dict) and row for row in data):
        raise HTTPException(status_code=500, detail="bar_line.py 数据行无效，未生成兜底图。")
    series_spec = value.get("series") if isinstance(value, dict) and isinstance(value.get("series"), list) else []
    pivoted = pivot_long_bar_line_data(data, value if isinstance(value, dict) else {}, series_spec)
    if pivoted:
        data = pivoted["data"]
        x_field = pivoted["xField"]
        column_fields = pivoted["columnFields"]
        line_fields = pivoted["lineFields"]
    else:
        x_field, numeric_fields = infer_bar_line_fields(data)
        typed_columns, typed_lines = typed_bar_line_fields(series_spec, numeric_fields)
        if len(numeric_fields) < 2 and not (typed_columns and typed_lines):
            column_fields = typed_columns or numeric_fields[:1]
            line_fields = typed_lines or numeric_fields[:1]
        else:
            column_fields = typed_columns or numeric_fields[:-1] or numeric_fields[:1]
            line_fields = typed_lines or numeric_fields[-1:]
    if not column_fields or not line_fields:
        raise HTTPException(status_code=500, detail="bar_line.py 无法识别柱系列和折线系列，未生成兜底图。")
    if is_placeholder_bar_line_payload_shape(data, x_field, column_fields, line_fields, title):
        raise HTTPException(status_code=500, detail="bar_line.py 识别到占位数据，未生成兜底图。")
    return {
        "type": "bar-line",
        "title": title,
        "props": {
            "xField": x_field,
            "columnSeries": [
                {"field": field, "label": generic_display_label(field, lang, model_labels), "color": color}
                for field, color in zip(column_fields, ("#4387f5", "#4bc3d5", "#8b5cf6", "#10b981"))
            ],
            "lineSeries": [
                {"field": field, "label": generic_display_label(field, lang, model_labels), "color": color}
                for field, color in zip(line_fields, ("#f9730c", "#ef4444", "#14b8a6"))
            ],
            "data": data,
        },
    }


def is_placeholder_bar_line_payload_shape(
    data: list[Any],
    x_field: str,
    column_fields: list[str],
    line_fields: list[str],
    title: str = "",
) -> bool:
    title_text = str(title or "").strip().lower()
    field_set = {str(field) for field in [x_field, *column_fields, *line_fields]}
    if title_text in {"bar line chart", "bar-line chart", "柱折图"} and field_set <= {"label", "value", "bar", "line", "index"}:
        return True
    if len(data) == 1 and field_set <= {"label", "value", "bar", "line", "index"}:
        row = data[0]
        if isinstance(row, dict):
            label = str(row.get("label") or row.get("index") or "").strip().lower()
            numeric_values = [value for key, value in row.items() if key != x_field and isinstance(value, (int, float))]
            return label in {"value", "1", ""} or len(numeric_values) <= 1
    return False


def typed_bar_line_fields(series_spec: list[Any], numeric_fields: list[str]) -> tuple[list[str], list[str]]:
    numeric_set = {str(field) for field in numeric_fields}
    columns: list[str] = []
    lines: list[str] = []
    for item in series_spec:
        if not isinstance(item, dict):
            continue
        field = str(item.get("field") or "").strip()
        if not field or field not in numeric_set:
            continue
        series_type = str(item.get("type") or "").lower()
        axis = str(item.get("axis") or "").lower()
        if series_type in {"bar", "column"} or axis == "right":
            columns.append(field)
        elif series_type == "line" or axis == "left":
            lines.append(field)
    return columns, lines


def pivot_long_bar_line_data(data: list[Any], payload: dict[str, Any], series_spec: list[Any]) -> dict[str, Any] | None:
    rows = [row for row in data if isinstance(row, dict)]
    if not rows:
        return None
    first = rows[0]
    x_field = str(payload.get("xField") or "").strip()
    if not x_field or x_field not in first:
        x_field = next((field for field in ("year", "年份", "date", "日期", "period", "name", "label") if field in first), "")
    series_field = str(payload.get("seriesField") or payload.get("groupField") or "").strip()
    if not series_field or series_field not in first:
        series_field = next((field for field in ("series", "系列", "category", "指标", "metric", "name") if field in first and field != x_field), "")
    value_field = str(payload.get("valueField") or payload.get("yField") or "").strip()
    if not value_field or value_field not in first:
        value_field = next((field for field in ("value", "数值", "值", "amount", "y") if isinstance(first.get(field), (int, float))), "")
    if not x_field or not series_field or not value_field:
        return None
    output_by_x: dict[str, dict[str, Any]] = {}
    ordered_series: list[str] = []
    for row in rows:
        x_value = row.get(x_field)
        series_name = str(row.get(series_field) or "").strip()
        value = row.get(value_field)
        if series_name == "" or not isinstance(value, (int, float)):
            continue
        key = str(x_value)
        output_by_x.setdefault(key, {x_field: x_value})[series_name] = value
        if series_name not in ordered_series:
            ordered_series.append(series_name)
    if not output_by_x or not ordered_series:
        return None
    typed = {str(item.get("field") or item.get("label") or ""): str(item.get("type") or "").lower() for item in series_spec if isinstance(item, dict)}
    column_fields = [field for field in ordered_series if typed.get(field) in {"bar", "column"}]
    line_fields = [field for field in ordered_series if typed.get(field) == "line"]
    if not column_fields and not line_fields:
        column_fields = [field for field in ordered_series if re.search(r"年均|平均|avg|average|mean", field, re.I)]
        line_fields = [field for field in ordered_series if field not in column_fields]
    if not column_fields:
        column_fields = ordered_series[:1]
    if not line_fields:
        line_fields = [field for field in ordered_series if field not in column_fields] or ordered_series[-1:]
    return {
        "xField": x_field,
        "data": list(output_by_x.values()),
        "columnFields": column_fields,
        "lineFields": line_fields,
    }


def infer_bar_line_fields(data: list[Any]) -> tuple[str, list[str]]:
    first = next((item for item in data if isinstance(item, dict)), {})
    if not isinstance(first, dict):
        return "label", ["bar", "line"]
    preferred_x = ("period", "date", "year", "quarter", "month", "label", "name", "x")
    x_field = next((field for field in preferred_x if field in first), "")
    if not x_field:
        x_field = next((key for key, item in first.items() if not isinstance(item, (int, float))), "label")
    numeric_fields = [
        key
        for key, item in first.items()
        if key != x_field and isinstance(item, (int, float))
    ]
    if not numeric_fields:
        numeric_fields = [key for key in ("bar", "line") if key in first]
    return str(x_field), [str(field) for field in numeric_fields]


