def video_relevance_terms(question: str, code: str) -> list[str]:
    text = str(question or "")
    lower = text.lower()
    symbols = [
        symbol.strip().upper()
        for symbol in [code, infer_symbol_from_question(question), extract_stock_code(question), *infer_symbols_from_question(question)]
        if str(symbol or "").strip().upper() not in {"", "MARKET", "ALL", "GENERAL", "NEWS"}
    ]
    terms: list[str] = []
    for symbol in symbols:
        terms.append(symbol)
        if "." in symbol:
            terms.append(symbol.split(".", 1)[0])
        if "-" in symbol:
            terms.append(symbol.split("-", 1)[0])
    alias_groups = (
        ({"BABA", "9988.HK", "9988"}, ["BABA", "Alibaba", "阿里巴巴", "阿里"]),
        ({"TCEHY", "0700.HK", "0700"}, ["TCEHY", "Tencent", "腾讯", "騰訊", "腾讯控股", "騰訊控股"]),
        ({"NVDA"}, ["NVDA", "Nvidia", "英伟达", "英偉達"]),
        ({"AAPL"}, ["AAPL", "Apple", "苹果", "蘋果"]),
        ({"MSFT"}, ["MSFT", "Microsoft", "微软", "微軟"]),
        ({"GOOGL", "GOOG"}, ["GOOGL", "GOOG", "Google", "Alphabet", "谷歌"]),
        ({"AMZN"}, ["AMZN", "Amazon", "亚马逊", "亞馬遜"]),
        ({"TSLA"}, ["TSLA", "Tesla", "特斯拉"]),
        ({"META"}, ["META", "Facebook"]),
        ({"AVGO"}, ["AVGO", "Broadcom", "博通"]),
    )
    symbol_set = set(symbols)
    for aliases, names in alias_groups:
        if symbol_set & aliases or any(name.lower() in lower or name in text for name in names):
            terms.extend(names)
    for ticker in re.findall(r"\b[A-Z]{1,6}(?:[.-][A-Z]{1,4})?\b", text):
        if ticker not in {"AI", "IPO", "ETF", "GDP", "CPI", "USD", "US"}:
            terms.append(ticker)
    deduped: list[str] = []
    for term in terms:
        clean = str(term or "").strip()
        if clean and clean.lower() not in {item.lower() for item in deduped}:
            deduped.append(clean)
    return deduped


def video_article_matches_terms(article: dict[str, Any], terms: list[str]) -> bool:
    haystack = " ".join(
        str(article.get(key) or "")
        for key in (
            "title",
            "summary",
            "description",
            "content_text",
            "url",
            "source",
            "matched_topics",
            "semantic_terms",
        )
    ).lower()
    return any(term.lower() in haystack for term in terms)


def filter_video_search_payload_for_question(payload: dict[str, Any], question: str, code: str) -> dict[str, Any]:
    if not isinstance(payload, dict) or payload.get("type") != "ainvest-video-search":
        return payload
    terms = video_relevance_terms(question, code)
    if not terms:
        return payload
    articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
    filtered = [item for item in articles if isinstance(item, dict) and video_article_matches_terms(item, terms)]
    updated = dict(payload)
    updated["articles"] = filtered
    updated["article_count"] = len(filtered)
    updated["relevance_filter"] = {
        "terms": terms,
        "before": len(articles),
        "after": len(filtered),
        "reason": "Video cards must mention the requested ticker/company/topic before rendering.",
    }
    if not filtered:
        updated["answer"] = ""
        updated["error"] = "No directly relevant AInvest video cards matched the requested ticker/company."
    return updated


def is_low_quality_news_payload(payload: dict[str, Any], question: str) -> bool:
    if not is_explicit_external_news_query(question):
        return False
    articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
    if not articles:
        return True
    generic_title_terms = (
        "股价",
        "股價",
        "股票股价",
        "报价",
        "報價",
        "行情",
        "图表",
        "圖表",
        "财报_数据报告",
        "最新股票消息和頭條新聞",
        "latest stock news and headlines",
    )
    bad_summary_terms = ("_waf_", "captcha", "access denied", "forbidden")
    useful = 0
    for item in articles:
        if not isinstance(item, dict):
            continue
        title = str(item.get("title") or "").strip().lower()
        summary = str(item.get("summary") or item.get("content_text") or "").strip().lower()
        if not title:
            continue
        if any(term.lower() in title for term in generic_title_terms):
            continue
        if any(term in summary for term in bad_summary_terms):
            continue
        useful += 1
    return useful == 0


