def localize_chart_label(label: str, lang: str) -> str:
    value = (label or "").strip()
    if not value:
        return value
    for sources, targets in CHART_LOCALIZATION_ENTRIES:
        if value in sources:
            return targets.get(lang) or targets.get("en") or value
    return to_traditional_chinese(value) if lang == "zh-Hant" else value


