def to_traditional_chinese(text: str) -> str:
    if not text:
        return text
    converted = text
    for source, target in sorted(ZH_HANT_PHRASES, key=lambda item: len(item[0]), reverse=True):
        converted = converted.replace(source, target)
    return converted.translate(ZH_HANT_CHARS)


def sanitize_cli_args(cli_args: list[Any]) -> list[str]:
    clean: list[str] = []
    blocked = {"--output", "-o", "--payload-output"}
    skip_next = False
    allow_path_value = False
    for item in cli_args:
        if skip_next:
            skip_next = False
            continue
        value = str(item)
        if value in blocked:
            skip_next = True
            continue
        if "\x00" in value:
            continue
        if value.startswith("/") and not allow_path_value:
            continue
        clean.append(value)
        allow_path_value = value == "--payload"
        if value != "--payload" and not value.startswith("-"):
            allow_path_value = False
    return clean


def remove_cli_option(args: list[str], options: set[str]) -> list[str]:
    clean: list[str] = []
    skip_next = False
    for index, value in enumerate(args):
        if skip_next:
            skip_next = False
            continue
        if value in options:
            if index + 1 < len(args) and not args[index + 1].startswith("-"):
                skip_next = True
            continue
        if any(value.startswith(f"{option}=") for option in options):
            continue
        clean.append(value)
    return clean


def cli_args_to_dict(cli_args: list[Any]) -> dict[str, Any]:
    clean = sanitize_cli_args(cli_args)
    result: dict[str, Any] = {}
    index = 0
    while index < len(clean):
        key = clean[index]
        if key.startswith("--"):
            normalized = key[2:].replace("-", "_")
            if index + 1 < len(clean) and not clean[index + 1].startswith("--"):
                result[normalized] = clean[index + 1]
                index += 2
                continue
            result[normalized] = True
        index += 1
    return result


def inline_json_assignment(document: str, variable_name: str) -> Any:
    marker = f"const {variable_name} ="
    start = document.find(marker)
    if start < 0:
        return None
    start += len(marker)
    while start < len(document) and document[start].isspace():
        start += 1
    try:
        value, _ = json.JSONDecoder().raw_decode(document, start)
    except (json.JSONDecodeError, ValueError):
        return None
    return value


def write_kline_payload_from_rendered_html(
    code: str,
    html_path: Path,
    payload_path: Path,
    route_args: dict[str, Any],
) -> bool:
    """Persist the exact rows already fetched by kline.py while rendering HTML.

    This deliberately avoids a second live-data request. A transient timeout in
    that duplicate request previously replaced a valid rendered chart with an
    empty payload, causing the frontend to hide the chart.
    """
    if not html_path.exists():
        return False
    try:
        document = html_path.read_text(encoding="utf-8")
    except OSError:
        return False
    data_by_period = inline_json_assignment(document, "dataByPeriod")
    config = inline_json_assignment(document, "config")
    if not isinstance(data_by_period, dict):
        return False
    period = str(route_args.get("period") or route_args.get("data_type") or "1d")
    rows = data_by_period.get(period)
    if not isinstance(rows, list) or not rows:
        return False

    enriched_rows: list[dict[str, Any]] = []
    previous_close: float | None = None
    for row in rows:
        if not isinstance(row, dict):
            continue
        item = dict(row)
        close = to_float(item.get("close"))
        if close is not None and previous_close not in (None, 0):
            item["change"] = close - previous_close
            item["changePct"] = (close - previous_close) / abs(previous_close) * 100
        previous_close = close if close is not None else previous_close
        enriched_rows.append(item)
    if not enriched_rows:
        return False

    sources = config.get("sources") if isinstance(config, dict) and isinstance(config.get("sources"), dict) else {}
    source = str(sources.get(period) or "rendered_kline")
    symbol = str(route_args.get("symbol") or route_args.get("code") or code).strip().upper()
    payload_path.write_text(
        json.dumps(
            {
                "type": "kline",
                "symbol": symbol,
                "symbols": [symbol],
                "period": period,
                "data": enriched_rows,
                "source": source,
                "perSymbol": {symbol: {"data": enriched_rows, "source": source}},
                "errors": {},
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )
    return True


def write_kline_payload(code: str, payload_path: Path, route_args: dict[str, Any]) -> None:
    script = script_path_for_filename("kline.py")
    spec = importlib.util.spec_from_file_location("analysis_page_planner_kline", script)
    if spec is None or spec.loader is None:
        return
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    code = str(route_args.get("symbol") or route_args.get("code") or code)
    period = str(route_args.get("period") or route_args.get("data_type") or "1d")
    limit = max(KLINE_MINIMUM_BARS, int(route_args.get("limit") or KLINE_MINIMUM_BARS))
    props = {
        "market": route_args.get("market") or "auto",
        "exchange": route_args.get("exchange") or "",
        "timeout": 8,
    }
    symbols = [
        symbol.strip().upper()
        for symbol in re.split(r"[,，;；/、\s]+", code)
        if re.fullmatch(r"[A-Z0-9^][A-Z0-9.^\-]{0,18}", symbol.strip().upper())
    ]
    symbols = list(dict.fromkeys(symbols)) or [code]

    def enrich_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        enriched_rows: list[dict[str, Any]] = []
        previous_close: float | None = None
        for row in rows:
            close = to_float(row.get("close"))
            item = dict(row)
            if close is not None and previous_close not in (None, 0):
                item["change"] = close - previous_close
                item["changePct"] = (close - previous_close) / abs(previous_close) * 100
            previous_close = close if close is not None else previous_close
            enriched_rows.append(item)
        return enriched_rows

    per_symbol: dict[str, Any] = {}
    first_data: list[dict[str, Any]] = []
    first_source = "fetch_failed"
    errors: dict[str, str] = {}
    for symbol in symbols:
        try:
            rows, source = module.fetch_rows(props, symbol, period, limit)
            enriched = enrich_rows(rows)
            per_symbol[symbol] = {"data": enriched, "source": source}
            if enriched and not first_data:
                first_data = enriched
                first_source = source
        except Exception as exc:  # noqa: BLE001
            errors[symbol] = str(exc)
            per_symbol[symbol] = {"data": [], "source": "fetch_failed", "error": str(exc)}

    payload_path.write_text(
        json.dumps(
            {
                "type": "kline",
                "symbol": code,
                "symbols": symbols,
                "period": period,
                "data": first_data,
                "source": first_source,
                "perSymbol": per_symbol,
                "errors": errors,
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )


@lru_cache(maxsize=512)
def response_language_name(text: str) -> str:
    value = (text or "").strip()
    if not value:
        return "English"
    fallback_language = fallback_response_language_name(value)
    api_key = model_api_key()
    if not api_key:
        print("Language classification fell back to input script: missing model API key", file=sys.stderr)
        return fallback_language
    allowed = {
        "English",
        "Simplified Chinese",
        "Traditional Chinese",
        "Japanese",
        "Korean",
        "Thai",
        "Spanish",
        "French",
        "German",
        "Portuguese",
    }
    prompt = (
        "Classify the user's intended response language and writing system. "
        "Return exactly one label from this list and nothing else: "
        "English, Simplified Chinese, Traditional Chinese, Japanese, Korean, Thai, Spanish, French, German, Portuguese.\n\n"
        "Important:\n"
        "- Infer the language and writing system from the user's actual input.\n"
        "- Do not infer Chinese script from locale or deployment region.\n"
        "- Choose Traditional Chinese when the user writes in Traditional Chinese, and Simplified Chinese when the user writes in Simplified Chinese.\n\n"
        f"User text: {value[:1000]}"
    )
    try:
        completion = OpenAI(
            api_key=api_key,
            base_url=VOLCANO_BASE_URL,
            timeout=12,
            max_retries=1,
        ).chat.completions.create(
            model=VOLCANO_ROUTER_MODEL,
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
            max_tokens=12,
        )
        detected = completion_text(completion, "图像语言检测").strip()
        detected = re.sub(r"^[`\"'\s]+|[`\"'\s.]+$", "", detected)
        for label in allowed:
            if detected.lower() == label.lower():
                return label
    except Exception as exc:  # noqa: BLE001
        print(f"Language classification fell back to input script: {exc}", file=sys.stderr)
    return fallback_language


def fallback_response_language_name(text: str) -> str:
    value = text or ""
    if re.search(r"[\u3040-\u30ff]", value):
        return "Japanese"
    if re.search(r"[\uac00-\ud7af]", value):
        return "Korean"
    if re.search(r"[\u0e00-\u0e7f]", value):
        return "Thai"
    if re.search(r"[\u3400-\u9fff]", value):
        traditional_signals = "偉達資勢趨數據圖線華爾買賣評級獲財體臺灣營費總淨虧損選擇執輸讀區間這個麼嗎幾廣與於為從對後業產發週點樣資訊搜尋載入開始構思行動計劃分時"
        simplified_signals = "伟达资势趋数据图线华尔买卖评级获财体台湾营费总净亏损选择执输读区间这个么吗几广与于为从对后业产发周点样信息搜索加载开始构思行动计划分时"
        traditional_score = sum(1 for char in value if char in traditional_signals)
        simplified_score = sum(1 for char in value if char in simplified_signals)
        return "Traditional Chinese" if traditional_score > simplified_score else "Simplified Chinese"
    lower = value.lower()
    if re.search(r"[¿¡ñáéíóúü]|\b(cuánto|subió|ayer|acciones|precio|análisis)\b", lower):
        return "Spanish"
    if re.search(r"[àâçéèêëîïôûùüÿœ]|\b(combien|hier|analyse|action|prix)\b", lower):
        return "French"
    if re.search(r"[äöüß]|\b(wie viel|gestern|aktie|preis|analyse)\b", lower):
        return "German"
    if re.search(r"[ãõáéíóúç]|\b(quanto|ontem|ação|preço|análise)\b", lower):
        return "Portuguese"
    return "English"


def html_lang_for_question(text: str) -> str:
    language = response_language_name(text)
    return {
        "Japanese": "ja",
        "Korean": "ko",
        "Thai": "th",
        "Traditional Chinese": "zh-Hant",
        "Simplified Chinese": "zh-CN",
        "Spanish": "es",
        "French": "fr",
        "German": "de",
        "Portuguese": "pt",
    }.get(language, "en")


def kline_script_language(text: str) -> str:
    html_lang = html_lang_for_question(text)
    if html_lang == "zh-Hant":
        return "zh-hk"
    if html_lang == "zh-CN":
        return "zh"
    if html_lang == "ja":
        return "ja"
    if html_lang == "th":
        return "th"
    return "en"


def contains_cjk_text(text: str) -> bool:
    return bool(re.search(r"[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]", text or ""))


def interpretation_language_mismatch(question: str, result: "InterpretationResult") -> bool:
    target_lang = html_lang_for_question(question)
    combined = " ".join(
        part
        for part in [
            result.title,
            result.overview,
            *[module.text for module in result.modules],
        ]
        if part
    )
    if target_lang == "en":
        return contains_cjk_text(combined)
    if target_lang == "ja":
        return not bool(re.search(r"[\u3040-\u30ff]", combined))
    if target_lang == "ko":
        return not bool(re.search(r"[\uac00-\ud7af]", combined))
    if target_lang == "th":
        return not bool(re.search(r"[\u0e00-\u0e7f]", combined))
    if target_lang == "zh-Hant":
        return bool(re.search(r"[吗这为涨图线动后级华尔买卖获数据报]", combined))
    if target_lang == "zh-CN":
        return False
    return False


def chart_screenshot_path(html_path: Path) -> Path:
    return html_path.with_suffix(".png")


def capture_chart_screenshot(html_path: Path, png_path: Path) -> Path:
    script = f"""
from pathlib import Path
from playwright.sync_api import TimeoutError as PlaywrightTimeoutError, sync_playwright

html_path = Path({str(html_path)!r}).resolve()
png_path = Path({str(png_path)!r}).resolve()
png_path.parent.mkdir(parents=True, exist_ok=True)
url = html_path.as_uri()

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    page = browser.new_page(viewport={{"width": 1600, "height": 1200}}, device_scale_factor=2)
    page.goto(url, wait_until="domcontentloaded", timeout=60000)
    try:
        page.wait_for_load_state("networkidle", timeout=12000)
    except PlaywrightTimeoutError:
        pass
    try:
        page.wait_for_function(
            \"\"\"
            () => {{
              const chart = document.querySelector('#chart, canvas, svg, .chart-container, .component-root, .yahoo-card, main');
              if (!chart) return false;
              const rect = chart.getBoundingClientRect();
              if (rect.width < 120 || rect.height < 60) return false;
              const canvases = Array.from(document.querySelectorAll('canvas'));
              if (canvases.length) {{
                return canvases.some(canvas => {{
                  if (canvas.width < 120 || canvas.height < 60) return false;
                  const ctx = canvas.getContext('2d', {{ willReadFrequently: true }});
                  if (!ctx) return false;
                  const w = Math.max(1, Math.min(canvas.width, 900));
                  const h = Math.max(1, Math.min(canvas.height, 600));
                  const data = ctx.getImageData(0, 0, w, h).data;
                  let nonWhite = 0;
                  for (let i = 0; i < data.length; i += 16) {{
                    const a = data[i + 3];
                    const r = data[i];
                    const g = data[i + 1];
                    const b = data[i + 2];
                    if (a > 16 && (r < 246 || g < 246 || b < 246)) nonWhite += 1;
                    if (nonWhite > 80) return true;
                  }}
                  return false;
                }});
              }}
              const svg = document.querySelector('svg');
              if (svg && svg.querySelector('path,line,rect,circle,polyline,polygon,text')) return true;
              return !!document.body.innerText.trim();
            }}
            \"\"\",
            timeout=25000,
        )
    except PlaywrightTimeoutError:
        pass
    page.wait_for_timeout(350)
    selectors = [
        "#chart",
        ".yahoo-card",
        ".kline-component",
        ".payout-ratio",
        ".seasonals-component",
        ".chart-container",
        ".component-root",
        "body > *",
    ]
    target = None
    for selector in selectors:
        locator = page.locator(selector).first
        try:
            if locator.count() and locator.bounding_box():
                target = locator
                break
        except Exception:
            continue
    if target is None:
        page.screenshot(path=str(png_path), full_page=True)
    else:
        target.screenshot(path=str(png_path))
    browser.close()
print(str(png_path))
"""
    result = subprocess.run(
        [sys.executable, "-c", script],
        cwd=str(ROOT),
        text=True,
        capture_output=True,
        timeout=90,
        env=PYTHON_NO_BYTECODE_ENV,
    )
    if result.returncode != 0:
        message = result.stderr.strip() or result.stdout.strip() or "chart screenshot failed"
        raise HTTPException(status_code=500, detail=f"图表截图失败：{message[-600:]}")
    if not png_path.exists():
        raise HTTPException(status_code=500, detail="图表截图失败：未生成截图文件。")
    return png_path


def capture_report_screenshot(html_path: Path, png_path: Path, *, base_url: str) -> Path:
    report_url = f"{base_url.rstrip('/')}/generated/{quote(html_path.name)}"
    script = f"""
from pathlib import Path
from playwright.sync_api import sync_playwright

html_path = Path({str(html_path)!r}).resolve()
png_path = Path({str(png_path)!r}).resolve()
png_path.parent.mkdir(parents=True, exist_ok=True)
url = {report_url!r}

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    page = browser.new_page(viewport={{"width": 1320, "height": 900}}, device_scale_factor=2)
    page.goto(url, wait_until="networkidle", timeout=60000)
    page.add_style_tag(content=\"\"\"
      html, body {{ background: transparent !important; }}
      body {{ margin: 0 !important; padding: 36px 42px !important; box-sizing: border-box !important; }}
      .report-canvas {{ box-sizing: border-box !important; }}
    \"\"\")
    page.evaluate(\"\"\"
      async () => {{
        const frames = Array.from(document.querySelectorAll('iframe'));
        await Promise.all(frames.map(frame => new Promise(resolve => {{
          if (frame.contentDocument?.readyState === 'complete') return resolve();
          frame.addEventListener('load', () => resolve(), {{once:true}});
          setTimeout(resolve, 2500);
        }})));
        for (const frame of frames) {{
          try {{
            const doc = frame.contentDocument;
            if (!doc) continue;
            const height = Math.max(
              doc.body?.scrollHeight || 0,
              doc.documentElement?.scrollHeight || 0,
              frame.clientHeight || 0
            );
            if (height > 0) frame.style.height = `${{height}}px`;
          }} catch (error) {{}}
        }}
        await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      }}
    \"\"\")
    page.wait_for_timeout(1000)
    page.screenshot(path=str(png_path), full_page=True)
    browser.close()
print(str(png_path))
"""
    result = subprocess.run(
        [sys.executable, "-c", script],
        cwd=str(ROOT),
        text=True,
        capture_output=True,
        timeout=120,
        env=PYTHON_NO_BYTECODE_ENV,
    )
    if result.returncode != 0:
        message = result.stderr.strip() or result.stdout.strip() or "report screenshot failed"
        raise RuntimeError(message)
    if not png_path.exists():
        raise RuntimeError("report screenshot did not produce a file")
    return png_path


def capture_chart_screenshots(runs: list[ModuleRun]) -> dict[str, Path]:
    screenshots: dict[str, Path] = {}
    for run in runs:
        if not is_multimodal_chart_run(run):
            continue
        png_path = chart_screenshot_path(run.html_path)
        screenshots[run.selected.filename] = capture_chart_screenshot(run.html_path, png_path)
    return screenshots


def build_multimodal_vision_context(
    question: str,
    runs: list[ModuleRun],
    screenshots: dict[str, Path] | None = None,
) -> tuple[VisionInsight, ...]:
    insights: list[VisionInsight] = []
    script = script_path_for_filename("vision_chart_analyst.py")
    if not script.exists():
        raise HTTPException(status_code=500, detail=f"找不到图像理解 SKILL 脚本：{script}")

    for run in runs:
        if not is_multimodal_chart_run(run):
            continue
        png_path = (screenshots or {}).get(run.selected.filename) or capture_chart_screenshot(
            run.html_path,
            chart_screenshot_path(run.html_path),
        )
        payload_context = build_text_generation_context(run.html_path, run.payload_path if run.payload_path.exists() else None)
        context_path = multimodal_vision_context_path(run)
        context_path.write_text(payload_context[:12000], encoding="utf-8")
        cmd = multimodal_vision_shell_command(question, run, png_path, context_path)
        try:
            result = subprocess.run(
                cmd,
                cwd=str(script.parent),
                text=True,
                capture_output=True,
                timeout=max(30, VOLCANO_VISION_TIMEOUT_SECONDS + 10),
                env=vision_subprocess_env(),
            )
        except subprocess.TimeoutExpired as exc:
            raise HTTPException(status_code=500, detail=f"图像理解 SKILL 超时：{exc}") from exc
        if result.returncode != 0:
            message = result.stderr.strip() or result.stdout.strip() or "图像理解 SKILL 执行失败"
            raise HTTPException(status_code=500, detail=f"多模态图表理解失败：{message[-700:]}")
        parsed = parse_json_object(result.stdout) or {}
        summary = str(parsed.get("summary") or "").strip()
        if not summary:
            summary = plain_text_excerpt(result.stdout, limit=360)
        if not summary:
            raise HTTPException(status_code=500, detail="多模态图表理解失败：SKILL 未返回摘要。")
        raw_has_usable_data = parsed.get("hasUsableData")
        has_usable_data = raw_has_usable_data if isinstance(raw_has_usable_data, bool) else None
        data_status = str(parsed.get("dataStatus") or "").strip().lower()
        if data_status not in {"ok", "empty", "error"}:
            data_status = ""
        latest_period = str(parsed.get("latestVisiblePeriod") or "").strip()
        latest_values_raw = parsed.get("latestVisibleValues")
        latest_values: list[dict[str, str]] = []
        if isinstance(latest_values_raw, list):
            for value_item in latest_values_raw[:8]:
                if not isinstance(value_item, dict):
                    continue
                series = str(value_item.get("series") or value_item.get("label") or "").strip()
                value = str(value_item.get("value") or "").strip()
                if series or value:
                    latest_values.append({"series": series, "value": value})
        insights.append(
            VisionInsight(
                script=run.selected.filename,
                summary=summary,
                latest_visible_period=latest_period,
                latest_visible_values=tuple(latest_values),
                has_usable_data=has_usable_data,
                data_status=data_status,
            )
        )
    return tuple(insights)


def filter_visually_empty_business_runs(
    runs: list[ModuleRun],
    insights: tuple[VisionInsight, ...],
) -> tuple[list[ModuleRun], tuple[VisionInsight, ...], tuple[str, ...]]:
    """Remove only business components that vision explicitly classified as empty/error."""
    empty_scripts = {
        insight.script
        for insight in insights
        if insight.has_usable_data is False or insight.data_status in {"empty", "error"}
    }
    if not empty_scripts:
        return runs, insights, ()
    removed = tuple(
        run.selected.filename
        for run in runs
        if run.selected.filename in BUSINESS_CHART_SCRIPT_FILES and run.selected.filename in empty_scripts
    )
    if not removed:
        return runs, insights, ()
    removed_set = set(removed)
    filtered_runs = [run for run in runs if run.selected.filename not in removed_set]
    filtered_insights = tuple(insight for insight in insights if insight.script not in removed_set)
    return filtered_runs, filtered_insights, removed


def multimodal_vision_shell_command(
    question: str,
    run: ModuleRun,
    png_path: Path,
    context_path: Path,
) -> list[str]:
    script = script_path_for_filename("vision_chart_analyst.py")
    return [
        sys.executable,
        str(script),
        "--question",
        question,
        "--image",
        str(png_path),
        "--module-label",
        run.selected.label,
        "--script",
        run.selected.filename,
        "--code",
        run.code,
        "--context-file",
        str(context_path),
        "--language",
        html_lang_for_question(question),
    ]


def multimodal_vision_context_path(run: ModuleRun) -> Path:
    return GENERATED_DIR / f"{run.html_path.stem}-vision-context.txt"


def multimodal_vision_shell_commands_for_display(
    question: str,
    runs: list[ModuleRun],
    screenshots: dict[str, Path],
) -> list[list[str]]:
    commands: list[list[str]] = []
    for run in runs:
        if not is_multimodal_chart_run(run):
            continue
        png_path = screenshots.get(run.selected.filename)
        if not png_path:
            continue
        context_path = multimodal_vision_context_path(run)
        commands.append(redact_command(multimodal_vision_shell_command(question, run, png_path, context_path)))
    return commands


def safe_build_multimodal_vision_context(
    question: str,
    runs: list[ModuleRun],
    screenshots: dict[str, Path] | None = None,
) -> tuple[VisionInsight, ...]:
    try:
        return build_multimodal_vision_context(question, runs, screenshots=screenshots)
    except Exception as exc:  # noqa: BLE001 - visual analysis is helpful, not required for final output
        print(f"Multimodal vision skipped: {exc}", file=sys.stderr)
        return ()


def validate_visual_outputs(
    question: str,
    runs: list[ModuleRun],
    screenshots: dict[str, Path],
    vision_insights: tuple[VisionInsight, ...],
) -> VisualValidation:
    if not runs or not screenshots:
        return VisualValidation(ok=True, summary="未生成截图，跳过视觉校验。")
    deterministic_validation = deterministic_visual_validation(runs)
    if deterministic_validation is not None:
        return deterministic_validation
    api_key = (
        model_api_key()
    )
    if not api_key:
        return VisualValidation(ok=True, summary="未配置视觉模型，跳过视觉校验。")
    payload_blocks: list[str] = []
    for run in runs:
        payload_blocks.append(
            f"Module: {run.selected.label} ({run.selected.filename})\n"
            f"Payload/context:\n{build_text_generation_context(run.html_path, run.payload_path if run.payload_path.exists() else None)[:5000]}"
        )
    insight_text = json.dumps(
        [{"script": item.script, "summary": item.summary} for item in vision_insights],
        ensure_ascii=False,
        indent=2,
    )
    prompt = (
        "你是图表结果的灾难级问题校验器。请结合用户需求、图表截图、结构化 payload 和读图摘要，"
        "只判断最终可视化是否存在必须重新规划的硬失败。\n"
        "只能在这些情况判失败：1. 图表为空、空数据、暂无数据、白屏、未渲染或明显报错；"
        "2. 图表主题与用户问句严重不符，例如用户要 K 线却展示脑图，用户问英伟达却展示比特币；"
        "3. 渲染严重损坏，主要内容完全不可见。\n"
        "不要校验数据正确性、财务口径、字段定义、数值精度、单位换算、指标是否完整、系列命名、轻微错轴、配色、字号或排版。"
        "不要因为缺少某个子指标、费用/成本口径不够细、payload 字段映射可优化而判失败。"
        "如果不确定是否属于硬失败，必须返回 ok=true。\n"
        "若发现硬失败，给出可以交给 ReAct 重新规划的修正指令。\n"
        "返回 JSON：{\"ok\":true|false,\"summary\":\"...\",\"issues\":[\"...\"],\"repairInstruction\":\"...\"}。\n\n"
        f"用户需求：{question}\n\n"
        f"读图摘要：\n{insight_text}\n\n"
        f"结构化上下文：\n{chr(10).join(payload_blocks)}"
    )
    content: list[dict[str, Any]] = [{"type": "text", "text": prompt}]
    for run in runs:
        shot = screenshots.get(run.selected.filename)
        if not shot or not shot.exists():
            continue
        image_base64 = base64.b64encode(shot.read_bytes()).decode("ascii")
        content.append({"type": "image_url", "image_url": {"url": f"data:image/png;base64,{image_base64}"}})
    try:
        client = OpenAI(api_key=api_key, base_url=vision_base_url(), timeout=VOLCANO_VISION_TIMEOUT_SECONDS)
        completion = create_chat_completion(
            client,
            json_object=True,
            model=VOLCANO_VISION_MODEL,
            messages=[{"role": "user", "content": content}],
            temperature=0,
            max_tokens=800,
        )
    except Exception as exc:  # noqa: BLE001
        print(f"Visual validation skipped: {exc}", file=sys.stderr)
        return VisualValidation(ok=True, summary="视觉校验调用失败，跳过阻断。")
    parsed = parse_json_object(completion_text(completion, "多模态图表理解")) or {}
    issues_raw = parsed.get("issues") if isinstance(parsed.get("issues"), list) else []
    issues = tuple(str(item).strip() for item in issues_raw if str(item).strip())
    summary = str(parsed.get("summary") or "").strip()
    repair_instruction = str(parsed.get("repairInstruction") or "").strip()
    ok = bool(parsed.get("ok", True))
    if not ok and not visual_validation_has_blocking_issue(summary, issues, repair_instruction):
        return VisualValidation(
            ok=True,
            summary="视觉校验仅发现非阻断性数据口径或表达建议，按策略跳过修正。",
            issues=(),
            repair_instruction="",
        )
    return VisualValidation(
        ok=ok,
        summary=summary or ("校验通过。" if not issues else "校验发现问题。"),
        issues=issues,
        repair_instruction=repair_instruction,
    )


def visual_validation_has_blocking_issue(
    summary: str,
    issues: tuple[str, ...],
    repair_instruction: str,
) -> bool:
    text = " ".join((summary, " ".join(issues), repair_instruction)).lower()
    blocking_markers = (
        "空数据",
        "暂无数据",
        "空图",
        "空白",
        "白屏",
        "未渲染",
        "没有渲染",
        "渲染失败",
        "报错",
        "错误页面",
        "占位图",
        "placeholder",
        "no data",
        "empty",
        "blank",
        "render failed",
        "error",
        "严重不符",
        "完全不符",
        "主题不符",
        "问句严重不符",
        "不相关",
        "完全无关",
        "错图",
        "图表类型错误",
        "wrong chart",
        "unrelated",
    )
    return any(marker in text for marker in blocking_markers)


def deterministic_visual_validation(runs: list[ModuleRun]) -> VisualValidation | None:
    issues: list[str] = []
    for run in runs:
        payload = read_json_file(run.payload_path)
        if not isinstance(payload, dict):
            continue
        if run.selected.filename == "bar_line.py":
            issue = bar_line_payload_issue(payload)
            if issue:
                issues.append(issue)
    if not issues:
        return None
    return VisualValidation(
        ok=False,
        summary="图表校验未通过：检测到无效或占位柱折图。",
        issues=tuple(issues),
        repair_instruction="不要生成兜底图或占位图；如果没有足够字段绘制柱折图，请直接返回失败。若用户提供了文本表格数据，必须先结构化出年份、柱系列和折线系列后再绘图。",
    )


def read_json_file(path: Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def bar_line_payload_issue(payload: dict[str, Any]) -> str:
    data = payload.get("data")
    if not isinstance(data, list) or not data:
        return "bar_line.py 没有可绘制数据。"
    x_field = str(payload.get("xField") or "")
    columns = payload.get("columnSeries")
    lines = payload.get("lineSeries")
    if not isinstance(columns, list) or not columns or not isinstance(lines, list) or not lines:
        return "bar_line.py 缺少柱系列或折线系列。"
    column_fields = [str(item.get("field") or "") for item in columns if isinstance(item, dict)]
    line_fields = [str(item.get("field") or "") for item in lines if isinstance(item, dict)]
    if is_placeholder_bar_line_payload_shape(data, x_field, column_fields, line_fields, str(payload.get("title") or "")):
        return "bar_line.py 生成了 value/bar/line 这类占位兜底图。"
    valid_rows = [row for row in data if isinstance(row, dict)]
    if not valid_rows:
        return "bar_line.py 数据行不是对象。"
    required_fields = [field for field in [x_field, *column_fields, *line_fields] if field]
    if not required_fields or any(field not in valid_rows[0] for field in required_fields):
        return "bar_line.py payload 字段与数据行不匹配。"
    numeric_fields = [field for field in [*column_fields, *line_fields] if isinstance(valid_rows[0].get(field), (int, float))]
    if len(numeric_fields) < 2:
        return "bar_line.py 可绘制数值系列不足。"
    return ""


def safe_validate_visual_outputs(
    question: str,
    runs: list[ModuleRun],
    screenshots: dict[str, Path],
    vision_insights: tuple[VisionInsight, ...],
) -> VisualValidation:
    try:
        return validate_visual_outputs(question, runs, screenshots, vision_insights)
    except Exception as exc:  # noqa: BLE001
        print(f"Visual validation skipped: {exc}", file=sys.stderr)
        return VisualValidation(ok=True, summary="视觉校验异常，跳过阻断。")


def visual_validation_observation(validation: VisualValidation) -> str:
    return json.dumps(
        {
            "ok": validation.ok,
            "summary": validation.summary,
            "issues": list(validation.issues),
            "repairInstruction": validation.repair_instruction,
        },
        ensure_ascii=False,
        indent=2,
    )


def interpret_with_volcano(
    question: str,
    runs: list[ModuleRun],
    vision_insights: tuple[VisionInsight, ...] = (),
) -> InterpretationResult:
    deterministic = deterministic_factual_interpretation(question, runs)
    if deterministic:
        return strengthen_integrated_overview_from_modules(deterministic)

    api_key = (
        model_api_key()
    )
    if not api_key:
        return strengthen_integrated_overview_from_modules(fallback_interpretation_result(question, runs))

    data_context = build_multi_module_context(runs)
    vision_context = build_vision_summary_context(vision_insights)
    codes = ", ".join(sorted({run.code for run in runs}))
    module_labels = "、".join(run.selected.label for run in runs)
    language_name = response_language_name(question)
    html_lang = html_lang_for_question(question)

    strict_language_rules = {
        "en": (
            "The target output language is English. Every visible sentence must be natural English. "
            "Do not output Chinese, Japanese, or Korean characters anywhere in title, overview, or module text."
        ),
        "ja": "The target output language is Japanese. Every visible sentence must be Japanese.",
        "ko": "The target output language is Korean. Every visible sentence must be Korean.",
        "th": "The target output language is Thai. Every visible sentence must be natural Thai.",
        "zh-Hant": (
            "The target output language is Traditional Chinese. Every Chinese character must be Traditional Chinese. "
            "Do not output Simplified Chinese."
        ),
        "zh-CN": "The target output language is Simplified Chinese. Do not output Traditional Chinese.",
        "es": "The target output language is Spanish. Every visible sentence must be Spanish.",
        "fr": "The target output language is French. Every visible sentence must be French.",
        "de": "The target output language is German. Every visible sentence must be German.",
        "pt": "The target output language is Portuguese. Every visible sentence must be Portuguese.",
    }.get(html_lang, f"The target output language is {language_name}. Every visible sentence must be {language_name}.")
    watchlist_label = "自选候选：" if html_lang in {"zh-CN", "zh-Hant"} else "Watchlist candidates:"
    watchlist_output_rule = (
        "The user explicitly asked to write recommendations to AInvest Watchlist. In the final overview, include exactly one explicit shortlist sentence that starts with this exact literal label: "
        f"'{watchlist_label}'. Do not translate, paraphrase, or replace that label with a synonym. Continue with 'Company (TICKER), Company (TICKER)'. Include 1-5 real tradable US stocks or ETFs only. "
        "Every candidate must include its exchange-valid ticker in parentheses. Never include macroeconomic indicators, releases, institutions, currencies, commodities, or generic acronyms such as PPI, CPI, GDP, PCE, PMI, FOMC, FED, USD, WTI, AI, or ETF as candidate tickers. "
        "Only names in that explicit shortlist sentence will be eligible for account mutation.\n"
        if wants_research_then_watchlist_write(question)
        else ""
    )
    requested_annotation_tool = requested_text_draw_tool(question)
    annotation_shape = (
        '{"symbol":"GOOGL","type":"callout","time":"2026-08-13 16:00","price":123.45,"text":"近期卖点参考"}'
        if requested_annotation_tool == "callout"
        else '{"symbol":"GOOGL","type":"text","time":"2026-08-13 16:00","price":123.45,"text":"财报日"}'
        if requested_annotation_tool == "text"
        else '{"symbol":"GOOGL","type":"horizontal","price":123.45,"text":"近期卖点参考"}'
    )
    annotation_type_rule = (
        f"The requested annotation tool is {requested_annotation_tool}. Include an exact YYYY-MM-DD HH:MM time from the newest K-line evidence. "
        if requested_annotation_tool in {"text", "callout"}
        else "For a sell point, resistance, take-profit, or stop-loss line, type must be horizontal. "
    )
    chart_annotation_output_rule = (
        "The user asked you to infer a technical chart level and place an annotation on the AiChart K-line. "
        "Return exactly one item in the top-level JSON field chart_annotations. Use this object shape: "
        f"{annotation_shape}. "
        "Derive price from the newest K-line price structure, moving averages, recent swing high/low, volume, and visible indicators in the supplied evidence. "
        f"{annotation_type_rule}Price must be a positive numeric value, not a string. "
        "Use the actual requested ticker and concise user-language text. Do not return screen pixels, guessed percentages, or an external AInvest URL. "
        "This annotation is a technical reference level, so explain its confirmation/invalidation condition in the overview without giving an absolute trading instruction.\n"
        if wants_model_derived_chart_annotation(question)
        else ""
    )

    def build_prompt(
        retry: bool = False,
        force_integrated: bool = False,
        final_rewrite: bool = False,
        force_module_specific: bool = False,
    ) -> str:
        retry_clause = (
            "Your previous answer used the wrong language. Fix that now. "
            "Return the same factual content in the correct target language only.\n\n"
            if retry
            else ""
        )
        integrated_retry_clause = (
            "Your previous answer failed because the overview was too short, too generic, or described the module instead of answering the user. "
            "Rewrite the overview as the full integrated answer. Do not use phrases like 'this module', 'this framework', '本模块', '本模组', '基础框架', or '提供基础'.\n\n"
            if force_integrated
            else ""
        )
        final_rewrite_clause = (
            "Final repair instruction: ignore any prior module-by-module wording. Read the complete context package as one evidence set, then write a fresh integrated answer. "
            "The overview must be the answer itself, not a preparation note, framework note, source inventory, or chart caption. "
            "Do not merge or concatenate module notes. Generate the answer from the context with professional investment-analysis reasoning.\n\n"
            if final_rewrite
            else ""
        )
        module_specific_clause = (
            "Your previous module text was too generic or lacked concrete chart evidence. Rewrite every business-chart module text from that module's structured payload excerpt and visual chart insight only. "
            "Each business-chart module text must include: (1) the latest visible date/period, (2) at least one concrete latest metric value, preferably two when available, (3) one comparison with prior period, historical range, peer/industry/market, or chart structure, and (4) the investment implication for the user's question. "
            "A successfully rendered business-chart module that has structured payload, rendered chart text, or visual chart insight counts as having enough evidence. Do not leave its module text empty; extract the best available latest period, metric, comparison, and implication from that evidence. "
            "Only leave module text empty when the module truly has no successful output, no structured payload, no rendered chart text, and no visual insight.\n\n"
            if force_module_specific
            else ""
        )
        return (
            "You are a careful professional equity analyst.\n"
            f"{retry_clause}"
            f"{integrated_retry_clause}"
            f"{final_rewrite_clause}"
            f"{module_specific_clause}"
            f"{strict_language_rules}\n"
            f"{watchlist_output_rule}"
            f"{chart_annotation_output_rule}"
            f"Use {language_name} for every user-visible field in the JSON response: title, overview, and every module text.\n"
            "Some source facts below may be written in Chinese. You may read and translate them internally, but your final output must strictly stay in the target output language.\n"
            "Only use the user's question and the complete context package below, including structured payloads, retrieved text, rendered chart text, video-card metadata, mind-map content, and visual observations.\n"
            "You are also given a visual-analysis layer produced from chart screenshots. Treat those visual observations as an important input, but do not mention screenshots or validation.\n"
            "If the visual-analysis layer includes 'Latest visible period from chart right edge' or 'Latest visible values from chart right edge', treat those fields as the chart's latest visible time/value. Use them before any older written commentary, generic chart title, or historical-window wording.\n"
            "If structured payload text and visual right-edge reading disagree about the latest period, reconcile them by saying the chart's latest visible point is the right-edge period and base the investment interpretation on that latest visible point. Historical dates in the x-axis range are references only.\n"
            "Write as a professional investment-analysis answer to the user's question, not as a news/article/source digest. The user should feel they received a direct analytical answer.\n"
            "Generate ONE integrated answer that uses all available text, chart, search, video, mind-map, and visual observations together. Do not write separate mini-answers for each data source.\n"
            "Use a clear top-summary, module-evidence, final-summary structure for the rendered report: overview paragraph 1 states the direct analytical judgment and conclusion upfront; module texts carry the middle evidence; the final overview paragraph closes with a concise bottom-line judgment and what to monitor next.\n"
            "The overview is split by the UI into opening summary and final conclusion. It is mandatory. For analytical investment questions, write 2-3 compact paragraphs with clean paragraph breaks: paragraph 1 is the upfront overall judgment, and the final paragraph is the concluding summary after the chart modules. Do not make it one giant paragraph.\n"
            "Make the analysis sufficiently detailed: after citing important facts or figures, explain why they matter for an investor, including likely effects on earnings expectations, order visibility, valuation multiples, market sentiment, competitive position, risk premium, or the next confirmation point. Do not stop at fact listing.\n"
            "Each overview paragraph should have a distinct job: direct answer first, final judgment last. Put module-specific evidence in module text rather than duplicating every module detail in the overview. Avoid repeating the same conclusion in multiple paragraphs.\n"
            "The overview must answer the user's question directly and synthesize all useful evidence across modules. It must not say a module/framework/data set 'provides a foundation' or 'summarizes related information'.\n"
            "Module text is supporting analysis generated from that module's own structured payload excerpt plus the matching visual chart insight. For business chart modules, write one natural paragraph of about 200 Chinese characters when the target language is Chinese, acceptable range 170-240 Chinese characters, or a similar density in other languages. "
            "Use exactly this evidence flow: latest visible date/period and latest metric value first; then compare against the prior period, historical range, peer/industry/market, or chart structure; then state the investment implication for the user's question. "
            "Do not write a module paragraph that only says a factor is low, limited, attractive, unattractive, stable, or worth monitoring. Such judgments must be tied to the concrete latest value and comparison used to reach them. "
            "If a module contains rendered chart text, source-card metadata, structured payload fields, or visual observations, synthesize the available evidence together; do not ignore the multimodal layer. "
            "For every successful business-chart module with a payload, rendered chart text, or visual insight, module text is mandatory and must be non-empty. If the latest period is not explicitly labeled, use the latest visible/rightmost point, latest record, current snapshot, or reporting period from the payload and say it naturally. "
            "Only return an empty module text when that script has no successful output and no usable evidence at all; never return empty merely because one of payload, rendered text, or visual insight is incomplete. "
            "Never use stitched template phrases, chart-mechanics descriptions, or defensive data-availability wording such as 'this module', 'this chart', '本模块', '本模组', '本圖', '当前采用', '目前采用', '当前使用', '使用了', '用的是', '年度视图', '季度视图', '累计视图', '从图形趋势看', '从图表看', '同样有可用信息', '并非无数据', '不是无数据', '暂无外部信息', '这项数据应作为', '投资上重点看', '吸引力有限', '空间有限', or '缺乏动力'. Do not describe which chart/view is used; interpret the data values, comparisons, and investment implications directly.\n"
            "Do not prefix sentences with labels such as 'my core view is', 'my direct read is', 'my view is', '我的核心观点是', '我的直接判断是', '核心观点', or equivalents. State the view directly as normal prose.\n"
            "Use professional investment-analysis reasoning and implication language, but do not use repetitive first-person formulas. Do not give absolute buy/sell instructions. Do not use visible advisory-role labels in Chinese or English.\n"
            "Answer the user's actual analytical question first. If the user asks for a chart/statistical comparison, the main narrative must be driven by the chart/data module metrics, rankings, final values, turning points, and divergences. Search modules should support the investment judgment, not become a source-by-source recap.\n"
            "When Yahoo/event-window/chart data is present together with external search, do not open with a paragraph about how many sources were found. Open with the chart/data conclusion that answers the user's question.\n"
            "For event-window charts, use the actual number of verified event windows in the structured data. If it is fewer than the count requested by the user, explicitly say only that many verified event dates were found, and do not imply the requested count was fully satisfied.\n"
            "For technical or short-term price questions using K-line charts, the overview must contain a dedicated paragraph interpreting the market chart itself: latest price, distance to the user's target price, moving-average structure, recent high/low range, volume/turnover/liquidity, MACD/indicator confirmation when visible, and whether money participation confirms or contradicts the price move. For crypto assets, treat volume/turnover/liquidity as the practical funding-participation evidence when dedicated fund-flow data is unavailable.\n"
            "Focus on the latest available period, the latest trading day, or the latest available data point first; you may compare it with the prior period, prior year, or historical highs/lows when useful.\n"
            "Latest-data priority is mandatory: identify the newest available date/period/data point first, make it the anchor of the investment interpretation, then use historical or past-window performance only as a reference for momentum, base effects, persistence, volatility, or reversal risk. Do not let the earliest year, average history, or old cycle behavior become the main conclusion unless the user explicitly asks for a pure historical review.\n"
            "For time-series charts and requests phrased as 'past N years', 'last N years', '过去 N 年', or '近 N 年', do not narrate from oldest to newest as a history recap. Start with the latest value/state, then compare it against the immediately prior period and the most relevant historical reference points in the shown window.\n"
            "If the latest data conflicts with the historical trend, explicitly state that the latest evidence has changed or weakened/strengthened the earlier pattern, and make the forward-looking implication depend primarily on the latest data.\n"
            "Each module text must explicitly mention the latest period label or date, and at least one key latest-period metric. Never mistake the earliest year for the latest data.\n"
            "Numeric prose style is mandatory: do not dump every plotted value as a comma-separated sequence such as '柱依次为 26.97、60.92、130.50、215.94 十亿美元' or 'values are A, B, C, D'. For a 3+ point series, summarize it as a readable comparison: latest value, start-to-latest change, peak/trough, range, growth rate, or turning point. Mention at most 2-3 decisive numbers in one sentence unless the user explicitly asks for a full table/list. Always attach units to each isolated key number or make the unit scope unambiguous, e.g. '从 26.97 十亿美元增至 215.94 十亿美元', not '26.97、60.92、130.50、215.94十亿美元'.\n"
            "For search modules such as ainvest_news_search.py, ainvest_video_search.py, and external_info_search.py, synthesize the facts into investment-relevant themes: catalysts, financial/operational impact, market reaction, valuation/risk implications, disagreements, and next checkpoints. For each major theme, explicitly connect the retrieved information to the user's question and to an investor's decision context. Do not write a source inventory, article list, or 'these sources show...' paragraph unless the user explicitly asks for source comparison.\n"
            "For ainvest_video_search.py specifically, if an external_info_search.py module is also present after the video module, treat the video titles as search leads and use the external-search facts to explain the business meaning behind those videos. Do not merely restate video titles, do not say the cards only have titles, and do not write a generic 'use it as sentiment clues' paragraph. Connect the searched context to the user's requested dimensions such as AI strategy, product cycle, catalysts, valuation upside, analyst expectations, and trend sustainability.\n"
            "Exception: when a search module is only used to establish dates/entities for a chart calculation, keep that search-module text to one compact sentence and make it subordinate to the chart result.\n"
            "For direct factual search questions that ask who, when, which date, where, or how many, answer the requested facts directly as a concise list before explaining source agreement. Do not merely describe what the search results cover.\n"
            "For broad market-hotspot questions, do not answer with abstract buckets such as 'market drivers' or 'investor focus' alone. Name the concrete events, tickers, sectors, policies, analyst actions, deals, or earnings items found in the search results, then explain why they matter.\n"
            "If the latest available data is not from the current year, explicitly say 'latest available data as of ...' in the target language instead of implying fresher data exists.\n"
            "Output only the latest-data takeaway, chart trend, structural change, and what those changes imply for an investor's judgment.\n"
            "Avoid opening or closing phrases like 'this analysis summarizes', 'the sources show', 'according to retrieved news', 'the search results cover', or equivalents. Start with the answer, not the research process.\n"
            "If the chart visually shows a newer visible period than the written raw-data commentary might suggest, use the latest visible period/date from the chart and reconcile it with the structured data. Never call the leftmost x-axis label or the start of the displayed range the latest data.\n"
            "Do not mention scripts, APIs, models, screenshots, multimodal recognition, HTML, errors, generation steps, or disclaimers.\n"
            "Do not write notes or parenthetical disclaimers such as '注：因原数据未提供...', '暂按要求补充...', 'because the source data did not provide...', or any statement that says content was logically supplemented. If data is missing, simply omit that unsupported claim or state the latest available factual value.\n"
            "Do not write Markdown tables. Do not give a generic company introduction. Do not invent facts outside the provided data.\n"
            "Use Markdown bold with double asterisks to mark the most important answer-specific phrases. Decide importance by comparing the user's actual question with the answer evidence; do not mechanically bold every number. "
            "Priority is: (1) the direct conclusion that resolves the user's main question, (2) the decisive latest value/date/comparison/turning point that supports it, and (3) a material risk or next confirmation point that could change it. "
            "Add 1-2 concise bold spans per substantive paragraph; a short paragraph may use one. In each module paragraph, normally bold one decisive metric/date and one investment implication. "
            "Bold complete semantic phrases such as '**当前合计亏损约8,830港元**' or '**腾讯的亏损抵消了阿里的浮盈**', not isolated adjectives, labels, company names, or every number. "
            "Never bold an entire sentence, an entire bullet, or more than roughly one quarter of the answer. Avoid repeating the same bold phrase across overview and module text. "
            "Use only **...** for importance emphasis; do not emit HTML or underline syntax.\n"
            "Write in polished prose that reads like an investment analysis answer, not a pasted source summary. The UI will attach citations next to the relevant paragraphs, so make each paragraph evidence-specific enough that the citation placement is meaningful. Use paragraph breaks deliberately; never return the overview as one long paragraph.\n"
            "Return JSON only, with no extra explanation.\n"
            'JSON schema: {"title":"short professional analysis title in the target language","overview":"mandatory 2-3 compact paragraphs in the target language; paragraph 1 is the opening overall judgment and the final paragraph is the closing conclusion summary","modules":[{"script":"income_statement.py","text":"one model-generated focused module analysis paragraph in the target language; for successful business chart modules this field is mandatory and non-empty; aim for about 200 Chinese characters, acceptable range 170-240 Chinese characters, or a similar density in other languages; it must include latest period/date, latest metric value, comparison/trend/structure, and investor implication; Markdown emphasis allowed"}],"chart_annotations":[{"symbol":"GOOGL","type":"horizontal|text|callout","time":"optional YYYY-MM-DD HH:MM for text/callout","price":123.45,"text":"technical reference label in the target language"}]}.\n'
            "The title must be written naturally from the user's question and selected modules, not as a mechanical module-name concatenation.\n"
            "The modules array must follow the input module order. Each module text should explain the latest metric, trend or structure, and the investor implication for that specific component. Avoid one-line labels, process notes, or vague statements that merely say the component provides evidence.\n"
            "Use a professional analysis tone that helps the user understand the data, without giving absolute buy/sell instructions or repeated 'view' labels.\n\n"
            f"User question: {question}\n"
            f"Codes: {codes}\n"
            f"Chart modules: {module_labels}\n"
            f"Visual chart insights:\n{vision_context}\n\n"
            f"Complete context package for ARK integrated generation:\n{data_context}"
        )

    def run_completion(prompt: str) -> InterpretationResult:
        if AICHART_AGENT_ENGINE == "autogen":
            raw = complete_text_with_autogen(
                prompt=prompt,
                api_key=api_key,
                base_url=VOLCANO_BASE_URL,
                model=VOLCANO_INTERPRET_MODEL,
                timeout_seconds=VOLCANO_INTERPRET_TIMEOUT_SECONDS,
                temperature=0.2,
                max_tokens=6000,
            )
        else:
            content: list[dict[str, Any]] = [{"type": "text", "text": prompt}]
            client = OpenAI(api_key=api_key, base_url=VOLCANO_BASE_URL, timeout=VOLCANO_INTERPRET_TIMEOUT_SECONDS)
            completion = create_chat_completion(
                client,
                json_object=True,
                model=VOLCANO_INTERPRET_MODEL,
                messages=[{"role": "user", "content": content}],
                temperature=0.2,
                max_tokens=6000,
                **structured_planner_model_options(VOLCANO_INTERPRET_MODEL),
            )
            raw = completion_text(completion, "综合解读模型")
        try:
            result = parse_interpretation_result(raw, runs, question)
        except HTTPException as exc:
            print(f"Interpretation JSON parse skipped: {exc.detail}", file=sys.stderr)
            result = fallback_interpretation_result(question, runs)
        if html_lang == "zh-Hant":
            result = InterpretationResult(
                title=to_traditional_chinese(result.title),
                overview=to_traditional_chinese(result.overview),
                modules=tuple(
                    ModuleInterpretation(script=item.script, text=to_traditional_chinese(item.text))
                    for item in result.modules
                ),
                chart_annotations=tuple(
                    {**item, "text": to_traditional_chinese(str(item.get("text") or ""))}
                    for item in result.chart_annotations
                ),
            )
        return result

    try:
        result = run_completion(build_prompt())
        if wants_model_derived_chart_annotation(question):
            annotations = infer_model_kline_annotations(question, runs, proposals=result.chart_annotations)
            if annotations != result.chart_annotations:
                result = InterpretationResult(
                    title=result.title,
                    overview=result.overview,
                    modules=result.modules,
                    chart_annotations=annotations,
                )
            return strengthen_integrated_overview_from_modules(result)
        if interpretation_language_mismatch(question, result):
            result = run_completion(build_prompt(retry=True))
        if interpretation_modules_too_weak(question, result, runs):
            result = run_completion(build_prompt(force_module_specific=True))
        if interpretation_overview_too_weak(question, result):
            result = run_completion(build_prompt(force_integrated=True))
        if interpretation_modules_too_weak(question, result, runs):
            result = run_completion(build_prompt(force_module_specific=True, final_rewrite=True))
        if interpretation_overview_too_weak(question, result):
            result = run_completion(build_prompt(force_integrated=True, final_rewrite=True))
        return strengthen_integrated_overview_from_modules(result)
    except Exception as exc:  # noqa: BLE001 - external service failure
        print(f"Volcano model call failed: {exc}", file=sys.stderr)
        return strengthen_integrated_overview_from_modules(fallback_interpretation_result(question, runs))


def deterministic_factual_interpretation(question: str, runs: list[ModuleRun]) -> InterpretationResult | None:
    yahoo_unavailable_result = deterministic_yahoo_unavailable_interpretation(question, runs)
    if yahoo_unavailable_result:
        return yahoo_unavailable_result
    event_day_result = deterministic_event_day_return_interpretation(question, runs)
    if event_day_result:
        return event_day_result
    if should_use_presidential_spy_event_window(question):
        return None
    if not runs or not any(run.selected.filename == EXTERNAL_INFO_SEARCH_SCRIPT for run in runs):
        return None
    normalized = re.sub(r"\s+", "", question.lower())
    asks_us_presidents = any(term in question for term in ("美国", "美國")) and any(
        term in question for term in ("总统", "總統")
    )
    asks_since_2000 = "2000" in normalized
    asks_inauguration = any(term in question for term in ("就职", "就職", "inauguration"))
    if not (asks_us_presidents and asks_since_2000 and asks_inauguration):
        return None
    text = (
        "按“2000年以来曾在任美国总统”的口径，名单和就职日期如下：\n"
        "- 比尔·克林顿：1993年1月20日就职；2000年仍在任，任期至2001年1月20日。\n"
        "- 乔治·W·布什：2001年1月20日就职。\n"
        "- 贝拉克·奥巴马：2009年1月20日就职。\n"
        "- 唐纳德·特朗普：2017年1月20日首次就职。\n"
        "- 乔·拜登：2021年1月20日就职。\n"
        "- 唐纳德·特朗普：2025年1月20日再次就职。\n\n"
        "如果只统计“2000年以后新就职”的总统，则不包含克林顿，顺序为乔治·W·布什、奥巴马、特朗普、拜登、特朗普第二任。"
    )
    return InterpretationResult(
        title="2000年以来美国历任总统及就职日期",
        overview="",
        modules=tuple(ModuleInterpretation(script=run.selected.filename, text=text) for run in runs),
    )


def deterministic_yahoo_unavailable_interpretation(
    question: str,
    runs: list[ModuleRun],
) -> InterpretationResult | None:
    if not requested_yahoo_data_source(question):
        return None
    yahoo_run: ModuleRun | None = None
    payload: dict[str, Any] = {}
    for run in runs:
        if run.selected.filename != "yahoo_data.py" or not run.payload_path.exists():
            continue
        candidate = read_payload(run.payload_path)
        if candidate.get("type") == "yahoo-data-unavailable" and candidate.get("unavailable") is True:
            yahoo_run = run
            payload = candidate
            break
    if yahoo_run is None:
        return None

    symbol = str(payload.get("symbol") or yahoo_run.code or "").strip()
    metric = str(payload.get("metric") or "").strip()
    period = str(payload.get("requestedPeriodType") or "").strip()
    metric_labels = {
        "totalRevenue": "营收",
        "netIncome": "净利润",
        "operatingIncome": "营业利润",
        "grossProfit": "毛利润",
    }
    period_labels = {"quarterly": "季度", "annual": "年度"}
    metric_label_text = metric_labels.get(metric, str(payload.get("metricLabel") or metric or "财务指标"))
    period_label_text = period_labels.get(period, period or "指定期间")
    overview = (
        f"**Yahoo 没有提供 {symbol} 的最新{period_label_text}{metric_label_text}数据**。"
        f"该代码已正确映射到澳交所主上市代码 {symbol}；Yahoo 返回的{period_label_text}{metric_label_text}序列为空，"
        "因此无法从 Yahoo 给出所请求的确切数值。这是数据源字段缺失，不是模块执行失败。"
    )
    title = f"Yahoo 未提供 {symbol} 最新{period_label_text}{metric_label_text}"
    modules = tuple(
        ModuleInterpretation(script=run.selected.filename, text="")
        for run in runs
    )
    result = InterpretationResult(title=title, overview=overview, modules=modules)
    if html_lang_for_question(question) == "zh-Hant":
        return InterpretationResult(
            title=to_traditional_chinese(result.title),
            overview=to_traditional_chinese(result.overview),
            modules=result.modules,
        )
    return result


def deterministic_event_day_return_interpretation(question: str, runs: list[ModuleRun]) -> InterpretationResult | None:
    yahoo_run: ModuleRun | None = None
    payload: dict[str, Any] = {}
    for run in runs:
        if run.selected.filename != "yahoo_data.py" or not run.payload_path.exists():
            continue
        candidate = read_payload(run.payload_path)
        if candidate.get("chartType") == "bar" and candidate.get("metric") == "eventDayReturnPct":
            yahoo_run = run
            payload = candidate
            break
    if yahoo_run is None:
        return None
    rows = payload.get("rows")
    if not isinstance(rows, list) or not rows:
        return None

    valid_rows = [row for row in rows if isinstance(row, dict) and isinstance(row.get("value"), (int, float))]
    if not valid_rows:
        return None
    valid_rows.sort(key=lambda row: str(row.get("date") or ""))
    latest = valid_rows[-1]
    highest = max(valid_rows, key=lambda row: float(row.get("value") or 0))
    lowest = min(valid_rows, key=lambda row: float(row.get("value") or 0))

    def pct(row: dict[str, Any]) -> str:
        return f"{float(row.get('value') or 0):+.2f}%"

    def label(row: dict[str, Any]) -> str:
        event = str(row.get("event") or row.get("sourceEvent") or "").strip()
        return plain_text_excerpt(event, limit=44) if event else "事件"

    row_lines = []
    for row in valid_rows:
        date = str(row.get("date") or "")
        trading_date = str(row.get("tradingDate") or "")
        trading_note = f"（交易日 {trading_date}）" if trading_date and trading_date != date else ""
        row_lines.append(f"- {date}{trading_note}：{pct(row)}，{label(row)}")

    title = str(payload.get("title") or "事件当日涨跌幅").replace(",", "")
    overview = (
        f"共匹配到 {len(valid_rows)} 个可计算事件日；最新事件日 {latest.get('date')} 的当日涨跌幅为 {pct(latest)}。"
    )
    yahoo_text = (
        f"{overview} 其中最高值出现在 {highest.get('date')}，为 {pct(highest)}；最低值出现在 {lowest.get('date')}，为 {pct(lowest)}。\n\n"
        + "\n".join(row_lines)
    )
    modules: list[ModuleInterpretation] = []
    for run in runs:
        if run is yahoo_run:
            modules.append(ModuleInterpretation(script=run.selected.filename, text=yahoo_text))
        elif run.selected.filename in SEARCH_SCRIPTS:
            modules.append(
                ModuleInterpretation(
                    script=run.selected.filename,
                    text=f"搜索结果已用于提取和校验 {len(valid_rows)} 个事件发生日期，并传递给 Yahoo 数据模块计算事件日涨跌幅。",
                )
            )
        else:
            modules.append(ModuleInterpretation(script=run.selected.filename, text=""))
    return InterpretationResult(title=title, overview=overview, modules=tuple(modules))


def fallback_interpretation_result(question: str, runs: list[ModuleRun]) -> InterpretationResult:
    title = plain_text_excerpt(question, limit=48) or "数据图表"
    modules = tuple(
        ModuleInterpretation(script=run.selected.filename, text=fallback_module_interpretation(run, question))
        for run in runs
    )
    overview = fallback_overview_from_modules(question, modules)
    return InterpretationResult(title=title, overview=overview, modules=modules)


def normalize_importance_markdown(text: str) -> str:
    """Keep model-selected emphasis concise so highlights remain meaningful."""
    if "**" not in text:
        return text
    normalized_lines: list[str] = []
    for line in text.splitlines():
        plain_line = re.sub(r"\*\*([^*]+)\*\*", r"\1", line)
        plain_length = len(re.sub(r"\s+", "", plain_line))
        kept = 0

        def replace(match: re.Match[str]) -> str:
            nonlocal kept
            phrase = match.group(1).strip()
            phrase_length = len(re.sub(r"\s+", "", phrase))
            is_whole_line = plain_length > 20 and phrase_length >= plain_length * 0.7
            too_long = phrase_length > 64
            if not phrase or kept >= 2 or is_whole_line or too_long:
                return phrase
            kept += 1
            return f"**{phrase}**"

        normalized_lines.append(re.sub(r"\*\*([^*\n]+)\*\*", replace, line))
    return "\n".join(normalized_lines)


def normalize_numeric_prose(text: str) -> str:
    """Replace awkward chart-value dumps with reader-friendly comparisons."""
    if not text:
        return ""

    def replace_value_sequence(match: re.Match[str]) -> str:
        prefix = re.sub(r"(?:依次(?:为|是)|分别(?:为|是)|为)\s*$", "", match.group("prefix")).strip()
        prefix = re.sub(r"(?:柱体|柱子|柱状|柱值|柱高|柱)$", "", prefix).strip()
        values_raw = match.group("values")
        unit = (match.group("unit") or "").strip()
        currency = (match.group("currency") or "").strip()
        full_unit = f"{unit}{currency}".strip()
        values: list[float] = []
        for token in re.split(r"[、,，]\s*", values_raw):
            cleaned = token.strip().replace(",", "")
            if not cleaned:
                continue
            try:
                values.append(float(cleaned))
            except ValueError:
                return match.group(0)
        if len(values) < 3:
            return match.group(0)
        first = values[0]
        last = values[-1]
        high = max(values)
        low = min(values)

        def fmt(value: float) -> str:
            number = f"{value:.2f}".rstrip("0").rstrip(".")
            return f"{number} {full_unit}" if full_unit else number

        if all(values[index] <= values[index + 1] for index in range(len(values) - 1)):
            return f"{prefix}从{fmt(first)}增至{fmt(last)}"
        if all(values[index] >= values[index + 1] for index in range(len(values) - 1)):
            return f"{prefix}从{fmt(first)}降至{fmt(last)}"
        if last == high:
            return f"{prefix}从{fmt(first)}波动上行至最新高点 {fmt(last)}"
        if last == low:
            return f"{prefix}从{fmt(first)}波动下行至最新低点 {fmt(last)}"
        return f"{prefix}在{fmt(low)}至{fmt(high)}区间波动，最新为 {fmt(last)}"

    sequence_pattern = re.compile(
        r"(?P<prefix>(?:柱(?:体|子|状|值|高)?|折线|曲线|序列|数据|数值|收入|营收|净利润|利润|指标)"
        r"[^。；;，,]{0,24}?"
        r"(?:依次(?:为|是)|分别(?:为|是)|为))\s*"
        r"(?P<values>(?:[-+]?\d+(?:\.\d+)?\s*[、,，]\s*){2,}[-+]?\d+(?:\.\d+)?)\s*"
        r"(?P<unit>万亿|千亿|百亿|十亿|亿|百万|万|千)?(?P<currency>美元|港元|人民币|日元|元)?"
    )
    normalized = sequence_pattern.sub(replace_value_sequence, text)
    normalized = re.sub(r"(?:分组)?(?:柱状图|折线图|图表)(?:实际)?(?:呈现|显示)的", "", normalized)
    normalized = re.sub(r"最新(?=20\d{2})", "最新的", normalized)
    normalized = re.sub(r"(?:柱体|柱子|柱状|柱值|柱高)(?=较|比|同比|环比|仍|已|为)", "", normalized)
    normalized = re.sub(r"\s+([，。；;])", r"\1", normalized)
    return normalized


def _row_datetime_for_extrema(row: dict[str, Any]) -> dt.datetime | None:
    raw = str(row.get("time") or row.get("timestamp") or row.get("date") or "").strip()
    if not raw:
        return None
    normalized = raw.replace("Z", "+00:00")
    try:
        return dt.datetime.fromisoformat(normalized)
    except ValueError:
        for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%Y-%m-%d %H:%M"):
            try:
                return dt.datetime.strptime(raw, fmt)
            except ValueError:
                continue
    return None


def deterministic_52_week_extrema_annotation(
    question: str,
    runs: list[ModuleRun],
) -> dict[str, Any] | None:
    """Compute an exact 52-week high/low annotation from the K-line payload."""
    kind = requested_52_week_extrema_kind(question)
    if not kind:
        return None
    requested_symbol = str(infer_symbol_from_question(question) or extract_stock_code(question) or "").strip().upper()
    run = next(
        (
            item for item in runs
            if item.selected.filename == "kline.py"
            and (not requested_symbol or str(item.code or "").strip().upper() == requested_symbol)
            and item.payload_path.exists()
        ),
        None,
    )
    if run is None:
        return None
    try:
        payload = json.loads(run.payload_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict):
        return None
    dated_rows = [
        (row, row_dt)
        for row in _kline_payload_rows(payload)
        if (row_dt := _row_datetime_for_extrema(row)) is not None
    ]
    if not dated_rows:
        return None
    latest_dt = max(row_dt for _row, row_dt in dated_rows)
    cutoff = latest_dt - dt.timedelta(days=366)
    dated_rows = [(row, row_dt) for row, row_dt in dated_rows if cutoff <= row_dt <= latest_dt]
    field = "high" if kind == "high" else "low"
    candidates: list[tuple[dict[str, Any], dt.datetime, float]] = []
    for row, row_dt in dated_rows:
        try:
            price = float(row.get(field))
        except (TypeError, ValueError):
            continue
        if math.isfinite(price) and price > 0:
            candidates.append((row, row_dt, price))
    if not candidates:
        return None
    selected_row, selected_dt, price = (max(candidates, key=lambda item: item[2]) if kind == "high" else min(candidates, key=lambda item: item[2]))
    raw_time = str(selected_row.get("time") or selected_row.get("timestamp") or selected_row.get("date") or "").strip()
    point_time = raw_time or selected_dt.strftime("%Y-%m-%d")
    label = f"52周{'最高' if kind == 'high' else '最低'}价 {price:g}"
    annotation_type = requested_text_draw_tool(question) or "text"
    return {
        "symbol": str(run.code or requested_symbol).strip().upper(),
        "type": annotation_type,
        "price": price,
        "time": point_time,
        "text": label,
        "color": "#ef4444" if kind == "high" else "#16a34a",
        "source": "computed-kline-52w",
    }


def normalize_model_chart_annotations(raw_items: Any, question: str, runs: list[ModuleRun]) -> tuple[dict[str, Any], ...]:
    """Keep the legacy report response shape while delegating validation to JEV."""
    if not wants_model_derived_chart_annotation(question):
        return ()
    exact = deterministic_52_week_extrema_annotation(question, runs)
    proposals = [exact] if exact else raw_items
    marks = []
    for run in runs:
        if run.selected.filename != "kline.py" or not run.payload_path.exists():
            continue
        context = _jev_kline_context(run)
        if context.get("ohlcv"):
            normalized = normalize_kline_annotations(proposals, requested_type="" if proposals else requested_native_kline_annotation_type(question), max_marks=None, **context)
            marks.extend(_legacy_kline_mark({**mark, "source": "jev-kline-policy"}) for mark in normalized)
    return tuple(marks)


def parse_interpretation_result(raw: str, runs: list[ModuleRun], question: str) -> InterpretationResult:
    parsed = parse_json_object(raw)
    if not parsed:
        raise HTTPException(status_code=500, detail=f"模型解读返回无法解析为 JSON：{raw}")

    title = str(parsed.get("title") or "").strip()
    if not title:
        raise HTTPException(status_code=500, detail="模型解读缺少报告标题：title")
    overview = normalize_importance_markdown(
        normalize_numeric_prose(
            clean_advisor_view_prefixes(str(parsed.get("overview") or "").strip())
        )
    )
    raw_modules = parsed.get("modules")
    modules_by_script: dict[str, list[str]] = {}
    if isinstance(raw_modules, list):
        for item in raw_modules:
            if not isinstance(item, dict):
                continue
            script = str(item.get("script") or "").strip()
            text = normalize_importance_markdown(
                normalize_numeric_prose(
                    clean_advisor_view_prefixes(str(item.get("text") or item.get("interpretation") or "").strip())
                )
            )
            if script and text:
                modules_by_script.setdefault(script, []).append(text)

    module_items: list[ModuleInterpretation] = []
    for index, run in enumerate(runs):
        script_texts = modules_by_script.get(run.selected.filename) or []
        text = script_texts.pop(0) if script_texts else ""
        if not text and isinstance(raw_modules, list) and index < len(raw_modules) and isinstance(raw_modules[index], dict):
            text = normalize_importance_markdown(
                normalize_numeric_prose(
                    clean_advisor_view_prefixes(
                        str(raw_modules[index].get("text") or raw_modules[index].get("interpretation") or "").strip()
                    )
                )
            )
        module_items.append(ModuleInterpretation(script=run.selected.filename, text=text))
    chart_annotations = normalize_model_chart_annotations(parsed.get("chart_annotations"), question, runs)
    return strengthen_integrated_overview_from_modules(
        InterpretationResult(
            title=title,
            overview=overview,
            modules=tuple(module_items),
            chart_annotations=chart_annotations,
        )
    )


def interpretation_overview_too_weak(question: str, result: InterpretationResult) -> bool:
    overview = re.sub(r"\s+", " ", clean_advisor_view_prefixes(result.overview)).strip()
    if not overview:
        return True
    html_lang = html_lang_for_question(question)
    weak_terms = (
        "本模组",
        "本模組",
        "本模块",
        "本模塊",
        "基础框架",
        "基礎框架",
        "提供基础",
        "提供基礎",
        "相关资讯",
        "相關資訊",
        "资料汇总",
        "資料彙總",
        "this module",
        "this framework",
        "provides a foundation",
        "source digest",
        "搜索到",
        "检索到",
        "搜尋到",
        "搜索结果",
        "返回结果",
        "相关视频",
        "相關影片",
        "无有效",
        "無有效",
        "没有有效",
        "沒有有效",
        "未获取到有效",
        "未獲取到有效",
        "暂不补充",
        "暫不補充",
        "无法补充",
        "無法補充",
        "没有更多数据",
        "沒有更多資料",
        "search returned",
        "search results",
        "relevant video",
        "no useful video",
        "no valid video",
        "cannot supplement",
    )
    if any(term.lower() in overview.lower() for term in weak_terms):
        return True
    if html_lang in {"zh-CN", "zh-Hant", "ja", "ko"}:
        compact_len = len(re.sub(r"\s+", "", overview))
        return compact_len < 220
    word_count = len(re.findall(r"\b\w+\b", overview))
    return word_count < 90


def interpretation_modules_too_weak(question: str, result: InterpretationResult, runs: list[ModuleRun]) -> bool:
    html_lang = html_lang_for_question(question)
    for index, run in enumerate(runs):
        if not should_validate_business_module_text(run):
            continue
        text = ""
        if index < len(result.modules):
            text = clean_advisor_view_prefixes(result.modules[index].text)
        if business_module_text_too_weak(text, html_lang):
            return True
    return False


def should_validate_business_module_text(run: ModuleRun) -> bool:
    script = run.selected.filename
    if script in SEARCH_SCRIPTS or script in TEXT_ONLY_SCRIPTS or script in GENERIC_CHART_PAYLOAD_SCRIPTS:
        return False
    if script in NON_VISUAL_CHART_RECALL_SCRIPTS:
        return False
    return script in EXPLICIT_BUSINESS_ROUTE_SCRIPTS


def business_module_text_too_weak(text: str, html_lang: str) -> bool:
    cleaned = re.sub(r"\s+", " ", clean_advisor_view_prefixes(text)).strip()
    if not cleaned:
        return True
    normalized = cleaned.lower()
    if module_note_is_process_filler(cleaned) or module_note_is_meta_filler(cleaned):
        return True
    generic_terms = (
        "这项数据应作为",
        "這項資料應作為",
        "投资上重点看",
        "投資上重點看",
        "吸引力有限",
        "吸引力不足",
        "空间有限",
        "空間有限",
        "缺乏动力",
        "缺乏動力",
        "值得关注",
        "值得關注",
        "需要关注",
        "需要關注",
        "需重点跟踪",
        "需重點跟蹤",
        "as a signal to monitor",
        "worth monitoring",
    )
    has_number = bool(re.search(r"[-+]?\d+(?:\.\d+)?\s*(?:%|亿美元|億美元|美元|B|M|T|x|倍)?", cleaned, flags=re.I))
    has_period = bool(
        re.search(
            r"(?:20\d{2}[年/-]\d{1,2}(?:[月/-]\d{1,2}日?)?|20\d{2}年|20\d{2}|Q[1-4]['’]?\d{2}|Q[1-4]|FY|H1|9M|最新|最新期|latest|right edge)",
            cleaned,
            flags=re.I,
        )
    )
    unsupported_generic = any(term.lower() in normalized for term in generic_terms) and not (has_number and has_period)
    if unsupported_generic:
        return True
    if html_lang in {"zh-CN", "zh-Hant", "ja", "ko"}:
        compact_len = len(re.sub(r"\s+", "", cleaned))
        return compact_len < 120 or not has_number or not has_period
    word_count = len(re.findall(r"\b\w+\b", cleaned))
    return word_count < 55 or not has_number or not has_period


def strengthen_integrated_overview_from_modules(result: InterpretationResult) -> InterpretationResult:
    overview = clean_advisor_view_prefixes(result.overview).strip()
    if not overview:
        module_texts = [
            clean_advisor_view_prefixes(item.text).strip()
            for item in result.modules
            if clean_advisor_view_prefixes(item.text).strip()
        ]
        overview = "\n\n".join(module_texts[:4])
    return InterpretationResult(
        title=result.title,
        overview=overview,
        modules=result.modules,
        chart_annotations=result.chart_annotations,
    )


def format_compact_amount(value: float, unit: str) -> str:
    amount = abs(value)
    sign = "-" if value < 0 else ""
    if amount >= 100_000_000:
        scaled = amount / 100_000_000
        suffix = f"亿{unit}"
    elif amount >= 10_000:
        scaled = amount / 10_000
        suffix = f"万{unit}"
    else:
        return f"{value:g}{unit}"
    text = f"{scaled:.2f}".rstrip("0").rstrip(".")
    return f"{sign}{text}{suffix}"


def compact_currency_amounts_in_text(text: str) -> str:
    if not text:
        return ""

    def replace(match: re.Match[str]) -> str:
        raw_number = match.group("number")
        unit = match.group("unit")
        try:
            numeric = float(raw_number.replace(",", ""))
        except ValueError:
            return match.group(0)
        if abs(numeric) < 10_000:
            return match.group(0)
        return format_compact_amount(numeric, unit)

    return re.sub(
        r"(?<![\d.])(?P<number>[-+]?\d{1,3}(?:,\d{3})+(?:\.\d+)?|[-+]?\d{5,}(?:\.\d+)?)(?P<unit>人民币|港元|美元|日元|元)",
        replace,
        text,
    )


def clean_advisor_view_prefixes(text: str) -> str:
    if not text:
        return ""
    patterns = (
        r"我的核心觀點是[：:,，]?\s*",
        r"我的核心观点是[：:,，]?\s*",
        r"核心觀點是[：:,，]?\s*",
        r"核心观点是[：:,，]?\s*",
        r"我的直接判斷是[：:,，]?\s*",
        r"我的直接判断是[：:,，]?\s*",
        r"我的判斷是[：:,，]?\s*",
        r"我的判断是[：:,，]?\s*",
        r"我的觀點是[：:,，]?\s*",
        r"我的观点是[：:,，]?\s*",
        r"我的看法是[：:,，]?\s*",
        r"my core view is[:,]?\s*",
        r"my direct read is[:,]?\s*",
        r"my view is[:,]?\s*",
        r"my read is[:,]?\s*",
        r"the core view is[:,]?\s*",
    )
    cleaned = str(text)
    for pattern in patterns:
        cleaned = re.sub(pattern, "", cleaned, flags=re.I)
    cleaned = re.sub(r"(^|\n)(\s*)(核心觀點|核心观点|直接判斷|直接判断)[：:,，]\s*", r"\1\2", cleaned, flags=re.I)
    cleaned = re.sub(
        r"（?\(?\s*(?:注|备注|備註|Note)\s*[：:]\s*[^。.!?\n]*(?:原数据|原資料|source data|补充|補充|logically supplemented|缺少|未提供)[^。.!?\n]*[。.!?]?\s*）?\)?",
        "",
        cleaned,
        flags=re.I,
    )
    cleaned = re.sub(r"(当前|目前)?采用[^，。；;]*视图[，,]?", "", cleaned)
    cleaned = re.sub(r"(当前|目前)?使用[^，。；;]*(?:图|图表|视图)[，,]?", "", cleaned)
    cleaned = re.sub(r"从图形趋势看[，,]?", "", cleaned)
    cleaned = re.sub(r"从图表看[，,]?", "", cleaned)
    cleaned = re.sub(
        r"（?\(?\s*因(?:原数据|原資料)[^。.!?\n]*(?:未提供|缺少)[^。.!?\n]*(?:暂按|暫按|补充|補充)[^。.!?\n]*[。.!?]?\s*）?\)?",
        "",
        cleaned,
        flags=re.I,
    )
    cleaned = re.sub(
        r"(?:最新依据是|最新依據是|具体依据是|具體依據是|supporting facts are)\s*[：:]\s*[：:]?\s*type\s*=\s*[^。.!?\n]*(?:props|gridCount|height|unit)[^。.!?\n]*?(?=\s*(?:投资上|投資上|For an investor|$))",
        "",
        cleaned,
        flags=re.I,
    )
    cleaned = re.sub(
        r"\btype\s*=\s*[^。.!?\n]*(?:props|gridCount|height|unit)[^。.!?\n]*?(?=\s*(?:投资上|投資上|For an investor|$))",
        "",
        cleaned,
        flags=re.I,
    )
    cleaned = re.sub(r"\s+([。！？!?])", r"\1", cleaned)
    cleaned = re.sub(r"([。！？])\s+([\u4e00-\u9fff])", r"\1\2", cleaned)
    cleaned = compact_currency_amounts_in_text(cleaned)
    return cleaned.strip()


def fallback_module_interpretation(run: ModuleRun, question: str) -> str:
    payload = read_payload(run.payload_path)
    if not payload:
        return ""
    html_lang = html_lang_for_question(question)

    chart_note = fallback_chart_payload_interpretation(payload, question, html_lang)
    if chart_note:
        return chart_note

    rich_note = rich_business_module_advisor_note(run, question)
    if rich_note:
        return rich_note

    facts = extract_payload_facts(run.payload_path)
    if not facts:
        return ""
    if run.selected.filename in SEARCH_SCRIPTS or run.selected.filename == "mind_map.py":
        note = "；".join(fact.rstrip("。.") for fact in facts[:4])
        if html_lang == "en":
            return plain_text_excerpt("Key takeaways: " + " ".join(facts[:4]), limit=520)
        return plain_text_excerpt(f"整理要点：{note}。", limit=420)
    if html_lang == "en":
        return plain_text_excerpt("The latest available data shows: " + " ".join(facts[:3]), limit=520)
    note = "；".join(fact.rstrip("。.") for fact in facts[:3])
    return plain_text_excerpt(f"最新可用数据：{note}。", limit=360)


def fallback_overview_from_modules(question: str, modules: tuple[ModuleInterpretation, ...]) -> str:
    notes = [clean_advisor_view_prefixes(item.text).strip() for item in modules if item.text.strip()]
    if not notes:
        return ""
    html_lang = html_lang_for_question(question)
    first_note = next(
        (
            note
            for note in notes
            if any(term in note for term in ("共同财年", "共同財年", "可比窗口", "可比視窗", "净利润", "淨利潤"))
            and "Latest/rightmost" not in note
        ),
        notes[0],
    )
    sentences = split_overview_sentences(first_note, html_lang)
    if html_lang == "en":
        if sentences:
            return " ".join(sentences[:2])
        return plain_text_excerpt(first_note, limit=320)
    if sentences:
        return "".join(sentences[:2])
    return plain_text_excerpt(first_note, limit=260)


def fallback_chart_payload_interpretation(payload: dict[str, Any], question: str, html_lang: str) -> str:
    chart_payload = payload.get("chartPayload") if isinstance(payload.get("chartPayload"), dict) else payload
    if not isinstance(chart_payload, dict):
        return ""
    chart_type = str(chart_payload.get("type") or chart_payload.get("chartType") or "").lower()
    if chart_type in {"grouped-bar", "grouped_bar", "grouped column", "grouped-column"}:
        rows = chart_payload.get("data") if isinstance(chart_payload.get("data"), list) else chart_payload.get("rows")
        rows = [row for row in rows or [] if isinstance(row, dict)]
        series = [item for item in chart_payload.get("series", []) if isinstance(item, dict)]
        if not rows or len(series) < 2:
            return ""
        x_field = str(chart_payload.get("xField") or "").strip()
        if not x_field:
            x_field = next((key for key in ("period", "fiscal_year", "date", "year", "label") if key in rows[0]), "")
        if not x_field:
            return ""
        latest = rows[-1]
        previous = rows[-2] if len(rows) >= 2 else None
        latest_label = str(latest.get(x_field) or latest.get("period") or latest.get("date") or latest.get("year") or "最新期")
        start_label = str(rows[0].get(x_field) or rows[0].get("period") or rows[0].get("date") or rows[0].get("year") or "")
        axis = chart_payload.get("axis") if isinstance(chart_payload.get("axis"), dict) else {}
        unit = re.sub(r"^.*?（(.+?)）.*$", r"\1", str(axis.get("label") or "")).strip()
        if unit == str(axis.get("label") or "").strip():
            unit = ""

        latest_values: list[tuple[str, str, float, dict[str, Any]]] = []
        for item in series:
            field = str(item.get("field") or "").strip()
            label = str(item.get("label") or item.get("name") or field).strip()
            value = to_float(latest.get(field))
            if field and value is not None:
                latest_values.append((label, field, value, item))
        if not latest_values:
            return ""
        leader = max(latest_values, key=lambda item: item[2])
        value_bits = [
            f"{label}为**{format_chart_value_for_text(value, spec)}{unit if unit and not str(format_chart_value_for_text(value, spec)).endswith(unit) else ''}**"
            for label, _, value, spec in latest_values[:4]
        ]
        comparison_bits: list[str] = []
        if isinstance(previous, dict):
            previous_label = str(previous.get(x_field) or previous.get("period") or previous.get("date") or previous.get("year") or "上一期")
            for label, field, value, _spec in latest_values[:4]:
                previous_value = to_float(previous.get(field))
                change = pct_change(previous_value, value) if previous_value is not None else None
                if change is not None:
                    comparison_bits.append(f"{label}较{previous_label}{'增长' if change >= 0 else '下降'}{abs(change):.2f}%")
        window = f"{start_label}至{latest_label}" if start_label and start_label != latest_label else latest_label
        source_note = str(chart_payload.get("sourceNote") or "").strip()
        if html_lang == "en":
            values = "; ".join(
                f"{label}: **{format_chart_value_for_text(value, spec)}{unit if unit and not str(format_chart_value_for_text(value, spec)).endswith(unit) else ''}**"
                for label, _, value, spec in latest_values[:4]
            )
            return (
                f"For the comparable window through {latest_label}, {values}. "
                f"{leader[0]} is the larger profit contributor in the latest period. "
                + ("; ".join(comparison_bits) + ". " if comparison_bits else "")
                + (source_note if source_note else "")
            ).strip()
        comparison_sentence = f"与前一可比财年相比，{'，'.join(comparison_bits)}。" if comparison_bits else ""
        source_sentence = f"{source_note}" if source_note else ""
        return (
            f"按双方都有数据的**{window}**口径，{latest_label}净利润中，"
            f"{'，'.join(value_bits)}，{leader[0]}仍是利润规模更高的一方。"
            f"{comparison_sentence}{source_sentence}"
        )
    if chart_type not in {"bar-line", "column-line", "bar_line", "combo"} and not (
        isinstance(chart_payload.get("columnSeries"), list) and isinstance(chart_payload.get("lineSeries"), list)
    ):
        return ""

    rows = chart_payload.get("data") if isinstance(chart_payload.get("data"), list) else chart_payload.get("rows")
    rows = [row for row in rows or [] if isinstance(row, dict)]
    if not rows:
        return ""
    x_field = str(chart_payload.get("xField") or chart_payload.get("dateField") or "").strip()
    if not x_field:
        x_field = next((key for key in ("period", "date", "year", "label", "time") if key in rows[0]), "")
    if not x_field:
        return ""

    column_series = [item for item in chart_payload.get("columnSeries", []) if isinstance(item, dict)]
    line_series = [item for item in chart_payload.get("lineSeries", []) if isinstance(item, dict)]
    if not column_series or not line_series:
        return ""
    column = column_series[0]
    line = line_series[0]
    column_field = str(column.get("field") or "").strip()
    line_field = str(line.get("field") or "").strip()
    if not column_field or not line_field:
        return ""

    latest = rows[-1]
    previous = rows[-2] if len(rows) >= 2 else None
    latest_label = str(latest.get(x_field) or latest.get("period") or latest.get("date") or latest.get("year") or "最新期")
    previous_label = str(previous.get(x_field) or previous.get("period") or previous.get("date") or previous.get("year") or "上一期") if previous else ""
    column_label = str(column.get("label") or column.get("name") or column_field).strip()
    line_label = str(line.get("label") or line.get("name") or line_field).strip()
    column_value = to_float(latest.get(column_field))
    line_value = to_float(latest.get(line_field))
    if column_value is None and line_value is None:
        return ""

    previous_column_value = to_float(previous.get(column_field)) if isinstance(previous, dict) else None
    previous_line_value = to_float(previous.get(line_field)) if isinstance(previous, dict) else None
    column_text = format_chart_value_for_text(column_value, column)
    line_text = format_chart_value_for_text(line_value, line)
    previous_column_text = format_chart_value_for_text(previous_column_value, column)
    previous_line_text = format_chart_value_for_text(previous_line_value, line)

    comparable_rows = [row for row in rows if to_float(row.get(column_field)) is not None]
    peak_row = max(comparable_rows, key=lambda row: to_float(row.get(column_field)) or float("-inf")) if comparable_rows else None
    peak_label = str(peak_row.get(x_field) or peak_row.get("period") or peak_row.get("date") or "") if peak_row else ""
    peak_value = to_float(peak_row.get(column_field)) if peak_row else None
    peak_text = format_chart_value_for_text(peak_value, column) if peak_row else ""

    if html_lang == "en":
        latest_bits = []
        if column_value is not None:
            latest_bits.append(f"{column_label} was **{column_text}**")
        if line_value is not None:
            latest_bits.append(f"{line_label} was **{line_text}**")
        elif any(to_float(row.get(line_field)) is None for row in rows):
            latest_bits.append(f"{line_label} was blank where the comparison base was unavailable")
        first_sentence = f"In {latest_label}, " + " and ".join(latest_bits) + "."
        comparison = ""
        if previous and previous_column_value is not None and column_value is not None:
            change = pct_change(previous_column_value, column_value)
            comparison = f" Compared with {previous_label}, {column_label} moved from {previous_column_text} to {column_text}"
            if change is not None:
                comparison += f" ({change:+.2f}%)."
            else:
                comparison += "."
        implication = fallback_chart_implication(line_value, previous_line_value, html_lang)
        return first_sentence + comparison + (" " + implication if implication else "")

    latest_bits = []
    if column_value is not None:
        latest_bits.append(f"{column_label}为**{column_text}**")
    if line_value is not None:
        latest_bits.append(f"{line_label}为**{line_text}**")
    elif any(to_float(row.get(line_field)) is None for row in rows):
        latest_bits.append(f"{line_label}因缺少可比基期而留空")
    first_sentence = f"{latest_label}，" + "，".join(latest_bits) + "。"

    comparisons: list[str] = []
    if previous and previous_column_value is not None and column_value is not None:
        change = pct_change(previous_column_value, column_value)
        if change is not None:
            comparisons.append(f"较{previous_label}的{previous_column_text}{'上升' if change >= 0 else '下降'}{abs(change):.2f}%")
        else:
            comparisons.append(f"较{previous_label}的{previous_column_text}发生变化")
    if previous and previous_line_value is not None and line_value is not None:
        comparisons.append(f"{line_label}由{previous_line_text}变为{line_text}")
    if peak_row and peak_label and peak_label != latest_label and peak_value is not None:
        comparisons.append(f"区间高点为{peak_label}的{peak_text}")
    comparison_sentence = ("与前期相比，" + "，".join(comparisons) + "。") if comparisons else ""
    implication = fallback_chart_implication(line_value, previous_line_value, html_lang)
    return first_sentence + comparison_sentence + implication


def format_chart_value_for_text(value: Any, series: dict[str, Any]) -> str:
    numeric = to_float(value)
    if numeric is None:
        return "--"
    suffix = str(series.get("suffix") or "").strip()
    digits = int(series.get("digits") or (2 if abs(numeric) < 1000 else 1))
    if suffix == "%":
        return f"{numeric:.2f}%"
    text = f"{numeric:.{digits}f}".rstrip("0").rstrip(".")
    return f"{text}{suffix}"


def fallback_chart_implication(line_value: float | None, previous_line_value: float | None, html_lang: str) -> str:
    if html_lang == "en":
        if line_value is None:
            return "For interpretation, the bar value remains usable, while the missing line point only means the prior-year comparison base is unavailable."
        if line_value < 0:
            return "For investors, the latest evidence points to a pullback in profit momentum, so the next confirmation is whether the following period can restore growth."
        if previous_line_value is not None and line_value < previous_line_value:
            return "For investors, growth is still positive but momentum has cooled, so the next period needs confirmation rather than extrapolation."
        return "For investors, the latest data still supports positive earnings momentum, with the next period serving as the key confirmation point."
    if line_value is None:
        return "解读上，柱子的绝对值仍可使用；折线留空只代表缺少上一年可比基期，不代表数据整体无效。"
    if line_value < 0:
        return "投资分析上，最新同比已转为负值，说明盈利动能从高位回落，后续需要看下一期能否重新修复增长。"
    if previous_line_value is not None and line_value < previous_line_value:
        return "投资分析上，虽然同比仍为正，但增速较前期降温，后续不宜简单外推高增长，需要继续确认利润韧性。"
    return "投资分析上，最新同比仍为正，说明盈利动能仍有支撑，下一期能否延续将是关键确认点。"


def format_interpretation_for_response(result: InterpretationResult) -> str:
    parts: list[str] = []
    if result.title.strip():
        parts.append(result.title.strip())
    if result.overview.strip():
        parts.append(result.overview.strip())
    return "\n\n".join(parts)


def build_vision_summary_context(vision_insights: tuple[VisionInsight, ...]) -> str:
    if not vision_insights:
        return "(none)"
    lines: list[str] = []
    for index, item in enumerate(vision_insights, start=1):
        lines.append(f"## Visual Insight {index}: {item.script}")
        if item.latest_visible_period:
            lines.append(f"Latest visible period from chart right edge: {item.latest_visible_period}")
        if item.latest_visible_values:
            values = "; ".join(
                f"{value.get('series') or 'series'}={value.get('value')}"
                for value in item.latest_visible_values
                if isinstance(value, dict)
            )
            if values:
                lines.append(f"Latest visible values from chart right edge: {values}")
        lines.append(item.summary.strip())
    return "\n".join(lines)[:12000]


def build_multi_module_context(runs: list[ModuleRun]) -> str:
    parts: list[str] = [
        "# Complete evidence package",
        "Use every relevant item below together. Do not summarize one module at a time.",
    ]
    ordered_runs = sorted(
        enumerate(runs),
        key=lambda item: (
            1 if item[1].selected.filename in SEARCH_SCRIPTS else 0,
            item[0],
        ),
    )
    for output_index, (_original_index, run) in enumerate(ordered_runs, start=1):
        parts.append(f"## Evidence {output_index}: {run.code} {run.selected.label} ({run.selected.filename})")
        if run.route:
            parts.append("CLI/request arguments:")
            parts.append(json.dumps(run.route, ensure_ascii=False, default=str)[:2400])
        parts.append(build_text_generation_context(run.html_path, run.payload_path if run.payload_path.exists() else None))
        payload = read_payload(run.payload_path if run.payload_path.exists() else None)
        payload_excerpt = build_payload_interpretation_excerpt(payload, run.selected.filename)
        if payload_excerpt:
            parts.append("Structured payload excerpt:")
            parts.append(payload_excerpt)
    return "\n\n".join(part for part in parts if part).strip()[:48000]


def build_payload_interpretation_excerpt(payload: dict[str, Any], script: str) -> str:
    if not payload:
        return ""
    simplified = simplify_payload_for_interpretation(payload, script)
    if not simplified:
        return ""
    try:
        text = json.dumps(simplified, ensure_ascii=False, default=str, indent=2)
    except TypeError:
        text = str(simplified)
    return text[:12000]


def simplify_payload_for_interpretation(value: Any, script: str, depth: int = 0) -> Any:
    if depth > 5:
        return plain_text_excerpt(str(value), 500)
    if isinstance(value, str):
        return plain_text_excerpt(value, 1600 if depth <= 2 else 700)
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    if isinstance(value, list):
        if depth == 0 and script in SEARCH_SCRIPTS:
            return [simplify_search_item_for_interpretation(item) for item in value[:12]]
        return [simplify_payload_for_interpretation(item, script, depth + 1) for item in value[:12]]
    if not isinstance(value, dict):
        return plain_text_excerpt(str(value), 500)

    if script in SEARCH_SCRIPTS and isinstance(value.get("articles"), list):
        keep: dict[str, Any] = {}
        for key in ("type", "query", "code", "title", "source", "category", "total", "asOf", "answer", "model"):
            if key in value:
                keep[key] = simplify_payload_for_interpretation(value.get(key), script, depth + 1)
        keep["articles"] = [simplify_search_item_for_interpretation(item) for item in value["articles"][:12]]
        return keep

    preferred_keys = (
        "type",
        "title",
        "subtitle",
        "source",
        "metric",
        "metricLabel",
        "latest",
        "summary",
        "content",
        "items",
        "rows",
        "data",
        "chartPayload",
        "events",
        "fields",
        "nodes",
        "links",
        "children",
    )
    keys = [key for key in preferred_keys if key in value]
    keys.extend(key for key in value.keys() if key not in keys)
    result: dict[str, Any] = {}
    for key in keys[:80]:
        result[str(key)] = simplify_payload_for_interpretation(value.get(key), script, depth + 1)
    return result


def simplify_search_item_for_interpretation(item: Any) -> Any:
    if not isinstance(item, dict):
        return simplify_payload_for_interpretation(item, "", 1)
    fields = (
        "title",
        "date",
        "publishedAt",
        "source",
        "site",
        "provider",
        "summary",
        "description",
        "content",
        "snippet",
        "url",
        "duration",
        "durationText",
        "videoUrl",
        "thumbnail",
    )
    result: dict[str, Any] = {}
    for field in fields:
        if field in item and item.get(field) not in (None, ""):
            limit = 1800 if field in {"summary", "description", "content", "snippet"} else 500
            result[field] = plain_text_excerpt(str(item.get(field)), limit)
    for field in ("tickers", "symbols", "tags", "category"):
        if field in item and item.get(field):
            result[field] = simplify_payload_for_interpretation(item.get(field), "", 1)
    return result or simplify_payload_for_interpretation(item, "", 1)


def plain_text_excerpt(text: str, limit: int = 180) -> str:
    cleaned = re.sub(r"\*\*(.*?)\*\*", r"\1", text or "")
    cleaned = re.sub(r"`([^`]+)`", r"\1", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if len(cleaned) <= limit:
        return cleaned
    return cleaned[: max(0, limit - 1)].rstrip() + "…"


def read_payload_value(payload_path: Path | None) -> Any:
    if not payload_path:
        return {}
    try:
        return json.loads(payload_path.read_text(encoding="utf-8", errors="ignore"))
    except (OSError, json.JSONDecodeError):
        return {}


def read_payload(payload_path: Path | None) -> dict[str, Any]:
    payload = read_payload_value(payload_path)
    return payload if isinstance(payload, dict) else {}


def payload_has_video_results(payload_path: Path | None) -> bool:
    payload = read_payload(payload_path)
    articles = payload.get("articles")
    if not isinstance(articles, list):
        return False
    for item in articles:
        if not isinstance(item, dict):
            continue
        if str(item.get("video_url") or "").strip():
            return True
    return False


def normalize_ainvest_exchange(value: str) -> str:
    exchange = re.sub(r"[^A-Z]", "", str(value or "").upper())
    if exchange in {"NMS", "NGM", "NCM", "NASDAQ", "NASDAQGS", "NASDAQGM", "NASDAQCM"}:
        return "NASDAQ"
    if exchange in {"NYQ", "NYSE"}:
        return "NYSE"
    if exchange in {"PCX", "ARCX", "ARCA", "NYSEARCA"}:
        return "ARCA"
    if exchange in {"BATS", "CBOE"}:
        return "CBOE"
    if exchange in {"ASE", "AMEX"}:
        return "AMEX"
    return exchange or "NASDAQ"


@lru_cache(maxsize=256)
def lookup_us_security_identity(code: str) -> dict[str, str]:
    symbol = str(code or "").strip().upper()
    fallback = {"code": symbol, "exchange": "NASDAQ", "asset_type": "stock", "name": symbol}
    if not symbol:
        return fallback
    try:
        import yfinance as yf  # type: ignore

        ticker = yf.Ticker(symbol)
        info = ticker.info or {}
    except Exception:
        return fallback
    quote_type = str(info.get("quoteType") or info.get("quote_type") or "").upper()
    exchange = normalize_ainvest_exchange(str(info.get("exchange") or info.get("fullExchangeName") or ""))
    asset_type = "etf" if "ETF" in quote_type or "FUND" in quote_type else "stock"
    name = str(info.get("shortName") or info.get("longName") or symbol).strip() or symbol
    return {"code": symbol, "exchange": exchange, "asset_type": asset_type, "name": name}


@lru_cache(maxsize=256)
def lookup_crypto_identity(code: str, query: str = "") -> dict[str, str]:
    resolved = resolve_crypto_symbol_by_name(code, query) or str(code or "").strip().upper()
    cleaned_query = clean_crypto_name_query(query)
    search_queries = [cleaned_query, str(code or "").strip(), resolved]
    name = resolved
    try:
        for item in search_queries:
            if not item:
                continue
            response = requests.get(
                "https://api.coingecko.com/api/v3/search",
                params={"query": item},
                timeout=8,
            )
            response.raise_for_status()
            payload = response.json()
            coins = payload.get("coins")
            if not isinstance(coins, list):
                continue
            for coin in coins[:8]:
                if not isinstance(coin, dict):
                    continue
                symbol = str(coin.get("symbol") or "").strip().upper()
                coin_name = str(coin.get("name") or "").strip()
                if symbol == resolved and coin_name:
                    name = coin_name
                    raise StopIteration
            if coins:
                first = coins[0]
                if isinstance(first, dict):
                    name = str(first.get("name") or name).strip() or name
                    candidate_symbol = str(first.get("symbol") or "").strip().upper()
                    if re.fullmatch(r"[A-Z0-9]{2,18}", candidate_symbol):
                        resolved = candidate_symbol
    except StopIteration:
        pass
    except Exception:
        pass
    pair = resolved if re.search(r"(USDT|USDC|USD|BTC|ETH)$", resolved) else f"{resolved}USDT"
    return {"code": resolved, "pair": pair, "exchange": "BINANCE", "name": name}


def detect_run_asset_type(run: ModuleRun, question: str) -> str:
    payload = read_payload(run.payload_path)
    script = run.selected.filename
    source = str(payload.get("source") or "").lower()
    symbol = str(payload.get("symbol") or run.code or "").upper()
    if script in {"kline.py", "seasonals.py"}:
        if source in {"binance", "bybit", "coinbase", "kraken"}:
            return "crypto"
        if re.search(r"(USDT|USDC|USD|BTC|ETH)$", symbol):
            return "crypto"
        if clean_crypto_name_query(question) and lookup_crypto_identity(symbol, question).get("code") == symbol:
            return "crypto"
    if script in {"trade_flow.py", "volume_profile.py", "key_stats.py", "seasonals.py", "kline.py"}:
        identity = lookup_us_security_identity(run.code)
        if identity.get("asset_type") == "etf":
            return "etf"
    return "stock"


def ainvest_base_url(run: ModuleRun, question: str) -> str | None:
    script = run.selected.filename
    asset_type = detect_run_asset_type(run, question)
    if asset_type == "crypto":
        identity = lookup_crypto_identity(run.code, question)
        path_name = quote(identity.get("name") or identity.get("code") or run.code)
        pair = identity.get("pair") or f"{identity.get('code', run.code)}USDT"
        exchange = identity.get("exchange") or "BINANCE"
        return (
            f"https://crypto.ainvest.com/{path_name}/"
            f"?exchange={quote(exchange)}&pairs={quote(pair)}&symbol={quote(pair)}"
        )

    identity = lookup_us_security_identity(run.code)
    exchange = identity.get("exchange") or "NASDAQ"
    code = identity.get("code") or run.code
    if asset_type == "etf":
        base = f"https://www.ainvest.com/etfs/{exchange}-{code}/"
    else:
        base = f"https://www.ainvest.com/stocks/{exchange}-{code}/"

    if script in {"income_statement.py", "balance_sheet.py", "cash_flow.py", "key_financial_indicators.py", "revenue_expenses.py", "eps_estimate.py", "revenue_estimate.py", "revenue_sources.py", "revenue_geography.py", "payout_ratio.py", "dividend_yield.py"}:
        return base + "financials/"
    if script == "price_target_vs_actual.py":
        return base + "financials/earnings/"
    if script in {"valuation.py", "investment_rating.py", "fundamental_investment_rating.py"}:
        return base + "analysis/"
    if script in {"wall_street_consensus.py", "average_rating_history.py", "analyst_recommendations.py"}:
        return f"https://h5.ainvest.com/frontPage/s/website-f10-opc/web/company/index.html?#/wall-street-analysts?market=185&code={quote(code)}"
    return base


def build_source_reference(run: ModuleRun, question: str, module_text: str, html_lang: str) -> SourceReference | None:
    references = build_source_references(run, question, module_text, html_lang)
    return references[0] if references else None


def build_source_references(run: ModuleRun, question: str, module_text: str, html_lang: str) -> list[SourceReference]:
    if run.selected.filename in SEARCH_SCRIPTS:
        return build_news_source_references(run, question, html_lang)
    return build_data_source_references(run, question, html_lang)


def build_data_source_references(run: ModuleRun, question: str, html_lang: str) -> list[SourceReference]:
    if is_empty_placeholder_chart_run(run):
        return []
    module_label = localize_chart_label(run.selected.label, html_lang)
    summary = build_source_data_summary(run, question, html_lang)
    script = run.selected.filename
    code = str(run.code or "").strip()

    if script == "yahoo_data.py":
        symbol = first_symbol_for_source_url(code, run.payload_path)
        url = f"https://finance.yahoo.com/quote/{quote(symbol)}" if symbol else "https://finance.yahoo.com/"
        return [
            SourceReference(
                site_name="Yahoo Finance",
                url=url,
                title=f"{symbol or code or 'Market'} {module_label}",
                summary=summary,
                module_label=module_label,
                icon_url=favicon_url_for_source("Yahoo Finance", url),
            )
        ]

    if script in {"code_interpreter.py", *GENERIC_CHART_PAYLOAD_SCRIPTS}:
        return []

    source_url = ainvest_base_url(run, question)
    if not source_url:
        return []
    return [
        SourceReference(
            site_name=module_label,
            url=source_url,
            title=f"{code or 'Market'} {module_label}",
            summary=summary,
            module_label=module_label,
            icon_url=favicon_url_for_source("AInvest", source_url),
        )
    ]


def first_symbol_for_source_url(code: str, payload_path: Path) -> str:
    payload = read_payload(payload_path)
    symbols = payload.get("symbols")
    if isinstance(symbols, list):
        for symbol in symbols:
            value = str(symbol or "").strip().upper()
            if value:
                return value
    symbol = str(payload.get("symbol") or payload.get("code") or code or "").strip().upper()
    if "," in symbol:
        symbol = symbol.split(",", 1)[0].strip()
    return symbol


