def collect_overview_source_groups(runs: list[ModuleRun], question: str, html_lang: str) -> list[tuple[ModuleRun, list[SourceReference]]]:
    return []


def overview_html_with_inline_sources(overview: str, runs: list[ModuleRun], question: str, html_lang: str) -> str:
    return "\n".join(overview_html_blocks_with_inline_sources(overview, runs, question, html_lang))


def overview_html_blocks_with_inline_sources(overview: str, runs: list[ModuleRun], question: str, html_lang: str) -> list[str]:
    groups = collect_overview_source_groups(runs, question, html_lang)
    if not groups:
        return [paragraphs_html(part) for part in overview_paragraphs_for_display(overview, html_lang)]
    paragraphs = overview_paragraphs_for_display(overview, html_lang)
    if not paragraphs:
        return []
    source_target_indexes: dict[str, int | None] = {}
    for run, _references in groups:
        if run.selected.filename == VIDEO_SEARCH_SCRIPT:
            source_target_indexes[run.selected.filename] = assign_component_paragraph_index(run.selected.filename, paragraphs)
    used_scripts: set[str] = set()
    blocks: list[str] = []
    for index, paragraph in enumerate(paragraphs):
        paragraph_html = paragraphs_html(paragraph)
        source_html = source_html_for_overview_paragraph(paragraph, groups, used_scripts, index, source_target_indexes)
        blocks.append(append_inline_source_to_paragraphs(paragraph_html, source_html))
    return blocks


def report_conclusion_heading(html_lang: str) -> str:
    if html_lang == "zh-Hant":
        return "結論總結"
    if html_lang == "en":
        return "Conclusion"
    if html_lang == "ja":
        return "結論"
    if html_lang == "ko":
        return "결론"
    if html_lang == "th":
        return "บทสรุป"
    if html_lang == "es":
        return "Conclusión"
    if html_lang == "fr":
        return "Conclusion"
    if html_lang == "de":
        return "Fazit"
    if html_lang == "pt":
        return "Conclusão"
    return "结论总结"


def overview_paragraphs_for_display(overview: str, html_lang: str) -> list[str]:
    cleaned = re.sub(r"\n{3,}", "\n\n", str(overview or "").strip())
    paragraphs = [part.strip() for part in re.split(r"\n{2,}", cleaned) if part.strip()]
    if len(paragraphs) >= 2:
        return paragraphs
    one_line = re.sub(r"\s+", " ", cleaned).strip()
    if not one_line:
        return []
    compact_len = len(re.sub(r"\s+", "", one_line))
    if compact_len < 420:
        return [one_line]
    sentences = split_overview_sentences(one_line, html_lang)
    if len(sentences) < 4:
        return [one_line]
    target_count = 4 if len(sentences) >= 7 else 3
    if compact_len >= 900 and len(sentences) >= 9:
        target_count = 5
    return distribute_sentences_into_paragraphs(sentences, target_count)


def split_overview_sentences(text: str, html_lang: str) -> list[str]:
    if html_lang in {"zh-CN", "zh-Hant", "ja", "ko"}:
        parts = re.findall(r".+?[。！？；;](?=\s|$|[\u4e00-\u9fffA-Za-z0-9])|.+$", text)
    else:
        parts = re.findall(r".+?[.!?;](?=\s|$)|.+$", text)
    return [re.sub(r"\s+", " ", part).strip() for part in parts if part and part.strip()]


def distribute_sentences_into_paragraphs(sentences: list[str], target_count: int) -> list[str]:
    target_count = max(2, min(target_count, len(sentences)))
    total_chars = sum(len(sentence) for sentence in sentences)
    target_chars = max(1, total_chars // target_count)
    paragraphs: list[str] = []
    current: list[str] = []
    current_chars = 0
    for index, sentence in enumerate(sentences):
        current.append(sentence)
        current_chars += len(sentence)
        remaining_sentences = len(sentences) - index - 1
        remaining_slots = target_count - len(paragraphs) - 1
        should_break = current_chars >= target_chars and remaining_slots > 0 and remaining_sentences >= remaining_slots
        if should_break:
            paragraphs.append(" ".join(current).strip())
            current = []
            current_chars = 0
    if current:
        paragraphs.append(" ".join(current).strip())
    return [paragraph for paragraph in paragraphs if paragraph]


def assign_component_paragraph_index(script: str, paragraphs: list[str]) -> int | None:
    if not paragraphs:
        return None
    normalized = [paragraph.lower() for paragraph in paragraphs]
    if script == "mind_map.py":
        return 0
    if script == "key_stats.py":
        index = first_matching_paragraph_index(
            normalized,
            (
                "当前", "當前", "最新", "价格", "價格", "估值", "市值", "波动", "波動", "区间", "區間",
                "关注", "關注", "值得", "pe", "p/e", "beta", "market cap", "52 wk", "52周", "turnover",
            ),
        )
        return index if index is not None else min(1, len(paragraphs) - 1)
    if script == "trade_flow.py":
        index = first_matching_paragraph_index(
            normalized,
            (
                "资金", "資金", "净流", "淨流", "流入", "流出", "订单", "訂單", "大单", "大單",
                "小单", "小單", "机构", "機構", "博弈", "承接", "flow", "inflow", "outflow", "liquidity",
            ),
        )
        return index if index is not None else min(1, len(paragraphs) - 1)
    if script == "revenue_expenses.py":
        index = first_matching_paragraph_index(
            normalized,
            (
                "收入", "费用", "費用", "营收", "營收", "毛利", "营业利润", "營業利潤", "净利润",
                "淨利潤", "数据中心", "資料中心", "研发", "研發", "基本面", "业绩", "業績", "revenue",
                "expense", "gross", "operating income", "net income",
            ),
        )
        return index if index is not None else len(paragraphs) - 1
    if script == "income_statement.py":
        index = first_matching_paragraph_index(
            normalized,
            ("利润表", "利潤表", "净收入", "淨收入", "净利润", "淨利潤", "eps", "营收", "營收", "业绩", "業績"),
        )
        return index if index is not None else len(paragraphs) - 1
    if script in {"kline.py", "volume_profile.py"}:
        index = first_matching_paragraph_index(
            normalized,
            (
                "技术", "技術", "k线", "k線", "价格", "價格", "走势", "走勢", "短期", "支撑", "阻力",
                "成交", "量能", "资金", "資金", "换手", "換手", "订单流", "訂單流", "macd", "volume",
                "turnover", "support", "resistance", "technical", "flow", "liquidity",
            ),
        )
        return index if index is not None else min(1, len(paragraphs) - 1)
    if script == VIDEO_SEARCH_SCRIPT:
        index = last_matching_paragraph_index(
            normalized,
            (
                "视频", "影片", "影像", "相关视频", "相關影片", "直接关联", "直接關聯",
                "额外支撑", "額外支撐", "额外支持", "額外支持", "观点", "觀點", "访谈", "訪談",
                "黄仁勋", "黃仁勳", "jensen", "ceo", "皮查伊", "pichai", "youtube", "video", "videos",
            ),
        )
        return index if index is not None else len(paragraphs) - 1
    if script in SEARCH_SCRIPTS:
        return None
    index = first_matching_paragraph_index(
        normalized,
        ("财务", "財務", "估值", "盈利", "业绩", "業績", "评级", "評級", "分析师", "分析師", "valuation", "earnings", "analyst"),
    )
    return index if index is not None else len(paragraphs) - 1


def should_anchor_component_to_preferred(script: str) -> bool:
    return script in {"kline.py", "key_stats.py", "trade_flow.py", "revenue_expenses.py", "income_statement.py", VIDEO_SEARCH_SCRIPT}


def should_show_module_interpretation_with_overview(run: ModuleRun) -> bool:
    if run.selected.filename not in SEARCH_SCRIPTS:
        return True
    if run.selected.filename == VIDEO_SEARCH_SCRIPT and payload_has_video_results(run.payload_path):
        return True
    return False


def balanced_component_paragraph_index(
    preferred_index: int | None,
    paragraph_count: int,
    modules_by_paragraph: dict[int, list[str]],
    module_order: int,
) -> int | None:
    if paragraph_count <= 0:
        return None
    if preferred_index is None:
        preferred_index = module_order % paragraph_count
    preferred_index = max(0, min(preferred_index, paragraph_count - 1))
    candidates = sorted(
        range(paragraph_count),
        key=lambda index: (
            len(modules_by_paragraph.get(index, [])),
            abs(index - preferred_index),
            0 if index >= preferred_index else 1,
            index,
        ),
    )
    return candidates[0] if candidates else preferred_index


def first_matching_paragraph_index(paragraphs: list[str], terms: tuple[str, ...]) -> int | None:
    for index, paragraph in enumerate(paragraphs):
        if any(term in paragraph for term in terms):
            return index
    return None


def last_matching_paragraph_index(paragraphs: list[str], terms: tuple[str, ...]) -> int | None:
    for index in range(len(paragraphs) - 1, -1, -1):
        paragraph = paragraphs[index]
        if any(term in paragraph for term in terms):
            return index
    return None


def source_html_for_overview_paragraph(
    paragraph: str,
    groups: list[tuple[ModuleRun, list[SourceReference]]],
    used_scripts: set[str],
    index: int,
    source_target_indexes: dict[str, int | None] | None = None,
) -> str:
    source_target_indexes = source_target_indexes or {}
    scored: list[tuple[int, int, ModuleRun, list[SourceReference]]] = []
    for group_index, (run, references) in enumerate(groups):
        forced_index = source_target_indexes.get(run.selected.filename)
        if forced_index is not None and index != forced_index:
            continue
        text_blob = " ".join(
            [run.selected.label, run.selected.filename]
            + [ref.site_name + " " + ref.title + " " + ref.summary for ref in references[:4]]
        )
        score = source_relevance_score(paragraph, text_blob)
        if forced_index is not None and index == forced_index:
            score += 8
        if run.selected.filename not in used_scripts:
            score += 2
        scored.append((score, -group_index, run, references))
    scored.sort(reverse=True, key=lambda item: (item[0], item[1]))
    selected: list[tuple[ModuleRun, list[SourceReference]]] = []
    for score, _order, run, references in scored:
        if score <= 0 and selected:
            continue
        if score <= 0 and index > 0 and run.selected.filename in used_scripts:
            continue
        selected.append((run, references))
        used_scripts.add(run.selected.filename)
        if len(selected) >= 2:
            break
    if not selected and groups:
        run, references = groups[min(index, len(groups) - 1)]
        selected.append((run, references))
        used_scripts.add(run.selected.filename)
    return "".join(source_references_chip_html(references) for _run, references in selected)


def source_relevance_score(paragraph: str, source_text: str) -> int:
    para = re.sub(r"\s+", " ", paragraph or "").lower()
    source = re.sub(r"\s+", " ", source_text or "").lower()
    if not para or not source:
        return 0
    score = 0
    for token in re.findall(r"[a-zA-Z][a-zA-Z0-9.$-]{2,}", source):
        if token in para:
            score += 2
    for token in re.findall(r"[\u4e00-\u9fff]{2,8}", source):
        if token in para:
            score += 3
    return score


def build_news_source_references(run: ModuleRun, question: str, html_lang: str) -> list[SourceReference]:
    payload = read_payload(run.payload_path)
    articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
    module_label = localize_chart_label(run.selected.label, html_lang)
    references: list[SourceReference] = []
    for item in articles[:8]:
        if not isinstance(item, dict):
            continue
        url = str(item.get("url") or "").strip()
        title = str(item.get("title") or "").strip()
        if not url or not title:
            continue
        date = str(item.get("published_date") or str(item.get("published_at") or "")[:10]).strip()
        summary = str(item.get("summary") or item.get("content_text") or "").strip()
        if summary.startswith("%PDF") or "\x00" in summary:
            summary = ""
        if date:
            summary = f"{date} · {summary}" if summary else date
        site_name = display_source_name_for_article(payload, item, html_lang)
        references.append(
            SourceReference(
                site_name=site_name,
                url=url,
                title=title,
                summary=plain_text_excerpt(summary, limit=170),
                module_label=module_label,
                icon_url=favicon_url_for_source(site_name, url),
            )
        )
    if references:
        return references
    payload_type = str(payload.get("type") or "").strip()
    if payload_type == "ainvest-video-search" or run.selected.filename == VIDEO_SEARCH_SCRIPT:
        return []
    if payload_type == "external-info-search" or run.selected.filename == EXTERNAL_INFO_SEARCH_SCRIPT:
        is_kimi_like = is_kimi_external_payload(payload)
        fallback_url = "https://platform.kimi.com/docs/guide/use-web-search" if is_kimi_like else "https://www.google.com/"
        return [
            SourceReference(
                site_name=localized_kimi_search_label(html_lang) if is_kimi_like else "External Web",
                url=fallback_url,
                title="Kimi Web Search" if is_kimi_like else "External Info Search",
                summary="No matching external page links were returned for this search.",
                module_label=module_label,
                icon_url=favicon_url_for_source("Kimi" if is_kimi_like else "External Web", fallback_url),
            )
        ]
    return [
        SourceReference(
            site_name="AInvest",
            url="https://www.ainvest.com/news/",
            title="AInvest News Search",
            summary="No matching article links were returned for this search.",
            module_label=module_label,
            icon_url=favicon_url_for_source("AInvest", "https://www.ainvest.com/news/"),
        )
    ]


def generic_chart_source_summary(payload: dict[str, Any], run: ModuleRun, html_lang: str) -> str:
    props = payload.get("props") if isinstance(payload.get("props"), dict) else {}
    chart_payload = payload.get("chartPayload") if isinstance(payload.get("chartPayload"), dict) else {}
    title = str(
        payload.get("title")
        or props.get("title")
        or chart_payload.get("title")
        or payload.get("name")
        or run.selected.label
        or "chart"
    ).strip()
    title = localize_chart_label(title, html_lang) or title
    item_values: list[str] = []
    items = props.get("items") if isinstance(props.get("items"), list) else []
    for item in items[:6]:
        if not isinstance(item, dict):
            continue
        item_label = str(item.get("label") or item.get("name") or "").strip()
        item_value = str(item.get("displayValue") or item.get("value") or "").strip()
        if item_label and item_value:
            item_values.append(f"{item_label} {item_value}")
    if item_values:
        if html_lang == "en":
            return plain_text_excerpt(f"{title}: " + ", ".join(item_values) + ".", limit=170)
        return plain_text_excerpt(f"{title}：" + "，".join(item_values) + "。", limit=170)
    rows: list[Any] = []
    for candidate in (payload, props, chart_payload):
        if not isinstance(candidate, dict):
            continue
        for key in ("records", "data", "rows", "items", "nodes", "points", "series"):
            value = candidate.get(key)
            if isinstance(value, list) and value:
                rows = value
                break
        if rows:
            break
    count_text = ""
    if rows:
        count_text = f"，包含 {len(rows)} 个数据项" if html_lang != "en" else f" with {len(rows)} data item(s)"
    if html_lang == "en":
        return plain_text_excerpt(
            f"{title} summarizes the visible chart data{count_text}.",
            limit=170,
        )
    return plain_text_excerpt(
        f"{title}汇总了图中可见数据{count_text}。",
        limit=170,
    )


def build_source_data_summary(run: ModuleRun, question: str, html_lang: str) -> str:
    payload = read_payload(run.payload_path)
    payload_type = str(payload.get("type") or "").strip()
    if payload_type == "yahoo-data-unavailable":
        symbol = str(payload.get("symbol") or run.code or "").strip()
        period = str(payload.get("requestedPeriodType") or "requested").strip()
        metric = str(payload.get("metricLabel") or payload.get("metric") or "financial field").strip()
        if html_lang == "en":
            return f"Yahoo Finance did not provide {symbol} {period} {metric}."
        period_label = {"quarterly": "季度", "annual": "年度"}.get(period, period)
        metric_label_text = {
            "Total revenue": "营收",
            "Net income": "净利润",
            "Operating income": "营业利润",
            "Gross profit": "毛利润",
        }.get(metric, metric)
        return f"Yahoo Finance 未提供 {symbol} 的{period_label}{metric_label_text}数据。"
    if payload_type in {"ainvest-news-search", "ainvest-video-search", "external-info-search"}:
        articles = payload.get("articles") if isinstance(payload.get("articles"), list) else []
        direct_answer = str(payload.get("answer") or "").strip()
        if payload_type == "ainvest-video-search":
            source_name = "AInvest Videos"
        elif payload_type == "ainvest-news-search":
            source_name = "AInvest News"
        else:
            source_name = localized_kimi_search_label(html_lang) if is_kimi_external_payload(payload) else "External Info Search"
        if payload_type == "external-info-search" and direct_answer:
            return plain_text_excerpt(f"{source_name}：{direct_answer}", limit=170)
        if articles:
            bits = []
            for item in articles[:3]:
                if not isinstance(item, dict):
                    continue
                date = str(item.get("published_date") or str(item.get("published_at") or "")[:10]).strip()
                title = str(item.get("title") or "").strip()
                if title:
                    bits.append(f"{date + ' · ' if date else ''}{title}")
            if bits:
                if html_lang == "en":
                    return plain_text_excerpt(f"{source_name} returned {len(articles)} relevant result(s): " + " | ".join(bits), limit=170)
                return plain_text_excerpt(f"{source_name} 返回 {len(articles)} 条相关结果：" + "；".join(bits), limit=170)
        return f"{source_name} did not return matching results for this query."
    if run.selected.filename == "kline.py" and payload_type == "kline":
        rows = [row for row in payload.get("data", []) if isinstance(row, dict)]
        if rows:
            latest = rows[-1]
            latest_date = format_kline_time(latest.get("time"))
            source = str(payload.get("source") or "").upper() or "AInvest"
            period = str(payload.get("period") or "").upper()
            open_ = to_float(latest.get("open"))
            high = to_float(latest.get("high"))
            low = to_float(latest.get("low"))
            close = to_float(latest.get("close"))
            if html_lang == "en":
                parts = [f"Source: {source}", f"Period: {period}", f"Latest bar: {latest_date}"]
                price_bits = []
                if open_ is not None:
                    price_bits.append(f"O {format_source_price(open_)}")
                if high is not None:
                    price_bits.append(f"H {format_source_price(high)}")
                if low is not None:
                    price_bits.append(f"L {format_source_price(low)}")
                if close is not None:
                    price_bits.append(f"C {format_source_price(close)}")
                if price_bits:
                    parts.append(" · ".join(price_bits))
                return " · ".join(parts)
            return plain_text_excerpt(
                f"数据源 {source}，周期 {period}，最新数据截至 {latest_date}，开盘 {format_source_price(open_)}，最高 {format_source_price(high)}，最低 {format_source_price(low)}，收盘 {format_source_price(close)}。",
                limit=160,
            )
    if payload_type == "key-stats":
        fields = payload.get("fields") if isinstance(payload.get("fields"), dict) else {}
        ranges = payload.get("ranges") if isinstance(payload.get("ranges"), dict) else {}
        stats = payload.get("stats") if isinstance(payload.get("stats"), list) else []
        display_values = {
            str(item.get("key")): str(item.get("value"))
            for item in stats
            if isinstance(item, dict) and item.get("key") and item.get("value") not in (None, "")
        }
        current = fields.get("current")
        day_range = ranges.get("day") if isinstance(ranges.get("day"), dict) else {}
        week52 = ranges.get("week52") if isinstance(ranges.get("week52"), dict) else {}
        bits: list[str] = []
        if current is not None:
            bits.append(f"当前价 {format_source_price(current)}")
        if day_range:
            bits.append(f"日内区间 {day_range.get('lowLabel') or format_source_price(day_range.get('low'))}-{day_range.get('highLabel') or format_source_price(day_range.get('high'))}")
        if week52:
            bits.append(f"52周区间 {week52.get('lowLabel') or format_source_price(week52.get('low'))}-{week52.get('highLabel') or format_source_price(week52.get('high'))}")
        for key, label in (("marketCap", "市值"), ("peTtm", "P/E(TTM)"), ("beta", "Beta"), ("turnover", "成交额")):
            value = fields.get(key)
            if value is not None:
                bits.append(f"{label} {display_values.get(key) or format_source_price(value)}")
        if bits:
            if html_lang == "en":
                return plain_text_excerpt("Key snapshot: " + "; ".join(bits) + ".", limit=170)
            return plain_text_excerpt("关键快照：" + "；".join(bits) + "。", limit=170)
    if payload_type in {"income-statement", "balance-sheet", "cash-flow"}:
        view_name, view = select_latest_view(payload)
        if view:
            records = sorted_records(view_records(view))
            if records:
                latest = records[-1]
                values = latest.get("values") if isinstance(latest.get("values"), dict) else {}
                specs = metric_specs(payload)
                key_bits = []
                for key in preferred_metric_keys(payload, values)[:3]:
                    value = values.get(key)
                    if value is not None:
                        key_bits.append(f"{metric_label(specs, key)} {format_statement_metric_value(value, specs.get(key), key)}")
                if html_lang == "en":
                    prefix = f"{payload.get('title') or run.selected.label} · {(view.get('label') or view_name)} · Latest: {record_label(latest)}"
                    return plain_text_excerpt(prefix + (" · " + " · ".join(key_bits) if key_bits else ""), limit=170)
                prefix = f"{payload.get('title') or run.selected.label}，视图 {(view.get('label') or view_name)}，最新数据 {record_label(latest)}"
                return plain_text_excerpt(prefix + ("，" + "，".join(key_bits) if key_bits else ""), limit=170)
    if payload_type == "key-financial-indicators":
        view_name, view = select_latest_view(payload)
        if view:
            records = sorted_records(view_records(view))
            if records:
                latest = records[-1]
                values = latest.get("values") if isinstance(latest.get("values"), dict) else {}
                specs = metric_specs(payload)
                bits = []
                for key in preferred_metric_keys(payload, values)[:4]:
                    value = values.get(key)
                    if value is not None:
                        bits.append(f"{metric_label(specs, key)} {format_metric_value(value, specs.get(key))}")
                return plain_text_excerpt(" · ".join([record_label(latest), *bits]), limit=170)
    if payload_type in {"payout-ratio", "dividend-yield"}:
        records = [row for row in payload.get("records", []) if isinstance(row, dict)]
        if records:
            latest = records[-1]
            latest_label = str(latest.get("label") or latest.get("year") or "latest period")
            net_income = to_float(latest.get("parent_holder_net_profit"))
            dividend_cash = to_float(latest.get("dividend_cash_total"))
            payout_ratio = to_float(latest.get("pay_out_ratio"))
            dividend_yield = to_float(latest.get("dividend_yield"))
            if html_lang == "en":
                bits = [f"Latest period: {latest_label}"]
                if net_income is not None:
                    bits.append(f"net income {format_statement_metric_value(net_income, {'unit': 'B USD'}, 'parent_holder_net_profit')}")
                if dividend_cash is not None:
                    bits.append(f"cash dividends {format_statement_metric_value(dividend_cash, {'unit': 'B USD'}, 'dividend_cash_total')}")
                if payout_ratio is not None:
                    bits.append(f"payout ratio {payout_ratio * 100:.2f}%")
                if dividend_yield is not None:
                    bits.append(f"dividend yield {dividend_yield * 100:.2f}%")
                return plain_text_excerpt("Source data shows " + ", ".join(bits) + ".", limit=170)
            bits = [f"最新期为 {latest_label}"]
            if net_income is not None:
                bits.append(f"归母净利润 {format_statement_metric_value(net_income, {'unit': 'B USD'}, 'parent_holder_net_profit')}")
            if dividend_cash is not None:
                bits.append(f"现金分红总额 {format_statement_metric_value(dividend_cash, {'unit': 'B USD'}, 'dividend_cash_total')}")
            if payout_ratio is not None:
                bits.append(f"派息率 {payout_ratio * 100:.2f}%")
            if dividend_yield is not None:
                bits.append(f"股息率 {dividend_yield * 100:.2f}%")
            return plain_text_excerpt("，".join(bits) + "。", limit=170)
    if run.selected.filename in GENERIC_CHART_PAYLOAD_SCRIPTS:
        return generic_chart_source_summary(payload, run, html_lang)
    records = [row for row in payload.get("records", []) if isinstance(row, dict)]
    if records:
        latest = records[-1]
        latest_label = str(latest.get("label") or latest.get("year") or latest.get("date") or "latest period")
        numeric_bits: list[str] = []
        for key, value in latest.items():
            if key in {"label", "year", "date"}:
                continue
            numeric = to_float(value)
            if numeric is None:
                continue
            label = key.replace("_", " ")
            if 0 <= numeric <= 1 and ("ratio" in key or "yield" in key or "margin" in key):
                numeric_bits.append(f"{label} {numeric * 100:.2f}%")
            else:
                numeric_bits.append(f"{label} {format_source_price(numeric)}")
            if len(numeric_bits) >= 3:
                break
        if numeric_bits:
            if html_lang == "en":
                return plain_text_excerpt(f"Latest period: {latest_label}. " + ", ".join(numeric_bits) + ".", limit=170)
            return plain_text_excerpt(f"最新期：{latest_label}，" + "，".join(numeric_bits) + "。", limit=170)
    facts = extract_payload_facts(run.payload_path)
    if facts:
        return plain_text_excerpt(" ".join(facts[:2]), limit=170)
    chart_bits = extract_chart_summary_parts(run.html_path)
    if chart_bits:
        return plain_text_excerpt(" · ".join(chart_bits[:4]), limit=170)
    return "Open the AInvest source page for the underlying dataset."


def format_source_price(value: Any) -> str:
    numeric = to_float(value)
    if numeric is None:
        return str(value)
    amount = abs(numeric)
    if amount >= 1000:
        digits = 2
    elif amount >= 100:
        digits = 3
    elif amount >= 1:
        digits = 4
    elif amount >= 0.01:
        digits = 6
    else:
        digits = 8
    return f"{numeric:.{digits}f}"


def append_inline_source_to_paragraphs(module_paragraphs: str, source_html: str) -> str:
    if not source_html:
        return module_paragraphs
    return re.sub(r"</p>\s*$", lambda _match: source_html + "</p>", module_paragraphs, count=1, flags=re.S)


def has_text_only_nonvisual_result(runs: list[ModuleRun]) -> bool:
    return any(
        run.selected.filename in NON_DISPLAY_RUN_SCRIPTS
        or (
            run.selected.filename == "yahoo_data.py"
            and read_payload(run.payload_path).get("type") == "yahoo-data-unavailable"
        )
        for run in runs
    )


def report_display_runs(runs: list[ModuleRun]) -> list[ModuleRun]:
    display_candidates = [
        run
        for run in runs
        if run.selected.filename not in NON_DISPLAY_RUN_SCRIPTS
        and not is_empty_placeholder_chart_run(run)
        and read_payload(run.payload_path).get("type") != "yahoo-data-unavailable"
    ]
    if not any(run.selected.filename not in SEARCH_SCRIPTS for run in display_candidates):
        return display_candidates
    hideable_source_scripts = {"yahoo_data.py"}
    hidden_source_indexes: set[int] = set()
    for index, run in enumerate(display_candidates):
        if run.selected.filename in hideable_source_scripts:
            has_downstream_visualizer = any(
                candidate.selected.filename not in SEARCH_SCRIPTS
                and candidate.selected.filename not in hideable_source_scripts
                for candidate in display_candidates[index + 1 :]
            )
            if has_downstream_visualizer:
                hidden_source_indexes.add(index)
    visible_runs = [run for index, run in enumerate(display_candidates) if index not in hidden_source_indexes]
    return sorted(
        visible_runs,
        key=lambda run: (
            1 if run.selected.filename in SEARCH_SCRIPTS else 0,
            visible_runs.index(run),
        ),
    )


def merge_repair_runs_with_preserved_logic_charts(
    original_runs: list[ModuleRun],
    repair_runs: list[ModuleRun],
) -> list[ModuleRun]:
    repair_non_empty_scripts = {
        run.selected.filename
        for run in repair_runs
        if not is_empty_placeholder_chart_run(run)
    }
    preserved = [
        run
        for run in original_runs
        if run.selected.filename in LOGIC_CHART_SCRIPTS
        and not is_empty_placeholder_chart_run(run)
        and run.selected.filename not in repair_non_empty_scripts
    ]
    return [*repair_runs, *preserved]


def compact_module_supporting_note(
    text: str,
    overview: str,
    run: ModuleRun,
    question: str,
    all_runs: list[ModuleRun] | None = None,
) -> str:
    cleaned = clean_advisor_view_prefixes(str(text or "").strip())
    if not cleaned:
        return rich_business_module_advisor_note(run, question)
    compact_len = len(re.sub(r"\s+", "", cleaned))
    if run.selected.filename == VIDEO_SEARCH_SCRIPT:
        if compact_len < 120 or module_note_is_process_filler(cleaned) or module_note_is_meta_filler(cleaned):
            return compact_video_advisor_note(run, question, html_lang_for_question(question), all_runs)
    # Module text should come from the interpretation model. Older builds replaced
    # short model text with deterministic rich_* templates, which made reports read
    # like stitched rules instead of generated analysis.
    if module_note_is_process_filler(cleaned):
        return rich_business_module_advisor_note(run, question)
    if module_note_is_meta_filler(cleaned):
        return rich_business_module_advisor_note(run, question)
    paragraphs = [part.strip() for part in re.split(r"\n{2,}|\n", cleaned) if part.strip()]
    first = paragraphs[0] if paragraphs else cleaned
    if len(first) > 360:
        first = plain_text_excerpt(first, 360)
    overlap_source = re.sub(r"\s+", "", overview or "")
    overlap_candidate = re.sub(r"\s+", "", first)
    if overlap_candidate and len(overlap_candidate) > 40 and overlap_candidate in overlap_source:
        return ""
    if len(paragraphs) > 1 or len(cleaned) > 420:
        return first
    return cleaned


def module_note_is_process_filler(text: str) -> bool:
    normalized = re.sub(r"\s+", " ", text).strip().lower()
    process_terms = (
        "搜索到",
        "检索到",
        "搜尋到",
        "搜索结果",
        "檢索結果",
        "返回结果",
        "返回了",
        "相关视频",
        "相關影片",
        "视频搜索",
        "影片搜尋",
        "补充验证",
        "補充驗證",
        "强化长期增长逻辑",
        "強化長期增長邏輯",
        "无有效",
        "無有效",
        "没有有效",
        "沒有有效",
        "未获取到有效",
        "未獲取到有效",
        "暂不补充",
        "暫不補充",
        "无法补充",
        "無法補充",
        "没有更多数据",
        "沒有更多資料",
        "这项数据应作为判断趋势是否延续",
        "這項資料應作為判斷趨勢是否延續",
        "最新依据是",
        "最新依據是",
        "数据摘要",
        "資料摘要",
        "暂无相关新闻",
        "暫無相關新聞",
        "没有相关新闻",
        "沒有相關新聞",
        "新闻数据",
        "新聞資料",
        "aInvest videos",
        "search returned",
        "search results",
        "relevant video",
        "video cards",
        "no useful video",
        "no valid video",
        "cannot supplement",
    )
    return any(term.lower() in normalized for term in process_terms)


def module_note_is_meta_filler(text: str) -> bool:
    normalized = re.sub(r"\s+", " ", text).strip().lower()
    filler_terms = (
        "本模组",
        "本模組",
        "本模块",
        "本模塊",
        "本图表",
        "本圖表",
        "基础框架",
        "基礎框架",
        "提供基础",
        "提供基礎",
        "this module",
        "this chart",
        "this component",
        "provides a foundation",
    )
    return any(term.lower() in normalized for term in filler_terms)


