def rich_business_module_advisor_note(run: ModuleRun, question: str) -> str:
    html_lang = html_lang_for_question(question)
    if html_lang not in {"zh-CN", "zh-Hant"}:
        return ""
    payload = read_payload(run.payload_path)
    if not payload:
        return ""
    script = run.selected.filename
    if script == "kline.py" or payload.get("type") == "kline":
        note = rich_kline_advisor_note(payload)
    elif script == "key_stats.py" or payload.get("type") == "key-stats":
        note = rich_key_stats_advisor_note(payload)
    elif script == "revenue_expenses.py" or payload.get("type") == "revenue-expenses":
        note = rich_revenue_expenses_advisor_note(payload)
    elif script == "cash_flow.py" or payload.get("type") == "cash-flow":
        note = rich_cash_flow_advisor_note(payload)
    elif script == "key_financial_indicators.py" or payload.get("type") == "key-financial-indicators":
        note = rich_key_financial_indicators_advisor_note(payload)
    elif script == "dividend_yield.py" or payload.get("type") == "dividend-yield":
        note = rich_dividend_yield_advisor_note(payload)
    elif script == "capital_structure.py" or payload.get("type") == "waterfall":
        note = rich_capital_structure_advisor_note(payload)
    elif script == "revenue_sources.py" or payload_source_provider(payload) == "AInvest financial_reports_visual/usa/v1/sankey":
        note = rich_revenue_sources_advisor_note(payload)
    elif script == "revenue_geography.py" or payload_source_provider(payload) == "AInvest abroad/operate/v2/lastest":
        note = rich_revenue_geography_advisor_note(payload)
    elif script == "balance_sheet.py" or payload.get("type") == "balance-sheet":
        note = rich_balance_sheet_advisor_note(payload)
    elif script == "valuation.py" or str(payload.get("title") or "").lower().endswith("valuation"):
        note = rich_valuation_advisor_note(payload)
    elif script in {"investment_rating.py", "fundamental_investment_rating.py"} or payload.get("type") in {"investment-rating", "fundamental-investment-rating"}:
        note = rich_investment_rating_advisor_note(payload)
    elif script == "revenue_estimate.py" or payload.get("type") == "revenue-estimate":
        note = rich_revenue_estimate_advisor_note(payload)
    elif script == "eps_estimate.py" or str(payload.get("title") or payload.get("name") or "").lower() in {"earnings estimate", "收益预估", "收益預估"}:
        note = rich_eps_estimate_advisor_note(payload)
    elif script == "trade_flow.py" or payload.get("type") == "trade-flow":
        note = rich_trade_flow_advisor_note(payload)
    elif script == "wall_street_consensus.py" or payload.get("type") == "wall-street-consensus":
        note = rich_wall_street_consensus_advisor_note(payload)
    else:
        note = ""
    if html_lang == "zh-Hant" and note:
        return to_traditional_chinese(note)
    return note


def rich_dividend_yield_advisor_note(payload: dict[str, Any]) -> str:
    records = [row for row in payload.get("records", []) if isinstance(row, dict)]
    if not records:
        return ""
    records = sorted(records, key=lambda row: str(row.get("date") or row.get("label") or ""))
    latest = records[-1]
    previous = records[-2] if len(records) >= 2 else None
    first = records[0]
    code = str(payload.get("code") or ((payload.get("source") or {}).get("symbol") if isinstance(payload.get("source"), dict) else "") or "").upper()
    latest_label = str(latest.get("label") or latest.get("date") or "最新期")
    latest_yield = to_float(latest.get("dividend_yield_ratio") or latest.get("dividend_yield"))
    previous_yield = to_float(previous.get("dividend_yield_ratio") or previous.get("dividend_yield")) if previous else None
    first_yield = to_float(first.get("dividend_yield_ratio") or first.get("dividend_yield"))
    highest = max(records, key=lambda row: to_float(row.get("dividend_yield_ratio") or row.get("dividend_yield")) or -10**9)
    highest_yield = to_float(highest.get("dividend_yield_ratio") or highest.get("dividend_yield"))

    def pct(value: float | None) -> str:
        return "--" if value is None else f"{value * 100:.2f}%"

    day_change = ""
    if latest_yield is not None and previous_yield is not None:
        diff = (latest_yield - previous_yield) * 100
        day_change = f"，较上一数据点{'上升' if diff >= 0 else '下降'}{abs(diff):.2f}个百分点"
    window_change = ""
    if latest_yield is not None and first_yield is not None:
        diff = (latest_yield - first_yield) * 100
        window_change = f"，较区间起点{'上升' if diff >= 0 else '下降'}{abs(diff):.2f}个百分点"
    high_text = ""
    if highest_yield is not None:
        high_text = f"，区间高点为{pct(highest_yield)}（{highest.get('label') or highest.get('date') or '高点'}）"
    return (
        f"{code or '该标的'}股息率最新数据截至{latest_label}，当前约{pct(latest_yield)}{day_change}{window_change}{high_text}。"
        "从图形右端看，股息率仍处低位并延续缓慢回落，说明股东现金分红收益不是当前回报的主要来源，市场更依赖盈利增长、回购和估值变化来定价。"
        "对投资判断而言，这组数据更适合衡量防御属性：若股价继续上行而股息率走低，收益逻辑会更偏资本利得；若基本面转弱，低股息缓冲对回撤的保护有限。"
    )


def rich_capital_structure_advisor_note(payload: dict[str, Any]) -> str:
    props = payload.get("props") if isinstance(payload.get("props"), dict) else {}
    source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
    items = [item for item in props.get("items", []) if isinstance(item, dict)]
    if not items:
        return ""
    code = str(source.get("symbol") or payload.get("code") or "").upper()

    def item_by_name(*names: str) -> dict[str, Any]:
        for item in items:
            label = str(item.get("label") or "").lower()
            if any(name.lower() in label for name in names):
                return item
        return {}

    market = item_by_name("市值", "market")
    debt = item_by_name("负债", "負債", "debt")
    cash = item_by_name("现金", "現金", "cash")
    enterprise = item_by_name("企业价值", "企業價值", "enterprise")
    market_value = to_float(market.get("value"))
    debt_value = to_float(debt.get("value"))
    cash_value = abs(to_float(cash.get("value")) or 0) if cash else None
    enterprise_value = to_float(enterprise.get("value"))
    debt_ratio = debt_value / market_value * 100 if market_value and debt_value is not None else None
    cash_ratio = cash_value / market_value * 100 if market_value and cash_value is not None else None
    spread = enterprise_value - market_value if enterprise_value is not None and market_value is not None else None
    spread_text = f"，企业价值较市值高约{_format_billions_abs(spread)}" if spread is not None else ""
    return (
        f"{code or '该标的'}资本结构快照显示，市值约{market.get('displayValue') or _format_billions_abs(market_value)}，"
        f"负债约{debt.get('displayValue') or _format_billions_abs(debt_value)}，现金等价物约{cash.get('displayValue') or _format_billions_abs(cash_value)}，"
        f"企业价值约{enterprise.get('displayValue') or _format_billions_abs(enterprise_value)}{spread_text}。"
        f"按图中口径，负债约占市值{debt_ratio:.2f}%" if debt_ratio is not None else ""
    ) + (
        f"，现金约占市值{cash_ratio:.2f}%" if cash_ratio is not None else ""
    ) + (
        "，杠杆相对市值规模不高。对投资判断而言，这意味着资产负债表不是主要压力点，后续更关键的是现金储备、回购和AI投入能否继续转化为利润与自由现金流，而不是单纯依赖加杠杆推动估值扩张。"
    )


def _format_billions_abs(value: Any) -> str:
    numeric = to_float(value)
    if numeric is None:
        return "--"
    numeric = abs(numeric)
    if numeric >= 1_000:
        return f"{numeric / 1_000:.2f} T"
    return f"{numeric:.2f} B"


def rich_kline_advisor_note(payload: dict[str, Any]) -> str:
    rows = [row for row in payload.get("data", []) if isinstance(row, dict)]
    if not rows:
        return ""
    latest = rows[-1]
    first = rows[0]
    symbol = str(payload.get("symbol") or payload.get("code") or "").upper()
    period = str(payload.get("period") or "")
    latest_date = format_kline_time(latest.get("time"))
    close = to_float(latest.get("close"))
    first_close = to_float(first.get("close"))
    change_pct = to_float(latest.get("changePct"))
    volume = compact_money(latest.get("volume"))
    trend_pct = pct_change(first_close, close) if first_close is not None and close is not None else None
    direction = "上涨" if (change_pct or 0) >= 0 else "下跌"
    trend_text = f"，区间累计变化约{format_percent_value(trend_pct)}" if trend_pct is not None else ""
    close_text = f"{close:.2f}" if close is not None else "--"
    pct_text = f"{abs(change_pct):.2f}%" if change_pct is not None else "--"
    return (
        f"{symbol or '该标的'}短线仍处强趋势后的高位震荡阶段：{period}周期最新数据截至{latest_date}，收盘价{close_text}美元，"
        f"单日{direction}{pct_text}{trend_text}。从图形看，价格仍处在前期快速上行后的高位震荡区，均线系统尚未完全转弱，"
        f"说明中期多头结构没有被破坏；但最新K线回落且成交量约{volume}，提示高位分歧正在放大。从投资分析看，后续重点看股价能否重新站稳短期均线并放量突破，"
        "否则应把它视为强趋势中的波动修正，而不是无风险追涨信号。"
    )


def rich_key_stats_advisor_note(payload: dict[str, Any]) -> str:
    fields = payload.get("fields") if isinstance(payload.get("fields"), dict) else {}
    stats = payload.get("stats") if isinstance(payload.get("stats"), list) else []
    display = {
        str(item.get("key")): str(item.get("value"))
        for item in stats
        if isinstance(item, dict) and item.get("key") and item.get("value") not in (None, "")
    }
    code = str(payload.get("code") or "").upper()
    current = display.get("current") or format_source_price(fields.get("current"))
    market_cap = display.get("marketCap") or compact_money(fields.get("marketCap"))
    pe_ttm = display.get("peTtm") or format_source_price(fields.get("peTtm"))
    pe_dyn = display.get("peDyn") or format_source_price(fields.get("peDyn"))
    turnover = display.get("turnover") or compact_money(fields.get("turnover"))
    range_pct = display.get("rangePercent") or format_percent_value(to_float(fields.get("rangePercent")) or 0)
    week52_low = fields.get("week52Low")
    week52_high = fields.get("week52High")
    current_num = to_float(fields.get("current"))
    position = None
    if current_num is not None and to_float(week52_low) is not None and to_float(week52_high) is not None and to_float(week52_high) != to_float(week52_low):
        position = (current_num - float(week52_low)) / (float(week52_high) - float(week52_low)) * 100
    position_text = f"，处于52周区间约{position:.0f}%分位" if position is not None else ""
    return (
        f"{code or '该标的'}当前的定价已经包含较高成长预期：最新价约{current}美元{position_text}，市值约{market_cap}，"
        f"TTM市盈率{pe_ttm}倍、动态市盈率{pe_dyn}倍，成交额约{turnover}，日内振幅{range_pct}。这些数据说明市场仍愿意给英伟达较高成长溢价，"
        "但价格已经不便宜，短线波动也明显放大。从投资分析看，它更适合作为“基本面强、估值要求也高”的跟踪标的，后续需要用业绩指引、资金流和技术走势共同验证估值能否继续消化。"
    )


def rich_revenue_expenses_advisor_note(payload: dict[str, Any]) -> str:
    items = [item for item in payload.get("items", []) if isinstance(item, dict)]
    if not items:
        return ""
    latest = items[-1]
    subject = latest.get("subject") if isinstance(latest.get("subject"), dict) else {}
    year = subject.get("year") or record_label(subject)
    revenue = latest.get("operating_income_total") if isinstance(latest.get("operating_income_total"), dict) else {}
    gross = latest.get("gross_profit") if isinstance(latest.get("gross_profit"), dict) else {}
    op_profit = latest.get("operating_profit") if isinstance(latest.get("operating_profit"), dict) else {}
    net = latest.get("net_profit") if isinstance(latest.get("net_profit"), dict) else {}
    rd = latest.get("research_development_expenses") if isinstance(latest.get("research_development_expenses"), dict) else {}
    projects = latest.get("projects") if isinstance(latest.get("projects"), list) else []
    top_project = next((item for item in projects if isinstance(item, dict)), {})
    revenue_text = format_usd_billions(revenue.get("value"))
    gross_text = format_usd_billions(gross.get("value"))
    op_text = format_usd_billions(op_profit.get("value"))
    net_text = format_usd_billions(net.get("value"))
    rd_text = format_usd_billions(rd.get("value"))
    top_name = str(top_project.get("name") or "核心业务")
    top_value = format_usd_billions(top_project.get("value"))
    top_yoy = format_yoy_percent(top_project.get("yoy"))
    return (
        f"AI需求已经实质性转化为英伟达的收入和利润弹性：{year}财年收入{revenue_text}美元、毛利{gross_text}美元、营业利润{op_text}美元、"
        f"净利润{net_text}美元，其中{top_name}收入{top_value}美元，同比{top_yoy}，仍是增长主轴；研发投入{rd_text}美元，说明公司继续用技术投入巩固壁垒。"
        "从投资分析看，这组数据支持长期基本面主线，但也意味着估值对增长延续性很敏感；若后续数据中心增速、毛利率或研发转化效率下滑，股价回撤风险会被放大。"
    )


def payload_source_provider(payload: dict[str, Any]) -> str:
    source = payload.get("source")
    if isinstance(source, dict):
        return str(source.get("provider") or "")
    return ""


def rich_cash_flow_advisor_note(payload: dict[str, Any]) -> str:
    view_name, view = select_default_or_latest_view(payload)
    if not view:
        return ""
    records = sorted_records(view_records(view))
    if not records:
        return ""
    latest = records[-1]
    previous = records[-2] if len(records) >= 2 else None
    values = latest.get("values") if isinstance(latest.get("values"), dict) else {}
    lines = latest.get("lines") if isinstance(latest.get("lines"), dict) else {}
    waterfall_rows = view.get("waterfallRecords") if isinstance(view.get("waterfallRecords"), list) else []
    waterfall = waterfall_rows[-1] if waterfall_rows else {}
    waterfall_values = waterfall.get("values") if isinstance(waterfall.get("values"), dict) else {}
    code = str(payload.get("code") or "").upper()
    label = record_label(latest)
    operating = format_billions(values.get("act_cash_flow_net"))
    investing = format_billions(waterfall_values.get("invest_cash_flow_net", values.get("invest_cash_flow_net")))
    financing = format_billions(waterfall_values.get("financing_cash_flow_net", values.get("financing_cash_flow_net")))
    net_cash = format_billions(waterfall_values.get("cash_equivalents_net_addition", values.get("cash_equivalents_net_addition")))
    operating_yoy = lines.get("yoy_act_cash_flow_net")
    previous_operating = None
    if isinstance(previous, dict):
        prev_values = previous.get("values") if isinstance(previous.get("values"), dict) else {}
        previous_operating = prev_values.get("act_cash_flow_net")
    operating_change = pct_change(to_float(previous_operating), to_float(values.get("act_cash_flow_net"))) if previous_operating is not None else None
    growth_text = ""
    if operating_yoy is not None:
        growth_text = f"，同比{format_percent(operating_yoy)}"
    elif operating_change is not None:
        growth_text = f"，较上一期{format_percent_value(operating_change)}"
    view_label = str(view.get("label") or view_name)
    return (
        f"{code or '该标的'}现金流质量总体较强：{view_label}视图下最新期间{label}经营现金流约{operating}美元{growth_text}，"
        f"说明主营业务仍具备较强自我造血能力。同期投资现金流约{investing}美元，融资现金流约{financing}美元，净现金变动约{net_cash}美元，"
        "需要结合资本开支、回购、债务和现金储备一起看，而不是只看净现金单项。从投资分析看，经营现金流能否持续覆盖AI、云基础设施和股东回报，是判断增长质量的关键；"
        "若经营现金流继续扩张且投资支出能转化为收入，估值支撑会更稳，反之则会放大自由现金流与估值压力。"
    )


def rich_key_financial_indicators_advisor_note(payload: dict[str, Any]) -> str:
    view_name, view = select_default_or_latest_view(payload)
    if not view:
        return ""
    records = sorted_records(view_records(view))
    if not records:
        return ""
    latest = records[-1]
    previous = records[-2] if len(records) >= 2 else None
    values = latest.get("values") if isinstance(latest.get("values"), dict) else {}
    yoy = latest.get("yoy") if isinstance(latest.get("yoy"), dict) else {}
    prev_values = previous.get("values") if isinstance(previous, dict) and isinstance(previous.get("values"), dict) else {}
    code = str(payload.get("code") or "").upper()
    label = record_label(latest)
    eps = values.get("balanced_eps")
    roe = values.get("index_weighted_avg_roe")
    roa = values.get("total_assets_net_ratio")
    margin = values.get("sale_net_interest_ratio")
    debt = values.get("assets_debt_ratio")
    current_ratio = values.get("current_ratio")
    eps_change = pct_change(to_float(prev_values.get("balanced_eps")), to_float(eps)) if prev_values else None
    eps_change_text = f"，较上一期{format_percent_value(eps_change)}" if eps_change is not None else ""
    eps_text = format_source_price(eps) if eps is not None else "--"
    current_ratio_text = format_source_price(current_ratio) if current_ratio is not None else "--"
    roe_text = format_plain_percent_value(roe)
    roa_text = format_plain_percent_value(roa)
    margin_text = format_plain_percent_value(margin)
    debt_text = format_plain_percent_value(debt)
    return (
        f"{code or '该标的'}的关键财务指标显示盈利效率仍处较好区间：最新期间{label}每股收益约{eps_text}{eps_change_text}，"
        f"ROE约{roe_text}、ROA约{roa_text}，净利率约{margin_text}，说明利润转化效率对估值仍有支撑。流动比率约{current_ratio_text}、"
        f"资产负债率约{debt_text}，反映短期偿债压力相对可控。从投资分析看，这组指标更适合用来验证增长质量："
        "若EPS、ROE和净利率同步改善，说明业务扩张没有明显牺牲盈利能力；若收入增长但效率指标回落，则要警惕估值消化压力。"
    )


def format_plain_percent_value(value: Any) -> str:
    numeric = to_float(value)
    if numeric is None:
        return "--"
    return f"{numeric:.2f}%"


def format_score_two_decimals(value: Any) -> str:
    numeric = to_float(value)
    if numeric is None:
        return "--"
    return f"{numeric:.2f}"


def normalize_score_text(value: str) -> str:
    def replace_score(match: re.Match[str]) -> str:
        try:
            return f"{float(match.group(1)):.2f}/10"
        except ValueError:
            return match.group(0)

    return re.sub(r"(\d+(?:\.\d+)?)\s*/\s*10", replace_score, value)


def rich_revenue_sources_advisor_note(payload: dict[str, Any]) -> str:
    props = payload.get("props") if isinstance(payload.get("props"), dict) else {}
    source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
    items = [item for item in props.get("items", []) if isinstance(item, dict)]
    if not items:
        return ""
    code = str(source.get("symbol") or payload.get("code") or "").upper()
    period = props.get("badgeLabel") or record_label(source.get("period") if isinstance(source.get("period"), dict) else {})
    total = to_float(source.get("reportedTotalRevenue"))
    sorted_items = sorted(items, key=lambda item: to_float(item.get("value")) or 0, reverse=True)
    top = sorted_items[0]
    second = sorted_items[1] if len(sorted_items) > 1 else {}
    top_value = to_float(top.get("value")) or 0
    second_value = to_float(second.get("value")) or 0
    total_positive = sum((to_float(item.get("value")) or 0) for item in items)
    top_share = top_value / total_positive if total_positive else None
    second_share = second_value / total_positive if total_positive else None
    total_text = f"{total / 1000:.2f}B" if total is not None else f"{total_positive / 1000:.2f}B"
    return (
        f"{code or '该标的'}收入结构仍以核心业务为主：{period}总营收约{total_text}美元，"
        f"{top.get('label') or '第一大业务'}贡献约{top_value / 1000:.2f}B美元，占比{format_plain_percent_value(top_share * 100) if top_share is not None else '--'}；"
        f"{second.get('label') or '第二大业务'}贡献约{second_value / 1000:.2f}B美元，占比{format_plain_percent_value(second_share * 100) if second_share is not None else '--'}。"
        "这说明公司当前增长基础仍主要来自成熟业务，同时新增长曲线的占比变化会直接影响中长期估值弹性。从投资分析看，应关注收入集中度是否带来抗周期能力，"
        "以及云、AI相关业务能否持续提升占比；如果第二增长曲线加速放量，估值逻辑会更健康，反之则更依赖核心业务维持高利润率。"
    )


def rich_revenue_geography_advisor_note(payload: dict[str, Any]) -> str:
    props = payload.get("props") if isinstance(payload.get("props"), dict) else {}
    source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
    items = [item for item in props.get("items", []) if isinstance(item, dict)]
    if not items:
        return ""
    code = str(source.get("symbol") or payload.get("code") or "").upper()
    period_info = source.get("period") if isinstance(source.get("period"), dict) else {}
    period = (props.get("badgeLabel") or record_label(period_info)) if isinstance(period_info, dict) else ""
    period_text = str(period or "最新期").replace("： ", "：").strip()
    total = to_float(source.get("reportedTotalRevenue"))
    total_positive = sum((to_float(item.get("value")) or 0) for item in items)
    denominator = total if total and total > 0 else total_positive
    sorted_items = sorted(items, key=lambda item: to_float(item.get("value")) or 0, reverse=True)
    top = sorted_items[0]
    second = sorted_items[1] if len(sorted_items) > 1 else {}
    third = sorted_items[2] if len(sorted_items) > 2 else {}

    def item_text(item: dict[str, Any]) -> str:
        value = to_float(item.get("value")) or 0
        share = value / denominator * 100 if denominator else None
        return f"{item.get('label') or '地区'}{value / 1000:.2f}B美元、占比{format_plain_percent_value(share) if share is not None else '--'}"

    top_share = (to_float(top.get("value")) or 0) / denominator * 100 if denominator else None
    concentration = (
        "收入区域集中度较高"
        if top_share is not None and top_share >= 45
        else "收入区域分布相对分散"
    )
    other_text = f"；第三大地区为{item_text(third)}" if third else ""
    return (
        f"{code or '该标的'}按地区收入拆分显示，{period_text}，总营收约{(denominator or 0) / 1000:.2f}B美元，"
        f"最大市场为{item_text(top)}，第二大地区为{item_text(second)}{other_text}。"
        f"从结构看，{concentration}，美国仍是收入核心，欧洲、中东和非洲以及亚太提供主要海外增量。"
        "这类地域拆分适合判断增长韧性和监管、汇率、宏观周期风险：若海外占比继续提升，增长来源更均衡；若美国占比进一步抬升，则业绩弹性更依赖本土广告、云和AI需求兑现。"
    )


def rich_balance_sheet_advisor_note(payload: dict[str, Any]) -> str:
    view_key, view = select_default_or_latest_view(payload)
    if not isinstance(view, dict):
        return ""
    records = sorted_records(view_records(view))
    if not records:
        return ""
    latest = records[-1]
    previous = records[-2] if len(records) >= 2 else None
    values = latest.get("values") if isinstance(latest.get("values"), dict) else {}
    lines = latest.get("lines") if isinstance(latest.get("lines"), dict) else {}
    prev_values = previous.get("values") if isinstance(previous, dict) and isinstance(previous.get("values"), dict) else {}
    code = str(payload.get("code") or "").upper()
    label = record_label(latest)
    assets = to_float(values.get("assets_total"))
    debt = to_float(values.get("total_debt"))
    equity = to_float(values.get("holder_equity_total"))
    debt_ratio = to_float(lines.get("assets_debt_ratio"))
    assets_yoy = to_float(lines.get("yoy_assets_total"))
    debt_yoy = to_float(lines.get("yoy_total_debt"))
    equity_yoy = to_float(lines.get("yoy_holder_equity_total"))
    debt_to_equity = debt / equity if debt is not None and equity else None
    asset_change = pct_change(prev_values.get("assets_total"), assets) if previous else None
    debt_change = pct_change(prev_values.get("total_debt"), debt) if previous else None
    change_text = ""
    if asset_change is not None or debt_change is not None:
        bits = []
        if asset_change is not None:
            bits.append(f"资产较上一期{format_percent_value(asset_change)}")
        if debt_change is not None:
            bits.append(f"负债较上一期{format_percent_value(debt_change)}")
        change_text = "，" + "、".join(bits)
    yoy_text = ""
    if assets_yoy is not None or debt_yoy is not None or equity_yoy is not None:
        yoy_bits = []
        if assets_yoy is not None:
            yoy_bits.append(f"资产同比{format_percent(assets_yoy)}")
        if debt_yoy is not None:
            yoy_bits.append(f"负债同比{format_percent(debt_yoy)}")
        if equity_yoy is not None:
            yoy_bits.append(f"权益同比{format_percent(equity_yoy)}")
        yoy_text = "；" + "、".join(yoy_bits)
    leverage_text = f"，负债/权益约{debt_to_equity:.2f}倍" if debt_to_equity is not None else ""
    debt_ratio_text = format_plain_percent_value(debt_ratio * 100) if debt_ratio is not None else "--"
    return (
        f"{code or '该标的'}资产负债表最新一期为{label}：总资产{format_billions(assets)}、"
        f"总负债{format_billions(debt)}、股东权益{format_billions(equity)}，资产负债率{debt_ratio_text}{leverage_text}{change_text}{yoy_text}。"
        "资产和权益同步扩张，说明规模增长仍有资本基础支撑；但负债增速也较快，若后续资产负债率继续抬升，估值对现金流和投资回报率会更敏感。"
        "投资上应重点跟踪负债率能否稳定、权益增长是否来自可持续利润留存，以及扩张后的资产能否转化为更高收入和自由现金流。"
    )


def rich_valuation_advisor_note(payload: dict[str, Any]) -> str:
    props = payload.get("props") if isinstance(payload.get("props"), dict) else {}
    source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
    code = str(source.get("symbol") or payload.get("code") or "").upper()
    base = props.get("base") if isinstance(props.get("base"), dict) else {}
    rings = [item for item in props.get("rings", []) if isinstance(item, dict)]
    metrics = [item for item in props.get("metrics", []) if isinstance(item, dict)]
    market_cap = base.get("displayValue") or props.get("centerLabel") or "--"
    def ring_display(*tokens: str) -> str:
        for item in rings:
            label = str(item.get("label") or "").lower()
            if any(token.lower() in label for token in tokens):
                return str(item.get("displayValue") or item.get("value") or "--")
        return "--"
    revenue = ring_display("revenue", "收入", "營收")
    earnings = ring_display("earning", "earnings", "盈利", "利润", "利潤")
    metric_bits = [
        f"{item.get('label')} {item.get('value')}"
        for item in metrics
        if item.get("label") and item.get("value") not in (None, "", "--")
    ]
    metric_text = "、".join(metric_bits[:3]) if metric_bits else "估值倍数暂未完整披露"
    return (
        f"{code or '该标的'}估值模块显示当前市值约{market_cap}，对应收入约{revenue}、盈利约{earnings}，"
        f"核心倍数为{metric_text}。从投资分析看，长期配置价值不能只看增长叙事，还要看市值相对收入和盈利的消化压力："
        "如果收入、利润和现金流继续同步扩张，较高估值更容易被基本面吸收；若盈利增速放缓或现金流转弱，估值压缩风险会更快体现。"
    )


