def estimate_rows(payload: dict[str, Any]) -> list[dict[str, Any]]:
    if isinstance(payload.get("data"), list):
        return [row for row in payload.get("data", []) if isinstance(row, dict)]
    views = payload.get("views") if isinstance(payload.get("views"), dict) else {}
    default_view = str(payload.get("defaultView") or "")
    view = views.get(default_view) if isinstance(views.get(default_view), dict) else None
    if view is None:
        view = next((item for item in views.values() if isinstance(item, dict)), None)
    data = view.get("data") if isinstance(view, dict) and isinstance(view.get("data"), list) else []
    return [row for row in data if isinstance(row, dict)]


def select_default_or_latest_view(payload: dict[str, Any]) -> tuple[str, dict[str, Any] | None]:
    views = payload.get("views") if isinstance(payload.get("views"), dict) else {}
    default_view = str(payload.get("defaultView") or "")
    if default_view and isinstance(views.get(default_view), dict) and view_records(views[default_view]):
        return default_view, views[default_view]
    return select_latest_view(payload)


